return {
	["tid#treasure_des_tips_40324"]="原本为神水宫圣物，承装神水圣物天一神水。世人皆以为瓶中之水才是圣物，实则不然，凡水进此瓶中皆可凝练为天一神水，若受此水滋润，可使人内力大增。",
