	["tid#treasure_name_tips_10501"]="九霄佩",
	["tid#treasure_name_tips_20401"]="沧海镜",
	["tid#treasure_name_tips_20501"]="苍龙剪",
	["tid#treasure_name_tips_30401"]="七宝莲灯",
	["tid#treasure_name_tips_30501"]="飞羽弓",
	["tid#treasure_name_tips_40601"]="幻翎扇",
	["tid#treasure_name_tips_40701"]="造化葫芦",
	["tid#HeirloomName_10401"]="混元道法",
	["tid#HeirloomName_10501"]="九霄龙腾",
	["tid#HeirloomName_20401"]="沧海升月",
	["tid#HeirloomName_20501"]="苍龙逐日",
	["tid#HeirloomName_30401"]="步步生莲",
	["tid#HeirloomName_30501"]="羽落苍穹",
	["tid#HeirloomName_40601"]="明王凝视",
	["tid#HeirloomName_40701"]="造化乾坤",
	["tid#treasure_des_tips_10401"]="以玄铁打造的宝伞，质地薄如羽翼，伞刃削铁如泥，伞体却可抵挡重弩攻击，攻守一体，是不可多得的宝器。",
	["tid#treasure_des_tips_10501"]="本是皇家赏赐给至信之人的物品，后经世代相传，由佩戴者的内力滋养，竟产生反哺主人的效果，握持手中便可贯通经脉，增长内力。",
	["tid#treasure_des_tips_20401"]="镜中可容纳沧海，持此镜者，似乎可以减慢周围的时间，使自身有更多的时间进行修炼。",
	["tid#treasure_des_tips_20501"]="此剪乃两条苍龙所化，采天地灵气，受日月精华，起在空中挺折上下，头交头如剪，尾绞尾如股，纵然是得道神仙，也难免被两段。",
	["tid#treasure_des_tips_30401"]="由七种宝石镶嵌而成，点亮宝灯可照亮天地，炫彩夺目，使敌人无从遁形，意志薄弱者甚至会被直接照射昏迷。",
	["tid#treasure_des_tips_30501"]="传说中由飞龙筋骨打造而成，装饰以珍禽尾羽，轻盈无比却需万斤之力才可开弓，擅弓者甚至可以以剑为矢，威力无穷。",
	["tid#treasure_des_tips_40601"]="由明王孔雀羽制作而成，羽扇的每一根翎都会闪烁开合，仿佛眼睛一般，对人的心魄产生迷幻的力量。",
	["tid#treasure_des_tips_40701"]="原本是道家用于存储丹药的葫芦，经年累月由丹药滋养，葫芦内竟融合了百种药材的灵气，用此葫芦饮酒犹如吸收百种丹药功力。",
	["tid#treasure_des_tips_40501"]="此物乃是蜀山道门的秘宝，持之与人相斗，信手间便可化解对手的攻击，后来天罗众围攻蜀山，致使如意流落江湖。",
