	["tid#HeirloomDes_40738"]="坦克类侠客，战斗中会获得28.5%的防御和最大血量血量提升效果，持续17秒，且每次受到伤害时，会使攻击者降低9点攻速，最多叠加4次",
	["tid#HeirloomDes_40739"]="坦克类侠客，战斗中会获得29%的防御和最大血量血量提升效果，持续17秒，且每次受到伤害时，会使攻击者降低9点攻速，最多叠加4次",
	["tid#HeirloomDes_40740"]="坦克类侠客，战斗中会获得29.5%的防御和最大血量血量提升效果，持续18秒，且每次受到伤害时，会使攻击者降低9点攻速，最多叠加4次",
	["tid#herounlockedsaying_1"]="看看是你的脑袋硬，还是我的拳头硬。",
	["tid#herounlockedsaying_2"]="都说了不要靠近我了！",
	["tid#herounlockedsaying_3"]="龙门那个女人，其实没那么坏。",
	["tid#herounlockedsaying_4"]="佛会原谅我的任性吗？",
	["tid#herounlockedsaying_5"]="越是柔情，越是凌冽。",
	["tid#herounlockedsaying_6"]="你成佛，我成了痴情人。",
	["tid#herounlockedsaying_7"]="放下屠刀，立地成佛。",
	["tid#herounlockedsaying_8"]="善根福德，百毒不侵。",
	["tid#herounlockedsaying_9"]="以德施名，灭罪生福。",
	["tid#herounlockedsaying_10"]="可怕的是机关吗？不，是用机关的人。",
	["tid#herounlockedsaying_11"]="蜀中世家纷争事，暗起云涌逍九天",
	["tid#herounlockedsaying_12"]="针翎钉棘十指牵，暴雨飞星乾坤颠。",
	["tid#herounlockedsaying_13"]="你这个罐子看起来挺不错，开个价吧。",
	["tid#herounlockedsaying_14"]="和气生财，和气才能生财！",
	["tid#herounlockedsaying_15"]="不过是一些小钱而已。",
	["tid#herounlockedsaying_16"]="任何枷锁都无法束缚我！",
	["tid#herounlockedsaying_17"]="什么？你想为我歌功颂德吗？",
	["tid#herounlockedsaying_18"]="天上天下天地之间，谁能挡我？",
	["tid#herounlockedsaying_19"]="什么时候，才能找回我内心的安宁…",
	["tid#herounlockedsaying_20"]="事到如今，我能相信的，只有我的双刀。",
	["tid#herounlockedsaying_21"]="无处可藏。",
	["tid#herounlockedsaying_22"]="雕虫小技，不足为惧。",
	["tid#herounlockedsaying_23"]="战意！在燃烧！",
	["tid#herounlockedsaying_24"]="柔羽胜刚强",
	["tid#herounlockedsaying_25"]="气沉丹田，中正安舒",
	["tid#herounlockedsaying_26"]="动中有静，静中有动。",
	["tid#herounlockedsaying_27"]="海沙来啦！",
	["tid#herounlockedsaying_28"]="多吃一点总会有好处的！",
	["tid#herounlockedsaying_29"]="小小少年，没有烦恼，充满勇气吃得饱！",
	["tid#herounlockedsaying_30"]="万物负阴而抱阳，冲气以为和。",
	["tid#herounlockedsaying_31"]="玉清玄明，随我剑来！",
	["tid#herounlockedsaying_32"]="大师兄……如今，你过得可好？",
	["tid#herounlockedsaying_33"]="与你并肩，即使路远亦不疲倦。",
	["tid#herounlockedsaying_34"]="神机，有时候真不知道你在想什么。",
	["tid#herounlockedsaying_35"]="苍天之下，我的敌人将无所遁形。",
	["tid#herounlockedsaying_36"]="宁教我负天下人！",
	["tid#herounlockedsaying_37"]="我的过去，是成就我今日的黄金台阶！",
	["tid#herounlockedsaying_38"]="想见识我的厉害么？寒冰掌还是天霜拳！",
	["tid#herounlockedsaying_39"]="文武双全？过誉了过誉了！",
	["tid#herounlockedsaying_40"]="博学，是向前看而不再胆颤。",
	["tid#herounlockedsaying_41"]="刀锋所到之处，便是家。",
	["tid#herounlockedsaying_42"]="我会碾碎你的！",
	["tid#herounlockedsaying_43"]="和大山一样强壮！",
	["tid#herounlockedsaying_44"]="需要一个私人教练吗？",
	["tid#herounlockedsaying_45"]="身似菩提，心如明镜！",
	["tid#herounlockedsaying_46"]="佛音梵影心中过，菩提叶开妙法生。",
	["tid#herounlockedsaying_47"]="悠悠青罗伞，护我渡红尘。",
	["tid#herounlockedsaying_48"]="让我看看，你是白色还是黑色。",
	["tid#herounlockedsaying_49"]="为善去恶，便是我的剑心！",
	["tid#herounlockedsaying_50"]="情丝三千丈，一剑斩红尘！",
	["tid#herounlockedsaying_51"]="雷霆雨露，俱是恩泽。",
	["tid#herounlockedsaying_52"]="风云变幻，飞沙走石。",
	["tid#herounlockedsaying_53"]="当棋对酒，论尽英雄。",
	["tid#herounlockedsaying_54"]="你有什么秘密？！",
	["tid#herounlockedsaying_55"]="罪无可赦！",
	["tid#herounlockedsaying_56"]="我发现了你的弱点。",
	["tid#herounlockedsaying_57"]="英雄？我只是遵守秩序罢了。",
	["tid#herounlockedsaying_58"]="做女英雄？我可没有那种理想。",
	["tid#herounlockedsaying_59"]="别再做无用抵抗了。",
	["tid#herounlockedsaying_60"]="野蛮行径，我的最爱。",
	["tid#herounlockedsaying_61"]="那就是我摇滚的方式！",
	["tid#herounlockedsaying_62"]="哈！我现在状态超好！",
	["tid#herounlockedsaying_63"]="战意存在我的血液当中！",
	["tid#herounlockedsaying_64"]="谨小慎微，常记在心。",
	["tid#herounlockedsaying_65"]="性命为上，尊严为次。",
	["tid#herounlockedsaying_66"]="恭默守静，伺机而动",
	["tid#herounlockedsaying_67"]="闻其声，知其形。",
	["tid#herounlockedsaying_68"]="眼见为虚，耳听为实。",
	["tid#herounlockedsaying_69"]="一曲肝肠寸断，天涯难觅知音。",
	["tid#herounlockedsaying_70"]="低眉信手弄莲蓬，惹得菡萏满塘风。",
	["tid#herounlockedsaying_71"]="看来，你也需要我的帮助？",
	["tid#herounlockedsaying_72"]="女子亦当自强，虽然也会吃些苦头。",
	["tid#herounlockedsaying_73"]="当心你的背后！",
	["tid#herounlockedsaying_74"]="藏身在暗影之中。",
	["tid#herounlockedsaying_75"]="以我所见，你已经死了。",
	["tid#herounlockedsaying_76"]="猎人还是猎物，你可知自己的处境？",
	["tid#herounlockedsaying_77"]="兽亦有灵性，有些人却没有。",
	["tid#herounlockedsaying_78"]="狩猎可不是无端的杀戮。",
	["tid#herounlockedsaying_79"]="抓住你啦！",
	["tid#herounlockedsaying_80"]="别担心，我看着你呢！",
	["tid#herounlockedsaying_81"]="休息，休息一下。",
	["tid#herounlockedsaying_82"]="嗯……奉献给我吧！",
	["tid#herounlockedsaying_83"]="非常迷人……",
	["tid#herounlockedsaying_84"]="福无双至，祸不单行。",
	["tid#herounlockedsaying_85"]="逍遥此身君子意，一壶温酒向长空。",
	["tid#herounlockedsaying_86"]="以心为剑，是为名剑。",
	["tid#herounlockedsaying_87"]="大巧似拙，举轻若重。",
	["tid#herounlockedsaying_88"]="大搜查时间开始了！",
	["tid#herounlockedsaying_89"]="条律可是约束人品的最低底线了。",
	["tid#herounlockedsaying_90"]="绝不放过你！",
	["tid#herounlockedsaying_91"]="走开！不要靠近我的朋友！",
	["tid#herounlockedsaying_92"]="别怕！站我身后！",
	["tid#herounlockedsaying_93"]="坚毅，是永垂不朽的神圣品格！",
	["tid#herounlockedsaying_94"]="谁说只有过年才能放烟花的？跟我来！",
	["tid#herounlockedsaying_95"]="来瞧瞧，我新研究的大家伙！",
	["tid#herounlockedsaying_96"]="少用那些不入流的炮仗和我的杰作比，我会让你哭的很有节奏！",
	["tid#herounlockedsaying_97"]="世人大概忘了，真正的感情不是生离死别能够左右的。",
	["tid#herounlockedsaying_98"]="请记住我的名字，也许我自己也会忘记。",
	["tid#herounlockedsaying_99"]="我并不在乎世人那些所谓审判的眼光。",
	["tid#herounlockedsaying_100"]="你生病了，我来送你一程吧。",
	["tid#herounlockedsaying_101"]="我好美，我怎么这么完美",
	["tid#herounlockedsaying_102"]="治病救人，不分高低贵贱。",
	["tid#herounlockedsaying_103"]="遍行君臣药，先从冻馁均。",
	["tid#herounlockedsaying_104"]="虚实在其脉，静躁在其情。",
	["tid#herounlockedsaying_105"]="来无影，则去无踪。",
	["tid#herounlockedsaying_106"]="精准的配比！绝对没有误差！",
	["tid#herounlockedsaying_107"]="年轻人！上进！加油！",
	["tid#herounlockedsaying_108"]="梦想，还是要有的，心才不会麻木。",
	["tid#herounlockedsaying_109"]="乱红飞处，最是销魂。",
	["tid#herounlockedsaying_110"]="来吧，看看这高处的风景。",
	["tid#herounlockedsaying_111"]="何去……何从……",
	["tid#herounlockedsaying_112"]="别跟我提什么落英，一身鸡皮疙瘩！",
	["tid#herounlockedsaying_113"]="强夺不如智取，偷鸡何必蚀米。",
	["tid#herounlockedsaying_114"]="滥杀动物的人，会招致生灵的惩罚哦。",
	["tid#herounlockedsaying_115"]="生灵们，请来帮助我吧～",
	["tid#herounlockedsaying_116"]="说起来，我还挺喜欢你的～",
	["tid#herounlockedsaying_117"]="有谁会记得自己吃了多少米饭呢？",
	["tid#herounlockedsaying_118"]="我似乎一直都在寻找什么？",
	["tid#herounlockedsaying_119"]="跟他们在一起，我仿佛若有所得。",
	["tid#herounlockedsaying_120"]="静息凝神，可得长生。",
	["tid#herounlockedsaying_121"]="我分明满腔正气，为何总是孑然一身？",
	["tid#herounlockedsaying_122"]="打打杀杀也令人厌烦，不如听我说些道理？",
	["tid#herounlockedsaying_123"]="你有什么烦恼，便可跟我说说？",
	["tid#herounlockedsaying_124"]="你慢慢儿说，我在听。",
	["tid#herounlockedsaying_125"]="过去的事情我记不清了，但未来总归是好的。",
	["tid#herounlockedsaying_126"]="众生皆苦，救一人便是一人。",
	["tid#herounlockedsaying_127"]="我已再无烦忧，只求觅得那人踪迹。",
	["tid#herounlockedsaying_128"]="捣衣砧上声声慢，明月独留夜夜寒。",
	["tid#herounlockedsaying_129"]="在我眼里，若非屈膝者皆是敌人。",
	["tid#herounlockedsaying_130"]="如若能进取天下，谁都是可杀之人。",
	["tid#herounlockedsaying_131"]="瞧瞧那些伪善人的嘴脸，多么可笑。",
	["tid#herounlockedsaying_132"]="女子如水，正是神水本源。",
	["tid#herounlockedsaying_133"]="好看的女子令我心生愉悦。",
	["tid#herounlockedsaying_134"]="纵使天池偌大，也留不住人的心。",
	["tid#herounlockedsaying_135"]="上朔天华兮降福隆。",
	["tid#herounlockedsaying_136"]="瑶池宫阙，琼浆煮雪。",
	["tid#herounlockedsaying_137"]="我们拨弄的弦声名曰希望。",
	["tid#herounlockedsaying_138"]="你找我来，所为何事？",
	["tid#herounlockedsaying_139"]="再愚钝的人，听了我的话也能刹那顿悟。",
	["tid#herounlockedsaying_140"]="欲成诸佛龙象，先为众生马牛。",
	["tid#herounlockedsaying_141"]="江湖险恶，不可轻信于人。",
	["tid#herounlockedsaying_142"]="绝世之功？前人可习得，我亦可习得！",
	["tid#herounlockedsaying_143"]="我此一生，但求行侠仗义，无愧于心。",
	["tid#herounlockedsaying_144"]="等你老了，丑了，他还不是会抛弃你！",
	["tid#herounlockedsaying_145"]="漂亮的人，都该死！",
	["tid#herounlockedsaying_146"]="怕是只见新人笑，哪闻旧人哭，呵呵。",
	["tid#herounlockedsaying_147"]="多想得见三千山海川，历遍须弥云水翻。",
	["tid#herounlockedsaying_148"]="我的名字？可谓诸子不言神鬼事，冷山默语千秋辞吧。",
	["tid#herounlockedsaying_149"]="有些人呀，少时便不肯多读书，如今只落得一莽夫。",
	["tid#herounlockedsaying_150"]="庸碌之辈，愚蠢之人，不必与之为伍。",
	["tid#herounlockedsaying_151"]="中了我的生死符，就没有人能够背叛我。",
	["tid#herounlockedsaying_152"]="这世间诸多错杂，其罪非我也！",
	["tid#herounlockedsaying_153"]="我就是玉树临风胜潘安，才高八斗折宋玉的鲁国唐生。",
	["tid#herounlockedsaying_154"]="得三两好友相伴，赏花赏月，岂不美哉？",
	["tid#herounlockedsaying_155"]="霸王枪在手，千山万水任我游！",
	["tid#herounlockedsaying_156"]="我种下一颗种子，等它生根发芽。",
	["tid#herounlockedsaying_157"]="云隐海岛上四季繁春，我很怀念那里。",
	["tid#herounlockedsaying_158"]="青君拂柳，带来生机。",
	["tid#herounlockedsaying_159"]="心之所向，无惧无悔！愿求仁得仁，复无怨怼！",
	["tid#herounlockedsaying_160"]="虽有遗憾，并无后悔。",
	["tid#herounlockedsaying_161"]="活着，虽然令人感到痛苦，然而美好之事，却唯有活着，才能经历。",
	["tid#herounlockedsaying_162"]="别说出来，在心里偷偷回答我就好了~",
	["tid#herounlockedsaying_163"]="你若一生只此一瞬，纵然相守一瞬，亦是一生。",
	["tid#herounlockedsaying_164"]="人和人只要遇上，无论一个时辰也好，一天也好，缘分就抹不掉了。",
	["tid#herounlockedsaying_165"]="想夺秘籍？那要看你有没有这个本事了！",
	["tid#herounlockedsaying_166"]="也不知道，何时才能再见到那个人……",
	["tid#herounlockedsaying_167"]="恩怨情仇，最终不过是过眼云烟……",
	["tid#herounlockedsaying_168"]="能者定然放眼天下，又怎能偏安一隅？",
	["tid#herounlockedsaying_169"]="毕方之火能净化一切。",
	["tid#herounlockedsaying_170"]="假以时日，我定当突破十重金乌的禁锢。",
	["tid#herounlockedsaying_171"]="负心人都该化作我的花肥。",
	["tid#herounlockedsaying_172"]="当你陷入花草缠绕之下，你越挣扎，他们缠绕的便越紧。",
	["tid#herounlockedsaying_173"]="你怎知道，草木就是无情之物？",
	["tid#herounlockedsaying_174"]="我那香香妹子颇为娇蛮，不知你可见识过？",
	["tid#herounlockedsaying_175"]="待哪日我若再见了义父，一定能让他刮目相看。",
	["tid#herounlockedsaying_176"]="行侠仗义，是我与生俱来的本能。",
