	["tid#SkillName_60751"]="金山派普攻",
	["tid#SkillDes_60611"]="密宗释放法相之力，对全场范围内的敌人造成200%攻击力的伤害和持续2秒的眩晕效果，并为所有己方其他侠客施加持续5秒的“法相”效果，被施加了“法相”效果的己方侠客，造成的伤害提升15%",
	["tid#SkillDes_60612"]="等级2：被施加了“法相”效果的己方阴势力其他侠客，造成的伤害提升至30%",
	["tid#SkillDes_60613"]="等级3：释放时若密宗处于“涅槃”状态，“法相”会为己方阴势力侠客恢复100内力",
	["tid#SkillDes_60614"]="等级4：对敌方全体造成260%攻击力伤害",
	["tid#SkillDes_60621"]="当密宗首次死亡时，会暂时离开战场10秒，之后会回满生命值重回战场，并进入“涅槃”状态。该状态下，密宗的攻击、防御、生命值提升35%，攻速提升70点，直至战斗结束。若己方侠客全部阵亡，则密宗会立即回到战场",
	["tid#SkillDes_60622"]="等级2：密宗重新回到战场时，为自身增加90%伤害减免，持续3秒",
	["tid#SkillDes_60623"]="等级3：密宗暂时离场时，清除全体友方侠客的控制效果并免疫3秒，且密宗战败后回到战场所需时间缩短至6秒",
	["tid#SkillDes_60624"]="等级4：战斗开始时，密宗将自身20%内伤减免附加给己方全体阴势力其他侠客，涅槃后的密宗将自身50%内伤减免附加给己方全体阴势力其他侠客",
	["tid#SkillDes_60631"]="密宗消耗当前生命值的10%，在敌方最密集区域内降下降魔杵，对敌人造成160%攻击力的范围伤害，释放技能时若密宗处于“涅槃”状态，则该技能不会消耗生命值",
	["tid#SkillDes_60632"]="等级2：当自身处于“涅槃”状态时，该技能冷却时间会大幅度减少",
	["tid#SkillDes_60633"]="等级3：伤害提升至180%攻击力",
	["tid#SkillDes_60634"]="等级4：伤害提升至200%攻击力",
	["tid#SkillDes_60641"]="为己方防御力最高的侠客施加一个持续8秒的护盾，护盾存在期间，密宗会为其分担所受伤害的50%，释放技能时，若密宗处于“涅槃”状态，则技能效果会变为给自己和防御力最高的己方侠客都施加一个护盾，抵挡200%攻击力的伤害",
	["tid#SkillDes_60642"]="等级2：当密宗重新回到战场时，会立刻释放一次该技能",
	["tid#SkillDes_60643"]="等级3：护盾值提升至220%攻击力",
	["tid#SkillDes_60644"]="等级4：护盾值提升至240%攻击力",
	["tid#SkillDes_60651"]="密宗普攻",
	["tid#SkillDes_60711"]="金山派挥舞重剑，对自身周围的敌人造成300%攻击力的伤害，并使其造成的伤害降低20%，持续6秒",
	["tid#SkillDes_60712"]="等级2:该技能成功命中敌人后，会为自身添加3层凌绝意，且每额外命中一个敌人，还会多添加一层",
	["tid#SkillDes_60713"]="等级3:伤害提升至350%攻击力",
	["tid#SkillDes_60714"]="等级4:释放该技能后3秒内，凌绝意的层数不会减少",
	["tid#SkillDes_60721"]="战斗开始时，金山派会获得45层“凌绝意”，每层凌绝意会为其增加1%的减伤效果，每当金山派受到一次普通攻击，凌绝意便会减少1层，每当金山派打出一次普通攻击，凌绝意便会增加1层，凌绝意最多叠加45层",
	["tid#SkillDes_60722"]="等级2:开场获得的凌绝意层数以及凌绝意的最大层数提升至50层",
	["tid#SkillDes_60723"]="等级3:开场获得的凌绝意层数以及凌绝意的最大层数提升至55层",
	["tid#SkillDes_60724"]="等级4:开场获得的凌绝意层数以及凌绝意的最大层数提升至60层",
	["tid#SkillDes_60731"]="金山派挥剑旋转一圈，对自身周围的敌人造成130%攻击力的伤害，该技能命中敌人后，会为自身添加3层“凌绝意”，且每额外命中一个敌人，还会多添加一层",
	["tid#SkillDes_60732"]="等级2:伤害提升至150%攻击力",
	["tid#SkillDes_60733"]="等级3:该技能每命中一个敌人，即为自身添加一层80%攻击力的护盾，持续5秒",
	["tid#SkillDes_60734"]="等级4:伤害提升至170%攻击力",
	["tid#SkillDes_60741"]="金山派原地消失，随后在敌人身后出现并对其造成210%攻击力的伤害和持续2秒的眩晕效果，若金山派身上存在“凌绝意”，则该技能还会随机对另一名敌方侠客造成一次攻击，但造成的伤害和眩晕效果会减半",
	["tid#SkillDes_60742"]="等级2:伤害提升至250%攻击力",
	["tid#SkillDes_60743"]="等级3:眩晕效果提升至3秒",
	["tid#SkillDes_60744"]="等级4:对敌人造成的额外伤害将不再减半",
	["tid#SkillDes_60751"]="金山派普攻",
	["tid#SkillDes_60811"]="独孤在敌人另一侧位置召唤一个影分身，影分身会拥有独孤80%的属性，拥有绝技外的所有技能，且会持续嘲讽当前目标，当分身死亡时，会产生爆炸并对周围造成250%攻击力的伤害，释放该技能时，若场上已经存在了一个影分身，则会使该影分身立刻爆炸，并在原地召唤新的分身（技能实装前可能会有平衡性调整）",
	["tid#SkillDes_60812"]="等级2:影分身现在会拥有独孤90%的属性",
	["tid#SkillDes_60813"]="等级3:影分身爆炸时造成的伤害提升至300%攻击力",
	["tid#SkillDes_60814"]="等级4:影分身现在会拥有独孤100%的属性",
	["tid#SkillDes_60821"]="战斗开始时，独孤会瞬移至敌方攻击最高的敌人身后，随后对其造成250%攻击力的伤害并使其束缚3秒（技能实装前可能会有平衡性调整）",
	["tid#SkillDes_60822"]="等级2:造成的伤害提升至260%攻击力",
	["tid#SkillDes_60823"]="等级3:释放该技能后，自身攻速会提升50%，持续5秒",
	["tid#SkillDes_60824"]="等级4:束缚时间提升至4秒",
	["tid#SkillDes_60831"]="对敌方单体造成260%攻击力的伤害，释放后若处于目标身前，则会将敌人原地束缚1秒，并瞬移至敌人身后；若处于目标身后，则会对目标额外造成一次220%攻击力的伤害（技能实装前可能会有平衡性调整）",
	["tid#SkillDes_60832"]="等级2:造成的额外伤害提升至240%攻击力",
	["tid#SkillDes_60833"]="等级3:该技能造成伤害的50%会转化为自身血量",
