	["tid#SkillDes_60841"]="战斗中，当独孤从背后攻击敌人时，造成的所有伤害会提升100%，且每对同一名敌人普攻3次，下一次普攻便会瞬移至敌人身前绞杀敌人，对其造成240%攻击力的伤害并使其眩晕1秒；当独孤正面面对攻击目标时，会有50%的概率闪躲目标攻击（技能实装前可能会有平衡性调整）",
	["tid#SkillDes_60842"]="等级2:独孤击杀敌人成功后，会立刻恢复20%最大血量，并提升20%攻击力持续到战斗结束",
