	["tid#HeroroleTips_1"]="1. 升级到彩5的侠客可以进行职业进阶\n2. 每次进阶消耗一张紫+品质的本卡和指定数量的天运石，联动侠客可在联动期结束后使用两个进阶道具替代一张紫+品质的本卡完成进阶。\n3. 侠客职业进阶后，可以无损耗进行还原。\n4. 侠客职业进阶后，可提升基础属性，并在1、2、3、4、5、6、7级分别获得职业技能。\n5. 侠客职业进阶获得的属性加成和职业技能只有本卡享受。\n6. 侠客职业进阶至3、5、7级时，本职业大侠类侠客获得生命、攻击、防御加成\n7. 侠客职业技能预览：\n\n护卫→柱石→铁浮屠→遮天之盾→（第3赛季开启）擎天→镇→镇天→镇九天\n柱石：战斗开始提升伤害减免+5%，持续6秒。\n铁浮屠：战斗开始提升伤害减免+10%，持续6秒。\n遮天之盾：战斗开始提升伤害减免+15%，受击有20%概率额外恢复100内力，持续8秒。\n擎天：战斗开始提升伤害减免+15%，受击有20%概率额外恢复125内力，持续8秒\n镇：战斗开始提升伤害减免+20%，受击有20%概率额外恢复125内力，持续8秒\n镇天：战斗开始提升伤害减免+20%，受击有20%概率额外恢复150内力，持续8秒\n镇九天：战斗开始提升伤害减免+25%，受击有20%概率额外恢复150内力，持续8秒\n\n战士→先锋→冠军侯→风林火山→（第3赛季开启）武神→圣→圣君→至圣君\n先锋：开场额外获得200内力与10%生命上限。\n冠军侯：开场额外获得400内力与10%生命上限。\n风林火山：开场额外获得400内力与10%生命上限，增加40点攻速和10点生命吸取。\n武神：开场额外获得400怒气与10%生命上限，增加45点攻速和15点生命吸取。\n圣：开场额外获得500怒气与15%生命上限，增加45点攻速和15点生命吸取。\n圣君：开场额外获得500怒气与15%生命上限，增加50点攻速和20点生命吸取。\n至圣君：开场额外获得600怒气与20%生命上限，增加50点攻速和20点生命吸取。\n\n刺客→隐者→赤罗刹→十步一杀→（第3赛季开启）镇魂→煞→煞绝→诡煞绝\n隐者：暴击时，提升30点闪避和5%爆伤增福，持续5秒，最多可叠加三层。\n赤罗刹：暴击时，提升60点闪避和10%爆伤增福，持续5秒，最多可叠加三层。\n十步一杀：暴击时，提升100点闪避和10%爆伤增福，持续5秒，最多可叠加三层。若击杀敌人，则立即恢复自身最大生命值10%且进入嗜血状态，自身攻击+10%持续5秒。\n镇魂：暴击时，提升120点闪避和爆伤+15，持续5秒，最多可叠加三层。若击杀敌人，则立即恢复自身最大生命值10%且进入嗜血状态自身攻击+10%持续5秒\n煞：暴击时，提升120点闪避和爆伤+15，持续5秒，最多可叠加三层。若击杀敌人，则立即恢复自身最大生命值15%且进入嗜血状态自身攻击+20%持续5秒\n煞绝：暴击时，提升140点闪避和爆伤+20，持续5秒，最多可叠加三层。若击杀敌人，则立即恢复自身最大生命值15%且进入嗜血状态自身攻击+20%持续5秒\n诡煞绝：暴击时，提升160点闪避和爆伤+20，持续5秒，最多可叠加三层。若击杀敌人，则立即恢复自身最大生命值20%且进入嗜血状态自身攻击+25%持续5秒\n\n神射→鹰眼→穿云箭→夺魄惊心→（第3赛季开启）贯日→极→极目→穹极目\n鹰眼：每3秒提升2%攻击，最大提升10%攻击。\n穿云箭：每3秒提升3%攻击，最大提升15%攻击。\n夺魄惊心：每3秒提升3%攻击，最大提升15%攻击。若击杀敌人，则额外增加攻击上限3%和3%最大攻击，最多叠加五层。\n贯日：每3秒提升4%攻击，最大提升20%攻击。若击杀敌人，则额外增加攻击上限3%和3%最大攻击，最多叠加五层。\n极：每3秒提升4%攻击，最大提升20%攻击。若击杀敌人，则额外增加攻击上限5%和5%最大攻击，最多叠加五层。\n极目：每3秒提升5%攻击，最大提升25%攻击。若击杀敌人，则额外增加攻击上限5%和5%最大攻击，最多叠加五层。\n穹极目：每3秒提升5%攻击，最大提升25%攻击。若击杀敌人，则额外增加攻击上限8%和8%最大攻击，最多叠加五层。\n\n辅助→策士→觅星罗→神之一手→（第3赛季开启）天命→玄→玄奇→幽玄奇\n策士：战斗开始时获得一个20%最大生命值的护盾持续5秒。\n觅星罗：战斗开始时获得一个20%最大生命值的护盾持续5秒，若结束时护盾存在，则每1%生命的护盾值转化为内力5点，最大不超过100点。\n神之一手：战斗开始时获得一个30%最大生命值的护盾持续5秒，若结束时护盾存在，则每1%生命的护盾值转化为内力5点，最大不超过150点。\n天命：战斗开始时获得一个30%最大生命值的护盾持续5秒，若结束时护盾存在，则每1%生命的护盾值转化为怒气8点，最大不超过150点。\n玄：战斗开始时获得一个30%最大生命值的护盾持续5秒，若结束时护盾存在，则每1%生命的护盾值转化为怒气10点，最大不超过200点。\n玄奇：战斗开始时获得一个30%最大生命值的护盾持续5秒，若结束时护盾存在，则每1%生命的护盾值转化为怒气12点，最大不超过200点。\n幽玄奇：战斗开始时获得一个30%最大生命值的护盾持续5秒，若结束时护盾存在，则每1%生命的护盾值转化为怒气15点，最大不超过200点。\n\n术士→奇门→紫薇垣→道藏归一→（第3赛季开启）三清→元→元钧→威元钧\n奇门：每次释放必杀后，永久增加3%内伤。\n紫薇垣：每次释放必杀后，永久增加5%内伤。\n道藏归一：每次释放必杀后，永久增加5%内伤，且同时获得一个护盾，免疫一次技能伤害，最多增加叠加五层。\n三清：每次释放必杀后，永久增加6%内伤，且同时获得一个护盾，免疫一次伤害,最多增加叠加五层。\n元： 每次释放必杀后，永久增加7%内伤，且同时获得一个护盾，免疫一次伤害,最多增加叠加五层。  \n元钧： 每次释放必杀后，永久增加8%内伤，且同时获得一个护盾，免疫一次伤害,最多增加叠加五层。  \n威元钧： 每次释放必杀后，永久增加9%内伤，且同时获得一个护盾，免疫一次伤害,最多增加叠加五层。\n      ",
	["tid#Musclepulse_Tips_1"]="1.当四条经脉升至满重，且侠客培养达到以下品阶可消耗四脉真气突破周天；\n   大周天：侠客品阶升至白色；\n   圆满：侠客品阶升至白4；\n2.每次突破均会获得周天提升带来的属性加成位；\n3.重置经脉突破的周天也会重置。",
	["tid#Musclepulse_Tips_2"]="1.当四条经脉升至满重，且侠客培养达到以下品阶可消耗四脉真气突破周天；\n   大周天：侠客品阶升至白色；\n   圆满：侠客品阶升至白4；\n2.每次突破均会获得周天提升带来的属性加成，并开启一个秘籍槽位；\n3.重置经脉突破的周天也会重置，已开启的秘籍槽位也会关闭。",
	["tid#Musclepulse_Tips_3"]="1.当四条经脉升至满重，且侠客培养达到以下品阶可消耗四脉真气突破周天；\n   大周天：侠客品阶升至白色；\n   圆满：侠客品阶升至白4；\n   化境：侠客品阶升至彩2；\n2.每次突破均会获得周天提升带来的属性加成，并开启一个秘籍槽位；\n3.当突破化境境界后，开启一个仅能装备先天秘籍的槽位；\n4.重置经脉突破的周天也会重置，已开启的秘籍槽位也会关闭。",
	["tid#Musclepulse_Tips_4"]="1.当四条经脉升至满重，且侠客培养达到以下品阶可消耗四脉真气突破周天；\n   大周天：侠客品阶升至白色；\n   圆满：侠客品阶升至白4；\n   化境：侠客品阶升至彩2；\n   筑基：侠客品阶升至彩5；\n2.每次突破均会获得周天提升带来的属性加成，并开启一个秘籍槽位；\n3.当突破化境境界后，开启一个仅能装备先天秘籍的槽位；\n4.当突破筑基境界后，开启一个仅能装备神技秘籍的槽位；\n5.重置经脉突破的周天也会重置，已开启的秘籍槽位也会关闭。",
	["tid#Scripture_Tips_1"]="1.秘籍分为两类，分别是先天秘籍和绝技秘籍；\n2.装备先天秘籍提升基础属性，随着经脉提升秘籍属性加成越多；\n3.绝技秘籍可额外获得绝技效果；\n4.秘籍可参悟：\n   参悟时消耗多本秘籍合成高一品阶秘籍；\n   不同品阶秘籍参悟时所需数量不同，品阶越高所需数量越少；\n   参悟时可预览合成秘籍的概率；\n5.秘籍可推演：\n   可消耗一张推演图随机推演出一本相同品质的秘籍。\n6.秘籍可镶嵌（第七赛季开启）：\n   可以对彩色秘籍进行镶嵌，镶嵌所需道具也是彩色秘籍；\n   镶嵌后根据镶嵌的数量提供属性加成或技能加成；\n   镶嵌获得的加成对同名的所有的秘籍都生效；\n   作为镶嵌道具而被镶嵌的秘籍不能被侠客装备，但可以脱下后再给侠客装备；\n   秘籍的镶嵌操作与脱下操作没有次数限制；",
	["tid#HeroroleTips_2"]="1. 侠客返璞后返回彩5品质\n2. 侠客返璞后返还职业升级所消耗的所有侠客和资源",
	["tid#AttTips_1"]="攻速：每2点攻速可提升1%攻击速度和1%技能释放频率\n减速：每2点减速可降低1%攻击速度和1%技能释放频率\n生命吸取：每1点生命吸取可使造成伤害的1%转化为自身生命回复 \n暴击效果：基础暴击效果为200%，每1点暴击效果可使暴击造成的伤害提升1%\n暴击率：每点暴击率提升1%暴击概率\n抗暴率：每点抗暴率降低1%被暴击概率\n坚韧值：每1点坚韧值可使自身受到的控制效果的持续时间减少1% \n内伤增加：每1%内伤增加可使自身造成的内功伤害增加1% \n外伤增加：每1%外伤增加可使自身造成的外功伤害增加1%\n内伤加深：每1%内伤加深可抵消敌人1%的内伤减免效果 \n外伤加深：每1%外伤加深可抵消敌人1%的外伤减免效果\n最终伤害：每1%最终伤害可使自身造成的内外功伤害皆增加1%\n内伤减免：每1%内伤减免可使自身受到的内功伤害减少1%\n外伤减免：每1%外伤减免可使自身受到的外功伤害减少1%\n伤害减免：伤害减免上限为90%，每1%伤害减免可使自身受到的内功和外功伤害都减少1%\n命中：命中值可降低敌人闪避外功伤害的概率\n闪避：闪避值可提升闪避外功伤害的概率，闪避率上限为80%\n真实伤害：无视护盾、防御、伤害减免直接造成伤害。\n治疗效果：每1%治疗效果可使自身释放的治疗效果提升1%\n受治疗效果：每1%受治疗效果可使自身受到的治疗效果提升1%\n免疫控制：免疫眩晕、冰冻、束缚、定身等使侠客无法攻击和移动的控制效果，无法免疫魅惑效果",
