	["tid#SkillName_41434"]="噬暗空明(等级4)",
	["tid#SkillName_41441"]="洞观幽冥(等级1)",
	["tid#SkillName_41442"]="洞观幽冥(等级2)",
	["tid#SkillName_41443"]="洞观幽冥(等级3)",
	["tid#SkillName_41444"]="洞观幽冥(等级4)",
	["tid#SkillName_41451"]="飞龙堡普攻",
	["tid#SkillDes_21411"]="苍火门为随机三个敌人施加“苍火印”，苍火印会在施加两秒后爆炸，对周围的敌人造成300%攻击力的范围伤害，若敌方已经被施加了苍火印记或者血量低于30%，则苍火印会立刻爆炸",
	["tid#SkillDes_21412"]="等级2:伤害提升至400%攻击力",
	["tid#SkillDes_21413"]="等级3:立即爆炸的苍火印造成的伤害提高20%",
	["tid#SkillDes_21414"]="等级4:当敌人血量低于50%时，苍火印会立即爆炸",
	["tid#SkillDes_21421"]="为己方两个随机侠客施加“苍炎”效果，持续6秒，被施加了苍炎效果的侠客，每秒会对自身周围的敌人造成80%攻击力的伤害,该技能会优先对己方前排单位释放",
	["tid#SkillDes_21422"]="等级2:持续时间提升至8秒",
	["tid#SkillDes_21423"]="等级3:每秒造成的伤害提升至130%攻击力",
	["tid#SkillDes_21424"]="等级4:被施加了苍炎效果的己方侠客还会提升20%防御",
	["tid#SkillDes_21431"]="为一名血量最低的敌方单位施加一个“苍火印”，若该技能成功击杀了敌人，则受到该次苍火印伤害的敌人都会被施加一个苍火印",
	["tid#SkillDes_21432"]="等级2:敌方血量越低，该技能附加的苍火印的伤害越高，最高提升50%",
	["tid#SkillDes_21433"]="等级3:成功参与击杀敌人时，苍火门会获得20%攻击力提升持续到战斗结束，该效果不可叠加",
	["tid#SkillDes_21434"]="等级4:成功参与击杀敌人时，苍火门会获得30%攻击力提升持续到战斗结束，该效果不可叠加",
	["tid#SkillDes_21441"]="当苍火门死亡时，会在自身周围产生爆炸，对范围内的敌人造成300%攻击力的伤害并为其施加一个苍火印",
	["tid#SkillDes_21442"]="等级2:自爆伤害提升至400%攻击力",
	["tid#SkillDes_21443"]="等级3:自爆伤害提升至500%攻击力",
	["tid#SkillDes_21444"]="等级4:被自爆命中的敌人受到的治疗效果减少50%，持续5秒",
	["tid#SkillDes_21451"]="苍火门普攻",
	["tid#SkillDes_21511"]="启灵派骑上猎豹，带领豹群横穿战场，对敌人造成260%攻击力的伤害，若命中的敌人身上有流血效果，则该技能对其造成的伤害提升40%",
	["tid#SkillDes_21512"]="等级2：释放该技能后，若自身已经处于骑射状态，则会恢复20%最大生命值的血量",
	["tid#SkillDes_21513"]="等级3：伤害提升至280%攻击力",
	["tid#SkillDes_21514"]="等级4：被该技能命中的敌人还会额外附加一层流血效果",
	["tid#SkillDes_21521"]="战斗开始时，启灵派会骑上猎豹进入骑射状态，该状态下，启灵派的血量会提升20%，且受到的单次伤害最多不超过最大生命值的30%，当启灵派累计受到相当于其50%最大生命值的伤害时，会退出骑射状态",
	["tid#SkillDes_21522"]="等级2：骑射状态下，启灵派的血量提升效果提高至25%",
	["tid#SkillDes_21523"]="等级3：首次退出骑射状态时，启灵派会获得50%攻速提升，持续5秒",
	["tid#SkillDes_21524"]="等级4：骑射状态下，启灵派的血量提升效果提高至30%",
	["tid#SkillDes_21531"]="非骑射状态下，对目标造成160%攻击力的伤害并附加一层流血效果；骑射状态下，启灵派会在猎豹扑咬敌人后再对其射一箭，额外造成160%攻击力的伤害和一层流血效果",
	["tid#SkillDes_21532"]="等级2：伤害提升至180%攻击力",
	["tid#SkillDes_21533"]="等级3：每次进入骑射状态时，会额外释放一次该技能",
	["tid#SkillDes_21534"]="等级4：伤害提升至200%攻击力",
	["tid#SkillDes_21541"]="将启灵派打出骑射状态的敌人会被施加一个复仇印记，启灵派会优先攻击被施加了复仇印记的敌人，且对其造成的伤害提高15%",
	["tid#SkillDes_21542"]="等级2：当启灵派击杀被施加了复仇印记的敌人时，会再次进入骑射状态，若自身已经处于骑射状态，则会恢复20%最大生命值的血量",
	["tid#SkillDes_21543"]="等级3：攻击被施加了复仇印记的角色时，造成的伤害提升20%",
	["tid#SkillDes_21544"]="等级4：攻击被施加了复仇印记的角色时，造成的伤害提升25%",
	["tid#SkillDes_21551"]="启灵派普攻",
	["tid#SkillDes_41411"]="飞龙堡释放一个飞轮，飞轮会在敌我之间弹跳攻击5次，若飞轮命中了敌方单位，则会对其造成200%攻击力的伤害和一层中毒效果，若命中了己方单位，则会为其恢复150%攻击力的血量，并生成120%攻击力的护盾，持续5秒，飞轮会优先选择未命中过的敌方和己方单位",
	["tid#SkillDes_41412"]="等级2:释放时，己方场上每有一个水阵营的侠客，便额外弹跳一次",
	["tid#SkillDes_41413"]="等级3:伤害提升至220%攻击力，回血效果提升至160%攻击力",
	["tid#SkillDes_41414"]="等级4:伤害提升至240%攻击力，回血效果提升至180%攻击力，护盾效果提升至160%攻击力",
	["tid#SkillDes_41421"]="为己方最虚弱侠客(生命百分比最低)施加强化效果，使其受到的伤害减少30%，并每秒恢复100%攻击力的血量，持续5秒",
	["tid#SkillDes_41422"]="等级2:持续时间提升至6秒",
	["tid#SkillDes_41423"]="等级3:减伤效果提升至35%",
	["tid#SkillDes_41424"]="等级4:回血效果提升至120%攻击力",
	["tid#SkillDes_41431"]="战斗开始时，飞龙堡身边会环绕一个水环，当水环存在时，飞龙堡会获得20点攻速，当受到致命伤害时，水环会消失并抵消本次伤害，之后飞龙堡会恢复30%最大生命值和200点内力",
	["tid#SkillDes_41432"]="等级2:受到致命伤害时，场上每存在一个水阵营的侠客，还会额外回复5%最大生命值",
	["tid#SkillDes_41433"]="等级3:回复的内力提高至300点",
	["tid#SkillDes_41434"]="等级4:攻速提升至25点",
	["tid#SkillDes_41441"]="当飞龙堡存在于战场中时，我方所有水阵营侠客会获得15%的攻击力和防御提升，除自身以外，己方场上每有一个水阵营侠客，攻击力和防御力还会额外提升2%，该效果会在飞龙堡死亡时消失",
	["tid#SkillDes_41442"]="等级2:我方水阵营侠客获得的攻击力和防御力提升效果提升至25%",
	["tid#SkillDes_41443"]="等级3:其他阵营的友方侠客也会获得攻击力和防御力的提升效果，但效果值只有水阵营侠客的一半",
	["tid#SkillDes_41444"]="等级4:该强化效果会在飞龙堡死亡后保留5秒",
	["tid#SkillDes_41451"]="飞龙堡普攻",
	["tid#Herolife_214"]="苍火门地处西域，本是个不与中原多交接的门派，不过新任掌门沈流云执掌门派之后，事情渐渐了有了改观，他常常登高向东南远望，意欲对中原武林徐徐图之。",
	["tid#Herolegend1_214"]="苍火门原本是中原世家大派，无奈百余年前，中原动荡，为求自保于是与关外陇右世家交好，便一直向西迁移，远离中原纷争。后来陇右门阀东进，苍火门时任掌门无意参与天下争端，并未跟随复归中原，便一直西域开宗落脚，安定百余年。",
	["tid#Herolegend2_214"]="偏安一隅的苍火门，少了争斗自然也少了当年原本的锐气。苍火门最高心法金乌决，最高有九重，修炼至九重者，能催动烈火真气，威力非凡。然而，苍火门多年来，凡修炼本门最高心法者最高不过七重，已经多年不见有人能重现烈火真气雄威。",
	["tid#Herolegend3_214"]="直到这一代沈流云掌教，天赋异禀又勤奋练武，自幼年起便苦练金乌诀，加冠之年便已将金乌诀练至九重，令烈火真气重现人间，催动掌力便可看到浑厚的真气喷薄而出，犹如熊熊的火焰灼灼燃烧。也因此，一众长老破格认定沈流云成为苍火门最年轻的掌教。",
	["tid#Herolegend4_214"]="成为掌教之后的沈流云，不满足于苍火门百年来一直龟缩在西域，他熟知教派历史，深知当年苍火门在中原武林也是何等辉煌。并且他九重的金乌诀，也该有一展宏图之力。因此他决议将苍火门重回中原，应与那些中原的侠客们争一争高下。",
	["tid#Herolegend5_214"]="然而，早已习惯了偏安西域的长老们十分抗拒沈流云的决定，他们认为中原武林风云百年，早已不是当年的情况，如尽苍火门在西域开枝散叶，在当地也颇有威望，如此轻易放弃百年来在西域的积淀属实鲁莽。可沈流云如今神功大成，哪管长老们的劝诫，他以雷霆手段令长老们屈服，成为了苍火门唯一的话事人。",
	["tid#Herolegend6_214"]="苍火门的动向自然是引起了九天的注意，如尽中原武林本就有万象楼与天罗众不断搅动风云，倘若野心勃勃的苍火门也来给武林增添几分烟雨，势必会使武林更加动荡。于是在收到苍火门长老密信的九天-曜天君，决定前往拜会一下沈流云。",
	["tid#Herolegend7_214"]="沈流云拒绝了曜天君的拜会，他觉得中原武林如此排斥自己，不过是低看了苍火门的实力，于是主动发出挑战，约曜天君在玉门关一会。江湖传闻那一战神鬼惊泣，然而沈流云终究是惜败一招。但沈流云却并未因此气馁，他觉得苍火门百年来的沉寂，令本门的最高心法没落止步不前，因此他决定孤身前往蓬莱，好好历练一番，突破金乌诀的九重桎梏，一探金乌诀未有人达到的第十重。",
	["tid#Herolife_414"]="高小珊是飞龙堡的少堡主，她来自云来岛，听闻就如同天上的仙女，却始终散发着拒人于千里冰冷气质。倘若有人试图对飞龙堡不利，都将招致她的无情的反击。这样凌厉的做事方式，也许都来自于曾遭受的磨难。",
	["tid#Herolegend1_414"]="俏丽动人的她，虽然年纪轻轻已经统领了数万帮众，但她心中依然难忘儿时那场本不该发生的灾难。幼年目睹父亲在一场与宿敌的较量中身亡，彼时的画面时刻重现于她的脑中，也从此对报仇血恨念念不忘。她的心中，一直记着仇敌之子的名字——钟离要。",
	["tid#Herolegend2_414"]="父亲去世后，母亲也不顾一切，殉情而亡。高小珊年纪尚小，就背负上了沉重的血海深仇。为了报仇，她埋头经营，刻苦修炼，只为最后复仇的一刻。但她不知道的是，与钟离要相遇后，她便注定要时刻面临着，爱情与家仇之间的痛苦抉择。",
	["tid#Herolegend3_414"]="继承了父亲的飞龙堡后，高小珊师从神水宫玄水姬，潜心修炼，只待有朝一日报仇雪恨。她隐姓埋名求学于神水宫门下，却始终是玄水姬最得意的弟子。蛰伏多年后，她凭一招世人皆以为失传的“瑶池仙水”名闻武林，所到之处，一身冰凌般的内力如同水生仙子，将所有作乱的宵小尽数击败。",
	["tid#Herolegend4_414"]="涉足江湖多年后，她开始渐渐揭开父辈恩怨的真相。她意外发现自己有一个同胞妹妹，因生父的阴谋姐妹失散，被卷入复杂的江湖纷争。高小珊虽然个性果断独立，但她发现，自己和妹妹一样，只要进入江湖，都是一样的身不由己。父辈的恩怨纠葛，终归让她们这些后辈饱受磨难。她有时会想，倘若武林没了争端纠葛，又何必让人蒙受如此多的苦难。",
	["tid#Herolegend5_414"]="飞龙堡久经江湖浮沉，高小珊以一己之力支撑，过得十分艰难。近日江湖动荡，总有大小门派侵扰飞龙堡，堡内也渐渐有了骚动。高小珊是堡主的继女，有人以此为由，污蔑她难以服众，才让飞龙堡声名败落，成为众矢之的。但在高小珊的玲珑心思兼以决绝手段之下，他们发现堡内掀不起什么风浪，于是叛出飞龙堡，在江湖中自立门户，声称要为飞龙堡“正名”。",
	["tid#Herolegend6_414"]="高小珊追查这些叛逃的属下时，意外听闻他们和钟离要交好，还一起出海前往蓬莱了。这些叛徒原本是觊觎堡主之位，想从钟离要处骗取武林秘籍对付高小珊，但近日种种加上多年世仇，让高小珊觉得他们是与钟离要勾结，一同暗算飞龙堡。愤慨之下，高小珊只身出海，追往蓬莱岛。",
	["tid#Herolegend7_414"]="在蓬莱，高小珊没有见到钟离要，但习得蓬莱武功后功力大涨，重振飞龙堡威名已不在话下。回到中原，她发现叛徒打着飞龙堡的旗号坏事做尽，飞龙堡的声名岌岌可危，更被各大门派声讨。高小珊断定这是钟离要与他们之间的阴谋，于是下定决心，一定要会一会这个多年的“宿敌”。",
	["tid#SkillName_70111"]="焚焰血戮(等级1)",
