	["tid#SkillName_70144"]="煞魄(等级4)",
	["tid#SkillName_70151"]="天墉城普攻",
	["tid#SkillDes_70111"]="天墉城释放两次焚寂剑的魔焰，对自身周围大范围的敌人造成两次220%攻击力的外功伤害，并使自身进入“毁殇”状态，持续8秒。毁殇状态下，天墉城的攻击力提升80%，受到的伤害降低30%、不会被控制且不能获得内力。当与风晴雪同时上阵时，焚寂剑额外释放一次。",
	["tid#SkillDes_70112"]="等级2:毁殇状态时，天墉城获得的攻击力提升至100%",
	["tid#SkillDes_70113"]="等级3:毁殇持续时间提升至12秒",
	["tid#SkillDes_70114"]="等级4:毁殇状态下，天墉城的普攻将变为玄天炽炎",
	["tid#SkillDes_70121"]="天墉城挥舞燃烧着火焰的长剑，打击并轻微击退前方扇形区域内的敌方侠客，造成220%攻击力的外功伤害并恢复30%造成伤害的生命值。",
	["tid#SkillDes_70122"]="等级2:每次释放玄天炽炎，该技能的伤害提升8%，最多可叠加10层，持续整场战斗",
	["tid#SkillDes_70123"]="等级3:玄天炽炎每击中一名敌方侠客，天墉城获得10%防御力提升，最多叠加4层，持续5秒",
	["tid#SkillDes_70124"]="等级4:当天墉城的血量低于40%时，将有50%概率额外触发一次玄天炽炎",
	["tid#SkillDes_70131"]="开场时，天墉城召唤剑阵锁定敌方攻击力最高的侠客，使其对天墉城的伤害降低16%，并提高16%天墉城对目标的伤害",
	["tid#SkillDes_70132"]="等级2:被锁定的侠客，受治疗效果降低30%，持续整场战斗",
	["tid#SkillDes_70133"]="等级3:当被锁定侠客未被击败时，天墉城获得额外8%的伤害减免",
	["tid#SkillDes_70134"]="等级4:当被锁定的侠客被击败，天墉城获得50点攻速，持续6秒",
	["tid#SkillDes_70141"]="当天墉城的生命值首次低于80%时，将召唤煞魄护体，获得50%的伤害减免效果，持续到战斗结束",
	["tid#SkillDes_70142"]="等级2:煞魄持续时，周围的敌人每秒受到80%攻击力的伤害",
	["tid#SkillDes_70143"]="等级3:召唤煞魄后，天墉城攻击力提升20%，持续整场战斗",
	["tid#SkillDes_70144"]="等级4:召唤煞魄时将震晕周围的敌人，持续3秒",
