	["tid#SkillName_70251"]="娲皇神殿普攻",
	["tid#SkillDes_70211"]="娲皇神殿对敌方全体造成三次220%攻击力的内功伤害，每次伤害30%概率叠加一层冻伤（冻伤：降低2点攻速，并使目标每3秒受到一次60%攻击力的伤害，最多可叠加5层，持续15秒），当与天墉城同时上阵时，娲皇神殿会召唤红月，对敌方全体造成四次内功伤害，最后三次100%概率叠加一层冻伤",
	["tid#SkillDes_70212"]="等级2:对达到3层冻伤效果的敌人额外造成80%攻击力的内功伤害",
	["tid#SkillDes_70213"]="等级3:对达到4层冻伤效果的敌方侠客额外造成100%攻击力的内功伤害并冰冻1秒",
	["tid#SkillDes_70214"]="等级4:对达到5层冻伤效果的敌方侠客施加冰爆，冰爆将会使目标冰冻2秒，并对目标及周围造成160%攻击力的内功伤害",
	["tid#SkillDes_70221"]="娲皇神殿挥舞镰刀在敌方最密集的地方升起“冰柱”，每3秒攻击一次周围的敌方侠客，使其受到冻伤效果，冰柱可释放三次冻伤（冻伤：降低2点攻速，并使目标每3秒受到一次60%攻击力的伤害，最多可叠加5层，持续15秒）",
	["tid#SkillDes_70222"]="等级2:冰柱范围内的敌方侠客，受到的伤害增加10%",
	["tid#SkillDes_70223"]="等级3:冰柱出现时随机冰冻一名敌方侠客，持续2秒",
	["tid#SkillDes_70224"]="等级4:冰柱范围内的敌方侠客，受到的伤害增加20%",
	["tid#SkillDes_70231"]="开场时，给全部友方攻速提升40点，持续6秒。并与友方攻击力最高的侠客进行月相连结，双方攻速提升20点；若连结天墉城则攻速提升30点。连结角色死亡则取消连结（该技能优先选择天墉城）",
	["tid#SkillDes_70232"]="等级2:被连结侠客获得一次免控控制效果",
	["tid#SkillDes_70233"]="等级3:若连结对象被击败，娲皇神殿攻击力提升25%，暴击率提升15%，持续8s；若被击败的连结对象为天墉城，娲皇神殿攻击力提升35%，暴击率提升20%，持续8秒。",
	["tid#SkillDes_70234"]="等级4:若连结对象被击败，则降下冰雹对敌方全体侠客造成160%的内功伤害，并有80%概率的造成冰冻，持续2秒。",
	["tid#SkillDes_70241"]="娲皇神殿挥舞巨镰瞬移并攻击敌方血量最低的侠客（施法过程无敌），造成140%攻击力的内功伤害，当“冰柱”存在时，此技能将变为范围伤害，并为目标叠加一层冻伤效果。攻击后娲皇神殿回到攻击前的位置。当与天墉城同时上阵时，附加敌方已损失生命值3%的额外伤害，若击杀目标，则继续释放。",
	["tid#SkillDes_70242"]="等级2:当冰柱存在时，伤害提升至250%",
	["tid#SkillDes_70243"]="等级3:施放此技能后，娲皇神殿免疫控制2秒",
	["tid#SkillDes_70244"]="等级4:该技能每击中一名敌方侠客，回复50点内力",
