	["tid#SkillName_40951"]="飞雪刀普攻",
	["tid#SkillDes_40911"]="飞雪刀会攻击全部带破绽的人一次，并返回当前血量百分比最少的目标强迫其与自己“决斗”8秒钟，决斗持续期间，飞雪刀的攻击力提高30%，且收到的来自决斗角色以外的伤害会减少50%",
	["tid#SkillDes_40912"]="等级2:若决斗对象在决斗期间死亡，则飞雪刀的攻击力会提升10%，该效果会持续至战斗结束",
	["tid#SkillDes_40913"]="等级3:若决斗对象在决斗期间死亡，则飞雪刀会立刻恢复20%已损失的生命值",
	["tid#SkillDes_40914"]="等级4:施展该技能后，会立刻在决斗对象身上生成一个破绽",
	["tid#SkillDes_40921"]="飞雪刀每隔5秒随机对一名敌方侠客生成一个破绽，当飞雪刀普攻攻击被施加了破绽标记的角色时，会消耗该标记并额外附加敌方最大生命值3%的伤害，附加伤害的上限为500%攻击力，同一侠客最多叠加3层破绽。",
	["tid#SkillDes_40922"]="等级2:附加伤害提升至5%最大生命值",
	["tid#SkillDes_40923"]="等级3:每次攻击破绽成功，飞雪刀便会恢复5%已损失生命值",
	["tid#SkillDes_40924"]="等级4:每次攻击破绽成功，飞雪刀便会恢复10%已损失生命值",
	["tid#SkillDes_40931"]="战斗开始时，飞雪刀会瞬移至与自己位置相对的敌方侠客身后，对其造成240%攻击力的伤害，并立刻在其身上生成一个破绽",
	["tid#SkillDes_40932"]="等级2:伤害值提升至260%攻击力",
	["tid#SkillDes_40933"]="等级3:该技能造成伤害后，还会使敌方内力恢复速度减少30%，持续8秒",
	["tid#SkillDes_40934"]="等级4:伤害值提升至280%攻击力",
	["tid#SkillDes_40941"]="飞雪刀进入看破状态2秒，期间免疫控制，之后挥剑前刺，造成200%攻击力的伤害，若看破期间受到了来自敌方的控制效果，则会在技能结束时反击施加控制的敌方角色，对其造成200%攻击力的伤害并使其眩晕3秒",
	["tid#SkillDes_40942"]="等级2:伤害提升至230%攻击力",
	["tid#SkillDes_40943"]="等级3:反击成功时，立刻在反击目标身上生成一个破绽",
	["tid#SkillDes_40944"]="等级4:伤害提升至240%攻击力",
	["tid#SkillDes_40951"]="飞雪刀普攻",
	["tid#Herolife_313"]="有梨园女子，善歌舞，尤以百花词闻名天下，是京城乐清坊的当家花魁。据说听她一支曲就要花费千金，即便如此，京城的达官显贵们仍络绎不绝。但没人人知道，这位来自百花派的佳人，同时也是网罗天下情报，意欲颠覆新朝的复仇者。",
	["tid#Herolegend1_313"]="李兰婷出身梨园，自幼修习音律。幸被宫中执事选中，为官家宴席表演节目。一次偶然的机会，李兰婷的舞姿被偷偷溜出宫的皇子所见。皇子惊为天人，遂邀李兰婷入宫为宴会表演一曲，李兰婷欣然答应。",
	["tid#Herolegend2_313"]="时值国战之时，李兰婷为战士所作一曲破阵乐。李兰婷立于大殿之上，歌声悠扬，舞姿轻盈。此曲前段婉转低回，如出征前离别的絮语；后段激昂，宛若沙场征战金鼓震天，波澜壮阔，气势雄浑，不似柔弱女子所作。大殿内，百官拍手叫好，觥筹交错之间竟有无穷豪壮之气，酒酣之时，尽诉报国之志。",
	["tid#Herolegend3_313"]="因出色的表现，李兰婷被留居在宫外清乐园。皇子也喜好音律，更赏识李兰婷为国为民的情怀，遂与李兰婷相交。二人并无君臣之别，而是互为知己，皇子常在清乐园弹琴伴李兰婷起舞，颇有高山流水觅知音之意。不久天子驾崩，皇子登基为帝。继位前一晚，皇子与李兰婷对饮，他告诉李兰婷自己想做一个好皇帝，然后，他问李兰婷，愿不愿意做他的贵妃。李兰婷不知所措，落荒而逃。",
	["tid#Herolegend4_313"]="然而新帝登基，却引发祸端。权臣私通外戚大将，以清君侧之名公然进京，狼子野心路人皆知。仓皇之下，皇子只得亲率禁军迎敌。七日后，叛军攻入京城。皇子将李兰婷等宫人送出城外，离别之际，李兰婷答应嫁给皇子。但李兰婷没想到，一见已是永别，叛军囚禁了皇子，之后便大肆搜捕狐媚偏能惑主的宠姬李兰婷。原来，李兰婷正是他们发动叛乱的借口。",
	["tid#Herolegend5_313"]="李兰婷不知道自己是如何逃出来的，她只记得那是段噩梦般的日子。等她被百花派的前任掌门带回宗门时，曾与挚友琴瑟和鸣的清乐园已是一片焦土。不久后，皇子被大将军鸩杀，另立新帝。李兰婷痛苦万分，百花派掌门见之不忍，又欣赏李兰婷才情，便收李兰婷为弟子，传其武艺。",
	["tid#Herolegend6_313"]="数年后，李兰婷下山。她回到京师，在子夜偷偷来到清乐园。这是她于皇子回忆之地，也是皇子被鸩杀的地方，此时已被烧为焦土。李兰婷以手轻抚脚下灰烬，枯木清寒，晚风彻骨。李兰婷的思绪也随风回到从前：常居清乐园的她，常与挚友一同观赏夏天垂摇的翠绿杨柳，赏月捉蝉，采花闻香。想到此处，李兰婷不知不觉间流出两行清泪。那日之后，她决心复仇。",
	["tid#Herolegend7_313"]="乐清坊的名字取自前废帝最爱的清乐园，是京城内最纸醉金迷的地方。三巡过后，坊内的气氛在婉转魅惑的曲调中达到高潮。曲罢，李兰婷从闺阁中飘然而出，摘下自己的面纱，露出略施粉黛的绝美容颜，游走于达官显贵之间，留心记下他们不小心透露出的朝中隐秘。直到午夜将近，乐清坊的最后一批客人醉醺醺的离开或是留宿。李兰婷从宾客区回到后台，娇媚热情的面孔顷刻间归于平静，神情淡漠却专注。",
	["tid#itemName400035"]="石碑文本·一",
	["tid#itemName400036"]="石碑文本·二",
	["tid#itemDes400035"]="上面写着“五行轮转，生生不息”",
	["tid#itemDes400036"]="上面写着“五行逆乱，杀克不止”",
	["tid#itemName400037"]="庚金剑",
	["tid#itemName400038"]="碧木簪",
	["tid#itemName400039"]="土灵镜",
	["tid#itemName400040"]="玉净瓶",
	["tid#itemName400041"]="炎狱重剑",
	["tid#itemDes400037"]="蕴含着庚金之气的宝剑，似乎对木属性敌人很克制",
	["tid#itemDes400038"]="蕴含着木属性气息的簪子，应该对土属性很克制",
	["tid#itemDes400039"]="土灵结晶凝结成的镜子，能破除水属性的幻影",
	["tid#itemDes400040"]="装满了弱水的瓶子，能够熄灭任何火焰",
	["tid#itemDes400041"]="在炎狱中煅烧成的重剑，能够砍断庚金封印",
	["tid#MysticBuffDes_920041"]="当生命首次降至50%与30%时，获得30%最大生命值的护盾，护盾存在时提升10%攻击力，持续8秒（与无相神功效果不叠加）",
	["tid#MysticBuffDes_920042"]="当生命首次降至80%与40%时，获得30%最大生命值的护盾，护盾存在时提升10%攻击力，持续8秒（与无相神功效果不叠加）",
