	["tid#MysticBuffDes_930031"]="战斗开始时，给自己增加一个提升自身血量50%、攻击力20%的增益效果，持续时间8秒",
	["tid#MysticBuffDes_930032"]="战斗开始时，给自己增加一个提升自身血量50%、攻击力50%的增益效果，持续时间8秒",
	["tid#MysticBuffDesclass_930031"]="战士装备激活：首次血量降低至35%，触发一个吸收敌方伤害的护盾，护盾期间无敌，持续时间4秒，护盾消失时吸收的伤害50%转换为一个吸收这些伤害的护盾。",
	["tid#MysticBuffDes_300061"]="技能攻击敌对目标时判断其身上是否有回血、护盾增益效果，如有则驱散其中3个，最多同时驱散3个目标，并且给目标加一个攻击力降低60%的负面状态，持续3秒。秘籍效果每8秒生效一次",
	["tid#MysticBuffDes_300062"]="技能攻击敌对目标时判断其身上是否有回血、护盾增益效果，如有则驱散其中3个，最多同时驱散4个目标，并且给目标加一个攻击力降低60%的负面状态，持续3秒。秘籍效果每8秒生效一次",
	["tid#MysticBuffDes_300063"]="技能攻击敌对目标时判断其身上是否有回血、护盾增益效果，如有则驱散其中3个，最多同时驱散3个目标，并且给目标加一个攻击力降低60%的负面状态，持续3秒。秘籍效果每6秒生效一次",
	["tid#MysticBuffDes_300064"]="技能攻击敌对目标时判断其身上是否有回血、护盾增益效果，如有则驱散其中3个，最多同时驱散4个目标，并且给目标加一个攻击力降低60%的负面状态，持续3秒。秘籍效果每6秒生效一次",
