	["tid#Herolife_608"]="这江湖之中本就纷乱不断，而刺客便也层出不穷，可近几年来最让人闻风丧胆的刺客之一，便是独孤珏，传言她从来不接没有把握的单子，但是一旦接下，目标便是必死无疑。",
	["tid#Herolegend1_608"]="曾与独孤珏有过些许交情的人说过，独孤珏从来不做没有把握的事情，每次接到任务，必定做好严密的计划，然后坚决地执行。这人问她，万一发生一些变故也不变通一下吗？得到的回答却是所有的可能性她都想过了，也只有这样的计划才配叫做计划，她讨厌赌博，也因此不会做任何没有不确定的事情。",
	["tid#Herolegend2_608"]="独孤珏原本只是一个流民妇女诞下的遗腹子，本就食不果腹，餐风露宿的独孤母亲费劲最后一丝力气生下独孤珏后便撒手人寰，说起来独孤珏能活下来本身就是个奇迹了。而跟着流民长大的独孤珏后来落在了一座城里变成了乞丐，倒也算是安定了下来。",
	["tid#Herolegend3_608"]="不曾想到的是，作为一个乞丐，独孤珏凭借着天赋灵敏的反应与身手，练就出一手盗窃的好功夫，因此偷来不少财物的她，因此在一堆小乞丐当中就显得尤其滋润。并且尤擅做计划的她领着一帮小乞丐在城里犯了不知道多少次大小盗窃案子，身边也有了不少乞丐拥趸。然而，独孤珏没有计划到，平日里与自己要好的乞丐孩子里还是有人背叛了她，她被城里的地头蛇抓了起来。",
	["tid#Herolegend4_608"]="可令人没想到的是，这地头蛇反而十分欣赏独孤珏的天分，并将她送到了自己上面的刺客组织当中。独孤珏在刺客组织的一次次试炼当中脱颖而出，并获得一个固定的称号廿五。她最后接到的第一个任务便是击杀自己的前辈，组织的叛徒——廿四。",
	["tid#Herolegend5_608"]="为了取下廿四首级，她做了很多计划，在组织的催促当中做了无数次推演却迟迟不肯出手。她与廿四可能只是有过几面之缘，却对她的实力有深刻的了解，最后她决绝执行任务，因为她做不出能击败廿四的计划。后来听闻廿四去了蓬莱岛，而她也因此被逐出了组织，所以她便自称一派独孤一门，江湖上也再没有了刺客廿五。",
	["tid#herolegend6_608"]="被迫离开组织的独孤珏，开始在江湖崭露头角，但是组织当然不能放任自己的弃子在江湖上抛头露面，因此开始不断的试图除掉独孤珏。察觉到情况的独孤珏为了反制，于是也开始有意图的报复组织，她截取组织的目标，暗中对付组织的重要成员，不间断破坏组织的计划，甚至找到了天忍教当初窃取金山派剑谱的机密……然而组织，甚至背后的天忍教也对独孤珏无能为力。",
	["tid#herolegend7_608"]="终于，孤独珏的行动引起了凌雪寒的侧目，在经过深思熟虑之后，凌雪寒招揽独孤珏。既然独孤一门也是接取委托的，于是凌雪寒让的女儿凌一亲自找到独孤珏，并向她发出委托，只要完成便能加入天忍凌峰楼。凌一是谁，凌一正是如今天忍凌峰楼天罗第一高手，在她的面前，独孤珏也不敢轻举妄动，在感受到凌一黑色链刃上的冰冷寒意之后，独孤珏知道自己肯定无法面对整个天罗众，于是独孤珏接下了凌一的委托，并顺利完成，成为了天罗众的新成员。",
	["tid#herounlockedsaying_177"]="我那香香妹子颇为娇蛮，不知你可见识过？",
	["tid#herounlockedsaying_178"]="待哪日我若再见了义父，一定能让他刮目相看。",
	["tid#herounlockedsaying_179"]="行侠仗义，是我与生俱来的本能。",
	["tid#Herolife_215"]="江湖中与兽为伍，佼佼者当属万兽庄，但仍有一支另类对万兽庄与兽为伴的理念嗤之以鼻，这便是启灵派。而万兽庄庄主的一对千金中却生出了一个叛逆者，她天生便是野兽的统领者，在加入敌人的阵营后，她完全可以按照自己的想法来操纵野兽，成为江湖中不可忽视的力量。",
	["tid#Herolegend1_215"]="很多人都不清楚当初的万兽庄庄主曾拥有两个女儿，并蒂花开，故名莲华，而史春华正是其中的妹妹。然而，与天赋异禀的姐姐不同，姐姐始终恪守万兽庄的原则，对自然总是抱有一丝敬重，而妹妹却不同，她总觉得自然就是要去征服，弱肉强食就是丛林的法则。因此，史春华从小因为截然不同的形式风格屡屡遭受父亲的苛责，这让史春华的心里总是心生怨怼。",
	["tid#Herolegend2_215"]="并不受父亲的喜欢的小女儿遭到了父亲的冷落，甚至决定将她过继给同族的一个本家兄弟，为此遭到史春华的强烈反抗。身为姐姐的史春莲同样不想看到与自己的孪生姐妹就此分离也为次与父亲争辩过几番，不过史春华决定自己掌握自己人生不再受人摆布因此在一个夜里离开了万兽庄，此刻的她也才将将及笄之年而已。",
	["tid#Herolegend3_215"]="离开万兽庄的史春华利用自己掌握的狩猎知识暂时能在丛林之中苟存下来，然而她要面临的困境也是前所未有的，没有他人的帮助，孤身一人，物资缺乏，时刻要警惕周围的一切，以免成为野兽的猎物。但是，所有的困难在她的身上，似乎成了催化她野性本身的催化剂，她始终贯彻自己的信念，想要在丛林中生存下来，就要成为丛林规则的卫道者——弱肉强食，适者生存。这里没什么所谓的道德与世故，有的便是强者生存。",
	["tid#Herolegend4_215"]="可是身为人，终究是会有自己脆弱的一面，更何况史春莲离开家时也不过是一个涉世未深的小姑娘而已。丛林中一直有只名唤“玄将军”的黑色豹子，盘踞丛林堪为此地兽王，如此危险的猛兽其一身油亮黝黑的皮毛却也依然能受到某些达官贵人的青睐，众猎户无论谁都想获得那笔天价的赏钱。因此，一众猎户找到了熟悉丛林的史春莲合作对付这玄将军，并且许诺了一个让史春莲难以拒绝的报酬。可没想到的是，那些猎户利用了她，不过是想趁着她与玄将军两败俱伤之时趁渔翁之利，愤怒的史春莲发出野兽一般的怒吼似乎也激发了玄将军的血性反将这些猎人送归了尘土之中。",
	["tid#Herolegend5_215"]="渐渐地，史春莲觉得这片小小的丛林已经不能在满足她狩猎的本能，她需要一片更大的猎场更强的敌人，只有这样她才能变得更加强大。然而在她离开的那一天，玄将军也跟在她的身后，像是一种臣服的姿态，史春华清楚，这片丛林没了自己之后，玄将军也没了自己的对手也迟早会泯灭在碌碌无为的荒诞之中。于是江湖中多了一个与万兽庄截然不同的派别。",
	["tid#herolegend6_215"]="那一次史春莲意外见到了失散多年的孪生姐妹，然而这个早已变了样的妹妹却对自己毫无兴趣，反而对她身边的小夜十分有兴趣。而史春莲的小夜一见到史春华便被她身上的气势感到害怕于是低呜着退向史春莲的身后，筱九说，小夜很久没有感受到这种来自丛林的无情杀意了，所幸飞雪其实出现，赶走了不知从何处袭击儿来的玄将军。总之这是姐妹二人一次灾难性的重逢。",
	["tid#herolegend7_215"]="史春华的身边如今已经有了不少的拥趸，但是史春华从不信任任何人，他们会想方设法收集各种各样的奇珍异兽，并通过征服的方式试图奴役他们。他们的行为无可厚非去也让九黎部族的人忍无可忍，他们原本就是崇尚与自然生灵和谐相处的群体，如今启灵派的人也将自己的手伸向了那些地方，而代表着万兽庄势力的史春莲便义无反顾地站在了自己亲生妹妹的对立面。也许双生的并蒂莲，终究不能同享来自根须的养分。",
	["tid#herounlockedsaying_180"]="无情，是自然高效的法则。",
	["tid#herounlockedsaying_181"]="漫漫长夜是掩护我们行动的帷帐。",
	["tid#herounlockedsaying_182"]="人何尝不过是天生就启迪智慧的野兽。",
	["tid#poetry_215"]="长哨啸山林\\n  闻声夜下逢\\n  谁可驱百兽\\n  谓我启灵宗",
