	["tid#SkillName_21651"]="潘金莲普攻",
	["tid#SkillDes_21611"]="潘金莲向敌方战场释放毒雾，对范围内的敌人造成200%攻击力的伤害，并使其攻击力，攻击速度和防御力降低30%,持续6秒",
	["tid#SkillDes_21612"]="等级2:攻击力、攻击速度、防御力降低效果提升至35%",
	["tid#SkillDes_21613"]="等级3:持续时间提升至8秒",
	["tid#SkillDes_21614"]="等级4:攻击力、攻击速度、防御力降低效果提升至40%",
	["tid#SkillDes_21621"]="潘金莲对所有敌方男性侠客施加迷药，对其造成150%攻击力的伤害，并有50%的概率使其魅惑3秒，被魅惑的敌人只能使用普通攻击",
	["tid#SkillDes_21622"]="等级2:魅惑概率提升至60%",
	["tid#SkillDes_21623"]="等级3:被魅惑的人可以使用除必杀技以外的技能",
	["tid#SkillDes_21624"]="等级4:魅惑概率提升至70%",
	["tid#SkillDes_21631"]="战斗开始时，潘金莲会鼓舞所有自己和己方男性单位，使其在之后的10秒内，攻击速度提升30%",
	["tid#SkillDes_21632"]="等级2:被鼓舞的单位还会获得30%的攻击力提升效果",
	["tid#SkillDes_21633"]="等级3:攻速提升效果提高至40%",
	["tid#SkillDes_21634"]="等级4:持续时间提升至15秒",
	["tid#SkillDes_21641"]="战斗中，潘金莲受到来自敌方男性角色的伤害减少40%，当自身受到致命伤害时，会立刻瞬移至己方一名随机男性角色身边，使其在之后的5秒内，替自己承受伤害，该效果每场战斗只能触发一次",
	["tid#SkillDes_21642"]="等级2:潘金莲受到来自男性角色的伤害减少效果提升至50%",
	["tid#SkillDes_21643"]="等级3:受到致死伤害时，潘金莲还会使替自己承受伤害的己方侠客受到的伤害减少30%",
	["tid#SkillDes_21644"]="等级4:受到致死伤害时，潘金莲会优先瞬移至己方前排角色身后，且给予的减伤效果提升至40%",
