	["tid#SkillName_31451"]="花荣普攻",
	["tid#SkillDes_31411"]="花荣瞄准一名血量比例最低的敌方侠客，对其造成400%攻击力的伤害，该技能无法被闪避，若该技能成功击杀了敌方侠客，则花荣会立刻恢复500点内力",
	["tid#SkillDes_31412"]="等级2：伤害提升至430%攻击力，恢复内力效果提升至700点",
	["tid#SkillDes_31413"]="等级3：成功击杀敌人后，花荣的攻击力会提升20%，持续5秒，不可叠加",
	["tid#SkillDes_31414"]="等级4：成功击杀敌人后，花荣会立刻恢复满内力",
	["tid#SkillDes_31421"]="花荣攻击当前目标，对其造成180%攻击力的伤害，并附加5%敌方最大生命值的伤害，若该技能造成了暴击，则会额外释放一次，额外释放时会命中敌方全体目标，该技能最多单场战斗额外释放一次",
	["tid#SkillDes_31422"]="等级2：伤害提升至210%攻击力",
	["tid#SkillDes_31423"]="等级3：附加伤害提升至8%最大生命值",
	["tid#SkillDes_31424"]="等级4：该技能现在单场战斗最多能额外触发2次",
	["tid#SkillDes_31431"]="花荣在敌方随机目标脚下布置陷阱，当有敌人进入陷阱时，会受到200%攻击力的伤害并被束缚2秒，束缚期间敌人无法闪避",
	["tid#SkillDes_31432"]="等级2：束缚时间提升至3秒",
	["tid#SkillDes_31433"]="等级3：战斗开始时，花荣会立刻布置一个陷阱",
	["tid#SkillDes_31434"]="等级4：被陷阱束缚的敌方侠客，在束缚结束后还会减少20%攻击力，持续5秒",
	["tid#SkillDes_31441"]="战斗开始时，花荣会获得30%的暴击伤害提升，但战斗每过去5秒，暴击伤害的加成效果会减少10%，最多减少至0%",
	["tid#SkillDes_31442"]="等级2：当花荣成功击杀敌人时，暴击伤害加成会重置回初始状态",
	["tid#SkillDes_31443"]="等级3：战斗开始获得的暴击伤害加成提升至50%",
	["tid#SkillDes_31444"]="等级4：战斗开始获得的暴击伤害加成提升至70%",
