	["tid#SkillName_50951"]="卢俊义普攻",
	["tid#SkillDes_50911"]="卢俊义在己方后场位置降下麒麟阵图，阵图持续5秒，持续期间，阵图内的友军会获得20%的伤害提升，且受到的所有伤害都会由卢俊义承受（无法为队友承受中毒、裂伤效果）",
	["tid#SkillDes_50912"]="等级2:阵图持续时间提升至7秒",
