	["tid#array_tips_18"]="外伤增加30%，暴击率增加30，暴击效果增加20%",
	["tid#Herolife_216"]="出生于罗袖阁的名门，是当地远近闻名的貌美女子。潘金莲父亲是官拜知州，得益于此，她从很小就开始读书作画，是当地著名的才貌双绝。她所绘画和写作的一些浪漫主义作品由于她的美貌加持，引起了很大反响，追随者络绎不绝。当然了，向潘金莲提亲的人也是纷至沓来，只不过她都一一回绝了。后来，那些求而不得的人越来越多，渐渐出现了一些关于她的，扭曲了的传闻……",
	["tid#Herolegend1_216"]="罗袖阁名门潘家家主喜得千金，取名金莲。她出身时肩上就带着几片粉色胎记，像是几多娇艳鲜花。算命先生说，此女长大必是江山绝色，红颜祸水。因此，潘金莲从小被至于深闺之中，极少抛头露面。",
	["tid#Herolegend2_216"]="庭院深深，从小在高门大院中长大的潘金莲既没有伙伴，也没有玩乐。作为书香门第，潘家院内倒是有许多藏书。一个偶然的机会，小金莲阅读了父亲随手拿着的一本市井小说，从此便爱上了读书。只是父亲潘知州一直坚信女子无才便是德，不允许潘金莲去书斋。但在十岁的小金莲苦苦哀求下，府里的老管事还是答应偷偷放金莲去书斋看书。",
	["tid#Herolegend3_216"]="自此，潘金莲常常留连于书斋。潘金莲也开始尝试写一些浪漫主义的作品，起初她只是自娱自乐，不久后她开始假装是侍女所作让众多女侍品评。十岁时，家中为潘金莲聘请了一位女教习，教导金莲学习绘画，女工。这位教习与潘金莲志趣相投，常互相讨论文章，绘画。在教习的陪伴下，潘金莲绘画水平一日千里。",
	["tid#Herolegend4_216"]="终于，潘金莲按捺不住性子，她希望自己的作品能让更多人看到。于是她请求教习将自己的作品以笔名发布出去。潘金莲创作的这些浪漫主义作品，很快便引起了轰动，获得许多拥趸。但也有另一部分人认为写这些情情爱爱，非是正道。教习的身份很快被有心人查出，通过她锁定了这些作品的作者正是潘家大小姐。在一次本应只有家中女眷参与的祭祖仪式中，数十位好事者终于见到了这位大小姐本人。一时间，所有人都呆住了，他们从未见过如此貌美的女子。",
	["tid#Herolegend5_216"]="潘家大小姐不仅才华惊人，容貌更是倾国倾城的消息很快传遍了大江南北。也引得许多书生墨客开始追捧潘金莲的作品。在潘家，上门提亲的人踏破了门槛，这让潘金莲十分苦恼，但另一方面，她也欣喜于有更多的人看到了她的作品。",
	["tid#herolegend6_216"]="潘金莲的走红让她的父亲知州大人十分愤怒，她本就担心潘金莲的美貌惹出祸端，现在潘金莲成为火热议题，更是难以控制。于是他赶走了所有前来提亲的媒人，将潘金莲幽禁在家里。知州大人得知当今皇上正欲选妃，她打定主意让潘金莲进宫，给自己谋求荣华富贵。",
	["tid#herolegend7_216"]="潘金莲从父亲口中察觉了他的打算。潘金莲当然不愿意进宫，她已经被关的太久了，她不愿再去一个更加幽深的地方。为了自由，她第一次学会了利用自己的美貌，她告诉看守自己的侍卫，自己愿意和他私奔。于是在侍卫的帮助下，潘金莲轻松逃了出来。她看着身边一脸痴迷的侍卫，心中充满了对自由的期待。",
	["tid#herounlockedsaying_183"]="娶我？你可知，你又能从我这得到些什么……",
	["tid#herounlockedsaying_184"]="阅尽万卷，写诗作画，也不过是表达自我的手段而已。",
	["tid#herounlockedsaying_185"]="那些传闻，我并不在乎，不过是一些言论罢了。",
	["tid#poetry_216"]="眉眼似春面如花\\n  常含烟雨思朝霞\\n  笔下落得梦中意\\n  婀娜窈窕谁人家",
	["tid#Herolife_314"]="原为清风寨知寨，为救宋江，大闹清风寨。单凭一双弓箭，射遍天上地下，所以人称“小李广”。梁山座次排名第九，麾下十二队银枪手。又因是梁山第一美将军，所以和“金枪手”徐宁合称”风流威猛二将”。",
	["tid#Herolegend1_314"]="花荣邀请宋江前来清风山。宋江路上救了被王英掳上山的一名女子。她是清风寨知寨刘高之妻。不料刘高妻恩将仇报，唆使其夫在元夜观灯时将宋江抓住拷打。花荣大怒，抢回宋江并吓跑刘高军士。",
	["tid#Herolegend2_314"]="刘高告上青州，知府派都监黄信将花荣擒拿，与宋江一并押解青州。路上被清风山好汉救下，并杀了刘高。黄信逃回清风寨写信求救，知府命本州兵马总管“霹雳火”秦明带兵征剿清风山，花荣出阵与秦明大战，箭射秦明盔缨，后宋江设计收降秦明，花荣、黄信与清风山人马一同投奔梁山。",
	["tid#Herolegend3_314"]="花荣的箭法通神，世人皆知。上梁山后晁盖闻之不信，恰好天边有雁群飞过，花荣说要射第三只雁的雁头，弓开之处，弦响雁落，从此，满山之人无一不敬佩花荣。",
	["tid#Herolegend4_314"]="之后又随梁山众人江州劫法场， 智取无为军 ，三打祝家庄中射掉指路红灯， 攻打高唐州中射死薛元辉， 攻打大名府射杀李成副将，攻打曾头市时射中曾涂，救了即将中枪的吕方，曾涂中箭落马后被吕方、郭盛杀死。",
	["tid#Herolegend5_314"]="梁山大聚义中，花荣排行梁山第九，星号天英星，职务为马军八虎骑兼先锋使之首。朝廷第二次招安时，当花荣听见不赦免宋江时，花荣当场射杀了天使。在三败高太尉后，花荣随梁山众人受了招安。",
	["tid#herolegend6_314"]="征辽中，在檀州密云县和林冲、秦明、索超生擒了被张清用飞石打下马的阿里奇。一箭射中琼妖纳延，史进再一刀将琼妖纳延砍死。放箭协助关胜砍死兀颜光。。征田虎时，花荣一箭射死董澄。 打盖州时，花荣见张翔用箭射中孙立的马，花荣便一箭射中方琼，再一箭射张翔以振军威。杨端想要报仇，射出的箭却被花荣接住反被射死。 伏击卞祥军的时候，花荣一箭射死冯翊。征王庆时，花荣、林冲杀了阙翥、翁飞二将。征方腊时，花荣一箭射死王仁。 后又在乌龙岭一箭射中江南方腊国国师邓元觉。",
	["tid#herolegend7_314"]="征方腊后，花荣为存活并回京的12员正将之一，被封应天府兵马都统制。 在应天府一日梦见了宋江说自己已被奸臣害死，葬在蓼儿洼，希望花荣来探望他，花荣到了蓼儿洼后看见吴用，原来吴用昨夜与花荣作了相同的梦，二人为了义气，双双吊死在蓼儿洼上。人们深感其义气，便将宋江、李逵、花荣、吴用四人合葬于蓼儿洼",
	["tid#herounlockedsaying_186"]="我一壶紫羽箭，一张画雕弓，即可荡平七八个山寨！",
	["tid#herounlockedsaying_187"]="气定神闲，临危不乱，方可 一箭定乾坤！",
	["tid#herounlockedsaying_188"]="作为将门之后，我的使命，就是辅佐一个良君！",
	["tid#poetry_314"]="绿锦袍明金孔雀\\n  红鞓带束紫鸳鸯\\n  参差半露黄金甲\\n  手执银丝铁杆枪",
	["tid#Herolife_509"]="祖居北京人士，一身好武艺，棍棒天下无双。所持麒麟黄金矛，麒麟黄金甲，宝马麒麟兽号称河北三绝。是林冲的师兄，燕青的旧主。开始不愿意加入梁山，曾和梁山群雄大战金沙滩。后被奸人陷害，为梁山好汉搭救。曾头市一战，活捉史文恭，为晁盖报仇，威震天下。梁山排名第二。",
	["tid#Herolegend1_509"]="卢俊义是五代居住北京城的大富商，自小热爱舞刀弄棒，武功天下第一，难逢敌手。梁山好汉为了赚卢员外上山。吴用假装算命先生，在卢俊义府上设计让他自己写下一首藏头反诗：“芦花丛里一扁舟，俊杰俄从此地游。义士若能知此理，反躬逃难可无忧。”并指出卢俊义大祸临头，唯有去梁山一趟方可保全。为了避祸，卢俊义只得前往梁山。\n",
	["tid#Herolegend2_509"]="卢俊义带着随从来到梁山，他自恃武艺高强，一人杀上梁山。接连大战梁山诸位头领，最终却还是在计谋之下束手就擒，被请上梁山。卢俊义不愿意在梁山落草为寇，但宋江等头领还是强留他带了两个多月、等卢俊义回家时，他早就被官府认定成为通缉犯了。就连妻子也已经与自己的管家暗通款曲，霸占了他的家产。",
	["tid#Herolegend3_509"]="卢俊义不相信自己会遭到背叛，任凭燕小乙如何相劝还是要回家看看。卢俊义回家后很快被官军围捕。管家李固诬陷卢俊义“勾结叛匪，准备里应外合攻打大名府”，告到大名府梁中书那里。梁中书随后将卢俊义抓捕进监狱。卢俊义被捕之后屈打成招，被打入死牢。",
	["tid#Herolegend4_509"]="在好友柴进和忠仆燕小乙的运作下，卢俊义免以死罪，不料管家李固早已买通官差要对他痛下杀手。卢俊义不得以杀了官差再次被打入大牢，幸得梁山好汉救援才逃出生天。走投无路的卢俊义最终答应加入梁山，位居第二把交椅。",
	["tid#Herolegend5_509"]="卢俊义上山后，宋江请卢俊义坐第一把交椅，卢俊义不受。于是宋江提议谁捉住史文恭谁就为山寨之主。二人各自带队兵分两路攻打曾头市，宋江率先攻破，但史文恭却逃脱。史文恭正撞上卢俊义，被卢俊义生擒。宋江再次请卢俊义做头把交椅，卢俊义坚决不从。",
	["tid#herolegend6_509"]="之后卢俊义南征北战，梁山受招安之后更是屡立战功。征辽之战中，卢俊义大显神威，独自跃马挺枪与大辽四员猛将酣战一个时辰，最后战胜耶律宗霖，吓跑耶律宗雷、耶律宗电和耶律宗云。紧接着，卢俊义又将一伙约有一千多人的辽兵杀得四散奔逃。",
	["tid#herolegend7_509"]="在平方腊之后，宋朝朝廷封其为武功大夫、庐州安抚使兼兵马副总管。后因同杨戬、高俅有矛盾，被杨戬、高俅设计在皇帝的御酒里放入水银，卢俊义喝后不能骑马，在泗州淮河乘船时因醉失足落水而死。",
	["tid#herounlockedsaying_189"]="今有梁山兄弟相劝，寸心如割，坐立不安，当连夜前往。",
	["tid#herounlockedsaying_190"]="这等燕雀，安敢和鸿鹄厮并！",
	["tid#herounlockedsaying_191"]="我此一生，经过风风雨雨，早已脱胎换骨。",
	["tid#poetry_509"]="神奇马快似腾云\\n  人才武艺两超群\\n  杀场临敌冲万马\\n  上天降下恶星辰",
