	["tid#SkillName_41551"]="蒙武堂普攻",
	["tid#SkillDes_41511"]="蒙武堂进入防御姿态8秒，期间免疫控制，受到的伤害减少30%，且每秒会恢复自身生命值3%的血量，技能结束时，会对自身周围的敌人造成300%攻击力的伤害和2秒眩晕效果",
	["tid#SkillDes_41512"]="等级2:减伤效果提升至40%",
	["tid#SkillDes_41513"]="等级3:回血效果提升至5%最大生命值",
	["tid#SkillDes_41514"]="等级4:伤害提升至350%攻击力",
	["tid#SkillDes_41521"]="蒙武堂重锤地面，对前方范围内的敌人造成260%攻击力的伤害和持续2秒的眩晕效果，该技能成功命中敌人后，蒙武堂会获得15%的防御加成和20%伤害减免，持续5秒，且每额外命中一个敌人，防御加成还会额外提升5%，最多额外提升15%",
	["tid#SkillDes_41522"]="等级2:伤害提升至280%攻击力",
	["tid#SkillDes_41523"]="等级3:击中敌人获得的防御加成提升至10%",
	["tid#SkillDes_41524"]="等级4:防御提高效果的持续时间提升至7秒",
	["tid#SkillDes_41531"]="战斗第5秒蒙武堂会帮血量百分比最少队友承受伤害2秒，对并对自身周围造成200%的伤害和6秒嘲讽效果，该技能每场战斗仅能触发一次（无法为队友承受中毒、裂伤效果）",
	["tid#SkillDes_41532"]="等级2:为队友承受伤害的时间提升至3秒",
	["tid#SkillDes_41533"]="等级3:嘲讽时间提升至8秒",
	["tid#SkillDes_41534"]="等级4:嘲讽同时每秒回复自身血量3%",
	["tid#SkillDes_41541"]="战斗开始，为蒙武堂恢复5%最大生命值的血量，该技能每20秒仅能触发一次",
	["tid#SkillDes_41542"]="等级2:触发间隔缩短至15秒",
	["tid#SkillDes_41543"]="等级3:恢复的血量提升至8%最大生命值",
	["tid#SkillDes_41544"]="等级4:恢复的血量提升至10%最大生命值",
	["tid#SkillDes_41551"]="蒙武堂普攻",
	["tid#Herolife_415"]="阿宝音是草原响当当的勇士，在草原之上已经不再有人是他的对手，为了寻找更强大的对手，他将目标看向了南边的中原，也许那边有一片更大的天地来等着他施展草原勇士的雄威。",
	["tid#Herolegend1_415"]="阿宝音出生的家族，原本是一个落魄的家族，但是先祖曾经的荣光不停的从父亲的口中灌输进阿宝音的耳朵里，让阿宝音从小就觉得自己一定上天选中的人——他从小便决心复兴自己家族的荣耀。因此阿宝音从小就以非常人的标准要求自己，胃口要比所有人都大，力气也要比所有人都大。",
	["tid#Herolegend2_415"]="长大后的阿宝音可以拉开部落里最重的一张弓，骑射功夫也傲然草原，但是他更痴迷于绝对的力量，他始终坚信，在绝对的力量面前，所以技巧都是苍白的。会产生这样的观念，源自一次狼群袭击了羊群，狡诈的狼群的试探攻击让阿宝音的强弓一时间毫无用武之地，因为狼群总是在他试图拉弓时发起攻击，暴怒的阿宝音直接挥舞着拳头将狼群锤杀殆尽。",
	["tid#Herolegend3_415"]="徒手搏狼的声名一时间也响彻草原，家族的名声也随之有了些声势。听闻草原上有这样的勇士，也有不少的家族纷纷前来投来邀请，然而面对这些拉拢，却被阿宝音的父亲一一回绝了。正是这位向阿宝音灌输家族荣耀的人不允许自己家族的声名被别的家族蚕食。",
	["tid#Herolegend4_415"]="那些试图招揽阿宝音的家族也不是无缘无故的，几年一度的草原盛世，一场隆重的大会正在筹办，草原上的勇士们会代表自己的家族来参加这场盛大的聚会，能够拔得头筹的人，其所在家族将获得无与伦比的荣耀，整个草原都会响彻这个家族的名字。阿宝音和他的父亲都明白，自己重盛家族的声名的机会来了。",
	["tid#Herolegend5_415"]="原本以为一切都顺利的阿宝音在骑射马术上都拔得了头筹，直到与人角力摔跤之时却遇到了对手，但是看此人装扮面向却并非是草原人。便正如同阿宝音预料的那样，他最后的对手是个中原人，字号夔王山刑天，身高斐然，壮硕如山，每走一步都势大力沉，如坠千钧……败于他手之后，阿宝音开始萌发了对中原的好好奇心，似乎自己只要掌握了中原的功夫，配合自己得天独厚的身体条件定然能成就一番伟业。",
	["tid#herolegend6_415"]="不过，在被夔王山刑天击败之后，此人便成了阿宝音的心魔，他总是耿耿于怀立誓一定要战胜他。于是他在处理好家族事务之后，一路跟随刑天来到中原。遭到跟随的夔王山自然也不是毫无察觉，夔王山反倒是对这个年轻的草原汉子起了兴趣。",
	["tid#herolegend7_415"]="夔王山的刑天多次与阿宝音交手之后，愈发喜欢上了这个不止有一身蛮力的小子，经过对他经脉修炼上的点拨，阿宝音成长的速度令刑天也十分吃惊。只不过天下无不散的筵席，很快夔王山收到一封赤羽密令，于是刑天交给阿宝音一根赤羽作为信物，假如哪天阿宝音觉得自己完全有把握战胜自己了，便在江湖上凭着这支羽毛来寻找自己，不过那时候可就不会再手下留情了。",
	["tid#herounlockedsaying_192"]="雄鹰为我探路，骏马带我驰骋。",
	["tid#herounlockedsaying_193"]="我是草原的意志！",
	["tid#herounlockedsaying_194"]="谁来与我一战？",
	["tid#poetry_415"]="力撼山无极\\n  平地四海通\\n  敕勒苍山下\\n  策马纵如风",
	["tid#PSkillDes_90010111"]="立刻为全体己方奇兽恢复相当于旺财<color=#3BADE7>80%</color>攻击力的生命值，并且在之后的3秒内，每秒持续恢复<color=#3BADE7>24%</color>攻击力的生命值。\n若旺财在斗气阶段胜出，该技能获得强化：立刻治疗的生命值提升至<color=#3BADE7>120%</color>攻击力，持续治疗的生命值提升至<color=#3BADE7>36%</color>攻击力",
	["tid#PSkillDes_90010112"]="每次释放绝技时，有50%概率进入【招财】状态。\n招财状态：本次释放绝技时，额外增加<color=#3BADE7>200%</color>攻击力的护盾，并移除招财状态。",
	["tid#PSkillDes_90010113"]="所有被治疗的奇兽，可从【攻击力提升<color=#3BADE7>1%</color>，暴击概率提升<color=#3BADE7>1%</color>，伤害增加提升<color=#3BADE7>1%</color>】中随机获得1个增益效果，该效果持续整局战斗，且最多叠加至5层。",
	["tid#PSkillDes_90010114"]="绝技效果获得强化：治疗后持续恢复时长增加<color=#3BADE7>2</color>秒，当旺财处于【招财】状态下时，持续恢复时长再额外增加<color=#3BADE7>1</color>秒",
	["tid#PSkillDes_90010115"]="战斗开始时，旺财的内力恢复速率提升<color=#3BADE7>10%</color>。若旺财在斗气阶段胜出，其内力恢复速率额外提升<color=#3BADE7>10%</color>",
	["tid#PSkillDes_90010118"]="旺财在场时，每隔8秒，旺财随机选中一名己方后排侠客施加一个护盾，该护盾可以减少下次伤害的<color=#3BADE7>40%</color>。\n当击败敌方宠物后，效果强化为：旺财一次可施加<color=#3BADE7>3</color>个护盾守护后排侠客（强化效果在敌方未上阵奇兽单位时不生效）",
	["tid#PSkillDes_90010121"]="立刻为全体己方奇兽恢复相当于旺财<color=#ED74F8>100%</color>攻击力的生命值，并且在之后的<color=#ED74F8>3</color>秒内，每秒持续恢复<color=#ED74F8>30%</color>攻击力的生命值。\n若旺财在斗气阶段胜出，该技能获得强化：立刻治疗的生命值提升至<color=#ED74F8>150%</color>攻击力，持续治疗的生命值提升至<color=#ED74F8>45%</color>攻击力",
	["tid#PSkillDes_90010122"]="每次释放绝技时，有50%概率进入【招财】状态。\n招财状态：本次释放绝技时，额外增加<color=#ED74F8>250%</color>攻击力的护盾，并移除招财状态。",
	["tid#PSkillDes_90010123"]="所有被治疗的奇兽，可从【攻击力提升<color=#ED74F8>2%</color>，暴击概率提升<color=#ED74F8>2%</color>，伤害增加提升<color=#ED74F8>2%</color>】中随机获得1个增益效果，该效果持续整局战斗，且最多叠加至5层。",
	["tid#PSkillDes_90010124"]="绝技效果获得强化：治疗后持续恢复时长增加<color=#ED74F8>2秒</color>，当旺财处于【招财】状态下时，持续恢复时长再额外增加<color=#ED74F8>2秒</color>",
	["tid#PSkillDes_90010125"]="战斗开始时，旺财的内力恢复速率提升<color=#ED74F8>15%</color>。若旺财在斗气阶段胜出，其内力恢复速率额外提升<color=#ED74F8>15%</color>",
	["tid#PSkillDes_90010128"]="旺财在场时，每隔8秒，旺财随机选中一名己方后排侠客施加一个护盾，该护盾可以减少下次伤害的<color=#ED74F8>50%</color>。\n当击败敌方宠物后，效果强化为：旺财一次可施加<color=#ED74F8>3</color>个护盾守护后排侠客（强化效果在敌方未上阵奇兽单位时不生效）",
	["tid#PSkillDes_90010131"]="立刻为全体己方奇兽恢复相当于旺财<color=#bf7742>125%</color>攻击力的生命值，并且在之后的<color=#bf7742>3</color>秒内，每秒持续恢复<color=#bf7742>36%</color>攻击力的生命值。\n若旺财在斗气阶段胜出，该技能获得强化：立刻治疗的生命值提升至<color=#bf7742>180%</color>攻击力，持续治疗的生命值提升至<color=#bf7742>54%</color>攻击力",
	["tid#PSkillDes_90010132"]="每次释放绝技时，有50%概率进入【招财】状态。\n招财状态：本次释放绝技时，额外增加<color=#bf7742>300%</color>攻击力的护盾，并移除招财状态。",
	["tid#PSkillDes_90010133"]="所有被治疗的奇兽，可从【攻击力提升<color=#bf7742>3%</color>，暴击概率提升<color=#bf7742>3%</color>，伤害增加提升<color=#bf7742>3%</color>】中随机获得1个增益效果，该效果持续整局战斗，且最多叠加至5层。",
	["tid#PSkillDes_90010134"]="绝技效果获得强化：治疗后持续恢复时长增加<color=#bf7742>3秒</color>，当旺财处于【招财】状态下时，持续恢复时长再额外增加<color=#bf7742>2秒</color>",
	["tid#PSkillDes_90010135"]="战斗开始时，旺财的内力恢复速率提升<color=#bf7742>20%</color>。若旺财在斗气阶段胜出，其内力恢复速率额外提升<color=#bf7742>20%</color>",
	["tid#PSkillDes_90010138"]="旺财在场时，每隔8秒，旺财随机选中一名己方后排侠客施加一个护盾，该护盾可以减少下次伤害的<color=#bf7742>60%</color>。\n当击败敌方宠物后，效果强化为：旺财一次可施加<color=#bf7742>3</color>个护盾守护后排侠客（强化效果在敌方未上阵奇兽单位时不生效）",
	["tid#PSkillDes_90020111"]="吉祥朝前方喷出一道烈焰攻击敌方奇兽，对所有被烈焰击中的敌方造成<color=#3BADE7>160%</color>攻击力的伤害，并使其进入持续<color=#3BADE7>5秒</color>的灼烧状态。被灼烧的敌方，每秒将受到吉祥<color=#3BADE7>24%</color>攻击力的伤害。若吉祥在斗气阶段胜出，该技能获得强化：烈焰造成的伤害提升至<color=#3BADE7>240%</color>攻击力",
	["tid#PSkillDes_90020112"]="释放绝技后，吉祥进入【炎怒】状态，状态持续<color=#3BADE7>8秒</color>。\n【炎怒】状态：吉祥的攻速提升<color=#3BADE7>80%</color>",
	["tid#PSkillDes_90020113"]="被灼烧的敌方，防御减少<color=#3BADE7>40%</color>",
	["tid#PSkillDes_90020114"]="吉祥普攻被灼烧的敌方，额外追加一次<color=#3BADE7>100%</color>攻击力的伤害",
	["tid#PSkillDes_90020115"]="战斗开始时，吉祥获得<color=#3BADE7>30%</color>伤害增加，持续<color=#3BADE7>10秒</color>。若吉祥在斗气阶段胜出，其伤害增加持续时间额外提升<color=#3BADE7>5秒</color>",
	["tid#PSkillDes_90020118"]="战斗开始时，吉祥会召唤一个免疫侠客伤害的分身攻击敌方侠客，分身优先继承随机一位己方射手侠客<color=#3BADE7>20%</color>攻击力。当吉祥阵亡后分身消失。\n击败敌方宠物后，分身加强：继承攻击力提升至<color=#3BADE7>25%</color>（强化效果在敌方未上阵奇兽单位时不生效）",
	["tid#PSkillDes_90020121"]="吉祥朝前方喷出一道烈焰攻击敌方奇兽，对所有被烈焰击中的敌方造成<color=#ED74F8>200%</color>攻击力的伤害，并使其进入持续<color=#ED74F8>5</color>秒的灼烧状态。被灼烧的敌方，每秒将受到吉祥<color=#ED74F8>30%</color>攻击力的伤害。\n若吉祥在斗气阶段胜出，该技能获得强化：烈焰造成的伤害提升至<color=#ED74F8>300%攻击力</color>",
	["tid#PSkillDes_90020122"]="释放绝技后，吉祥进入【炎怒】状态，状态持续<color=#ED74F8>8</color>秒。\n【炎怒】状态：吉祥的攻速提升<color=#ED74F8>100%</color>",
	["tid#PSkillDes_90020123"]="被灼烧的敌方，防御减少<color=#ED74F8>50%</color>",
	["tid#PSkillDes_90020124"]="吉祥普攻被灼烧的敌方，额外追加一次<color=#ED74F8>120%</color>攻击力的伤害",
	["tid#PSkillDes_90020125"]="战斗开始时，吉祥获得<color=#ED74F8>40%</color>伤害增加，持续<color=#ED74F8>10秒</color>。若吉祥在斗气阶段胜出，其伤害增加持续时间额外提升<color=#ED74F8>5秒</color>",
	["tid#PSkillDes_90020128"]="战斗开始时，吉祥会召唤一个免疫侠客伤害的分身攻击敌方侠客，分身优先继承随机一位己方射手侠客<color=#ED74F8>25%</color>攻击力。当吉祥阵亡后分身消失。\n当击败敌方宠物后，分身加强：继承攻击力提升至<color=#ED74F8>30%</color>（强化效果在敌方未上阵奇兽单位时不生效）",
	["tid#PSkillDes_90020131"]="吉祥朝前方喷出一道烈焰攻击敌方奇兽，对所有被烈焰击中的敌方造成<color=#bf7742>250%</color>攻击力的伤害，并使其进入持续<color=#bf7742>5</color>秒的灼烧状态。被灼烧的敌方，每秒将受到吉祥<color=#bf7742>38%</color>攻击力的伤害。若吉祥在斗气阶段胜出，该技能获得强化：烈焰造成的伤害提升至<color=#bf7742>375%</color>攻击力",
	["tid#PSkillDes_90020132"]="释放绝技后，吉祥进入【炎怒】状态，状态持续8秒。\n【炎怒】状态：吉祥的攻速提升<color=#bf7742>125%</color>",
	["tid#PSkillDes_90020133"]="被灼烧的敌方，防御减少<color=#bf7742>60%</color>",
	["tid#PSkillDes_90020134"]="吉祥普攻被灼烧的敌方，额外追加一次<color=#bf7742>140%</color>攻击力的伤害",
	["tid#PSkillDes_90020135"]="战斗开始时，吉祥获得<color=#bf7742>50%</color>伤害增加，持续<color=#bf7742>10</color>秒。若吉祥在斗气阶段胜出，其伤害增加持续时间额外提升<color=#bf7742>5</color>秒",
	["tid#PSkillDes_90020138"]="战斗开始时，吉祥会召唤一个免疫侠客伤害的分身攻击敌方侠客，分身优先继承随机一位己方射手侠客<color=#bf7742>30%</color>攻击力。当吉祥阵亡后分身消失。\n当击败敌方宠物后，分身加强：继承攻击力提升至<color=#bf7742>35%</color>（强化效果在敌方未上阵奇兽单位时不生效）",
	["tid#PSkillDes_90030111"]="肥啾向天上随机洒出<color=#3BADE7>6</color>根羽毛（其中至少有1根皓羽，1根玄羽）\n皓羽效果：立刻为己方1只奇兽恢复相当于旺财<color=#3BADE7>40%</color>攻击力的生命值 \n玄羽效果：对任意1只敌方奇兽造成<color=#3BADE7>80%</color>攻击力的伤害\n若肥啾在斗气阶段胜出，技能效果强化为：羽毛数量额外增加<color=#3BADE7>3</color>根",
	["tid#PSkillDes_90030112"]="释放绝技时，羽毛数量再增加<color=#3BADE7>2</color>根",
	["tid#PSkillDes_90030113"]="玄羽会一直跟随附身目标 ,当目标身上的玄羽层数达到<color=#3BADE7>3</color>层时，立刻附身对目标进行一次【暗夜绞杀】，造成<color=#3BADE7>160%</color>攻击力的伤害，并且玄羽印记消失。",
	["tid#PSkillDes_90030114"]="皓羽会一直跟随附身目标，当目标身上的皓羽层数达到<color=#3BADE7>3</color>层时，立刻对附身目标进行一次【皓羽普渡】，立刻恢复<color=#3BADE7>120%</color>攻击力的生命值，并且皓羽印记消失。",
	["tid#PSkillDes_90030115"]="每释放一次大招，肥啾自身攻速提升<color=#3BADE7>8%</color>，效果持续全场\n斗气胜利时，额外提升<color=#3BADE7>4%</color>攻速",
	["tid#PSkillDes_90030118"]="肥啾在场时，每隔15秒会随机选中一名己方侠客施加最多可叠加1层的【翎佑】印记，并在接下来的3秒中免疫控制。随后印记消失并会产生小范围爆炸，并造成<color=#3BADE7>1%</color>侠客最大生命值的伤害。\n当击败敌方宠物后，效果强化为：免疫控制后，爆炸伤害提升至<color=#3BADE7>3%</color>（强化效果在敌方未上阵奇兽单位时不生效）",
	["tid#PSkillDes_90030121"]="肥啾向天上随机洒出<color=#ED74F8>6</color>根羽毛（其中至少有1根皓羽，1根玄羽）\n皓羽效果：立刻为己方1只奇兽恢复相当于旺财<color=#ED74F8>50%</color>攻击力的生命值 \n玄羽效果：对任意1只敌方奇兽造成<color=#ED74F8>100%</color>攻击力的伤害\n若肥啾在斗气阶段胜出，技能效果强化为：羽毛数量额外增加<color=#ED74F8>3</color>根",
