	["tid#PSkillDes_90030123"]="玄羽会一直跟随附身目标 ,当目标身上的玄羽层数达到<color=#ED74F8>3</color>层时，立刻附身对目标进行一次【暗夜绞杀】，造成<color=#ED74F8>200%</color>攻击力的伤害，并且玄羽印记消失。",
	["tid#PSkillDes_90030124"]="皓羽会一直跟随附身目标，当目标身上的皓羽层数达到<color=#ED74F8>3</color>层时，立刻对附身目标进行一次【皓羽普渡】，立刻恢复<color=#ED74F8>150%</color>攻击力的生命值，并且皓羽印记消失。",
