	["tid#SkillDes_90010111"]="立刻为全体己方奇兽恢复相当于旺财80%攻击力的生命值，并且在之后的3秒内，每秒持续恢复24%攻击力的生命值。\n若旺财在斗气阶段胜出，该技能获得强化：立刻治疗的生命值提升至120%攻击力，持续治疗的生命值提升至36%攻击力",
	["tid#SkillDes_90010112"]="每次释放绝技时，有50%概率进入【招财】状态。\n招财状态：本次释放绝技时，额外增加200%攻击力的护盾，并移除招财状态。",
	["tid#SkillDes_90010113"]="所有被治疗的奇兽，可从【攻击力提升1%，暴击概率提升1%。，伤害增加提升1%。】中随机获得1个增益效果，该效果持续整局战斗，且最多叠加至5层。\n",
	["tid#SkillDes_90010114"]="绝技效果获得强化：治疗后持续恢复时长增加2秒，当旺财处于【招财】状态下时，持续恢复时长再额外增加1秒",
	["tid#SkillDes_90010115"]="战斗开始时，旺财的内力恢复速率提升10%。若旺财在斗气阶段胜出，其内力恢复速率额外提升10%",
	["tid#SkillDes_90010118"]="旺财在场时，每隔8秒，旺财随机选中一名己方后排侠客施加一个护盾，该护盾可以减少下次伤害的40%。\n当击败敌方宠物后，效果强化为：旺财一次可施加3个护盾守护后排侠客（强化效果在敌方未上阵奇兽单位时不生效）\n",
