	["tid#SkillDes_90040133"]="阿驼每释放一次绝技，己方全体奇兽立刻回复内力240点",
	["tid#SkillDes_90040134"]="阿驼血量首次降低至40%时，立刻恢复25%最大生命值的生命",
	["tid#SkillDes_90040135"]="阿驼的普攻会附带30%概率的晕眩，持续2秒。在斗气阶段胜利后，晕眩概率额外提升10%",
	["tid#SkillDes_90040138"]="阿驼在场时，每隔10秒为己方1名护卫侠客施加一个持续5秒的护盾，抵消相当于自身最大生命值的7%伤害\n当击败敌方宠物后，效果强化为：阿驼一次可施加2个护盾守护护卫侠客（强化效果在敌方未上阵奇兽单位时不生效）",
