	["tid#itemDes_5475"]="蕴含神秘力量的印记，可以在联动侠客进阶时代替任意一张四系联动侠客，尚在联动期间内的侠客不能使用",
	["tid#itemDes_5476"]="蕴含神秘力量的印记，可以在联动侠客进阶时代替任意一张阴阳系联动侠客，尚在联动期间内的侠客不能使用",
	["tid#PetStory_900101"]="传闻中会时常将自己收集到的钱币带回来给主人的“衔钱之猫”，个头虽小却机敏十足，寻常的习武之人都难以轻易对付。",
	["tid#PetStory_900201"]="一条尚在成长的幼龙，因为体内拥有江湖人人渴望的龙元而受到无尽的追逐，因此这个小家伙十分暴躁，经常喷射火焰来表达自己的不满。",
	["tid#PetStory_900301"]="飞跃于山林之间的神奇飞禽，因为喜食天材地宝，圆滚的身形之下富含浑厚的玄素真气。",
	["tid#PetStory_900401"]="原本是番邦进贡而来的神兽，后来流落江湖，传说此神兽十分高傲，稍有怠慢就会受到它无情的暗器攻击。",
