	["tid#SkillName_11651"]="扈三娘普攻",
	["tid#SkillDes_11611"]="扈三娘进入“战舞”状态5秒，立即恢复自身20%最大生命值的血量；“战舞”状态下，扈三娘的攻击力会提升50%，受到的伤害会减少40%",
	["tid#SkillDes_11612"]="等级2:“战舞”状态的持续时间提升至8秒",
	["tid#SkillDes_11613"]="等级3:受到伤害减少50%",
	["tid#SkillDes_11614"]="等级4:“战舞”状态下，扈三娘的攻击力提升至60%",
	["tid#SkillDes_11621"]="扈三娘重击当前目标，对其造成160%攻击力的伤害，并使其攻击力减少20%，持续5秒",
	["tid#SkillDes_11622"]="等级2:攻击力提升至180%",
	["tid#SkillDes_11623"]="等级3:攻击力减少效果提升至30%",
	["tid#SkillDes_11624"]="等级4:攻击力提升至200%",
	["tid#SkillDes_11631"]="扈三娘挥舞长刀，攻击自身周围的敌人，造成180%攻击力的外功伤害，且每释放一次该技能，伤害就提升10%，持续10秒，最多叠加5层",
	["tid#SkillDes_11632"]="等级2:造成200%攻击力的外功伤害",
	["tid#SkillDes_11633"]="等级3:造成220%攻击力的外功伤害",
	["tid#SkillDes_11634"]="等级4:伤害提升效果现在最多可以叠加8层",
	["tid#SkillDes_11641"]="战斗开始时，扈三娘会标记与自己位置相对的敌人，并立即降低其20%最大防御力和20%最大血量",
	["tid#SkillDes_11642"]="等级2:对位目标降低25%防御",
	["tid#SkillDes_11643"]="等级3:标记后，每秒恢复自身生命值3%血量，持续10秒",
	["tid#SkillDes_11644"]="等级4:自身受到伤害减少20%",
