	["tid#SkillName_51051"]="宋江普攻",
	["tid#SkillDes_51011"]="宋江在战场上召唤雷云，雷云会持续降下10道雷击，每道雷击都会攻击随机一名敌人，对其造成120%攻击力的内功伤害",
	["tid#SkillDes_51012"]="等级2:伤害提升至140%攻击力",
	["tid#SkillDes_51013"]="等级3:雷击数量提升至12道",
	["tid#SkillDes_51014"]="等级4:伤害提升至160%攻击力",
	["tid#SkillDes_51021"]="宋江对当前目标释放闪电链，对其造成200%攻击力的伤害，闪电链命中目标后会弹射一次，对目标周围的另一名敌人造成同等伤害",
	["tid#SkillDes_51022"]="等级2:伤害提升至220%",
	["tid#SkillDes_51023"]="等级3:若闪电链命中的目标身上有“雷霆”标记，则闪电链会额外弹射两名敌人",
	["tid#SkillDes_51024"]="等级4:伤害提升至240%",
	["tid#SkillDes_51031"]="宋江的普攻和技能在命中目标时，会为其添加一层“雷霆”标记，当标记叠加至3层时会被引爆，对当前目标造成180%攻击力的真实伤害并使其眩晕2秒；标记被引爆后的5秒内将无法添加新的标记",
	["tid#SkillDes_51032"]="等级2:引爆伤害提升至200%攻击力",
	["tid#SkillDes_51033"]="等级3:标记被引爆后5秒内，该敌人的内伤减免效果会降低20%",
	["tid#SkillDes_51034"]="等级4:引爆伤害提升至240%攻击力",
	["tid#SkillDes_51041"]="战斗中，当雷霆标记首次被引爆时，宋江将获得20%的伤害提升，之后每额外引爆一次，还会额外获得5%的伤害提升，最多额外提升20%",
	["tid#SkillDes_51042"]="等级2:首次引爆标记获得的伤害提升提高至25%",
	["tid#SkillDes_51043"]="等级3:额外伤害提升最多提高至30%",
	["tid#SkillDes_51044"]="等级4:首次引爆标记获得的伤害提升提高至30%",
