	["tid#SkillName_70444"]="天雄冷坠(等级4)",
	["tid#SkillName_70451"]="林冲普攻",
	["tid#SkillDes_70411"]="林冲锁定一名后排血量最少的敌方侠客，立即瞬移至其身后，并对其造成300%攻击力的伤害，并使其当前内力减少30%，同时自身增加暴击30%和暴伤50，持续5秒",
	["tid#SkillDes_70412"]="等级2:释放时若敌人身上有“寒星”效果，则该技能造成的伤害提升50%",
	["tid#SkillDes_70413"]="等级3:释放时若敌人处于被“冰冻”状态，则该技能造成的伤害翻倍且无视敌方免死效果",
	["tid#SkillDes_70414"]="等级4:伤害提升至350%攻击力",
	["tid#SkillDes_70421"]="林冲对当前目标快速攻击三次，每次造成120%攻击力的伤害，释放该技能后，林冲会获得80的攻速提升，持续5秒",
	["tid#SkillDes_70422"]="等级2:该技能每次造成伤害，都会为敌人施加一层“寒星”效果",
	["tid#SkillDes_70423"]="等级3:攻速提升效果提高至100",
	["tid#SkillDes_70424"]="等级4:每段伤害提升至180%攻击力，且最后一击必定命中且暴击",
	["tid#SkillDes_70431"]="战斗开始时，林冲会向自己相对位置掷出长枪，将敌人禁锢在原地，随后瞬移至其身后，对其造成300%攻击力的伤害并使其眩晕2秒",
	["tid#SkillDes_70432"]="等级2:被该技能命中的敌人会被施加2层“寒星”效果",
	["tid#SkillDes_70433"]="等级3:伤害提升至330%攻击力",
	["tid#SkillDes_70434"]="等级4:眩晕时间提升至3秒",
	["tid#SkillDes_70441"]="林冲每次普攻命中敌人时，会为其施加一层“寒星”效果，每层寒星效果会使其造成的伤害减少10%，内力恢复效果减少10%，最多叠加6层，持续5秒；当寒星效果叠加至6层时，会消耗所有效果立即引爆目标，对其造成350%攻击力的伤害并使其冰冻3秒，冰冻结束后，目标造成的伤害会减少60%，内力恢复效果减少60%，持续5秒",
	["tid#SkillDes_70442"]="等级2:引爆伤害提升至550%",
	["tid#SkillDes_70443"]="等级3:每次寒星效果被引爆后，林冲会无敌2秒",
	["tid#SkillDes_70444"]="等级4:冰冻后，目标造成伤害和内力恢复减少70%，同时每秒造成自身攻击120%伤害，持续5秒",
	["tid#SkillDes_70451"]="林冲普攻",
	["tid#Herolife_116"]="原为扈家庄千金。先和祝家庄联盟。一打祝家庄时，曾生擒“矮脚虎”王英，连败“摩云金翅”欧鹏和“铁笛仙”马鳞。梁山众将为之震惊。二打祝家庄时被林冲生擒。宋江收为义妹，与王英成婚。梁山排名第五十九，是梁山三女中武功最强的。又被人称为“梁山美艳第一。”",
	["tid#Herolegend1_116"]="扈三娘是独龙岗扈家庄庄主扈太公的女儿，自幼好习武，英武更胜男儿。扈家庄与祝家庄结盟，扈三娘也与祝家庄祝朝奉的三子祝彪定了亲。宋江率梁山大军攻打祝家庄，首战失利后再度来犯。扈三娘率领扈家庄援军前来支援，正遇上梁山军队。",
	["tid#Herolegend2_116"]="眼见扈三娘美貌，好色的王英拍马上前与扈三娘交战。边打边出言调戏扈三娘，惹得扈三娘大怒。扈三娘刀舞如风，王英很快招架不住，拨马退走，却被扈三娘追上，生擒了回去。",
	["tid#Herolegend3_116"]="欧鹏见王英被捉，便上阵来斗扈三娘，但扈三娘本领高强，欧鹏占不了她一点便宜。接着祝家庄与梁山众人陷入混战，扈三娘斗完欧鹏再斗马麟，好生英武。秦明被栾廷玉用计捉去，马麟便撇了扈三娘，来保护宋江。扈三娘见宋江骑马到处寻找有没有迷路的好汉，便飞马紧追宋江，恰好遇见李逵，只好改变方向，却又碰上了林冲，两个斗不到十合，扈三娘便被林冲捉去。",
	["tid#Herolegend4_116"]="扈三娘被捉后，宋江派人将她连夜送回梁山泊，交给他父亲宋太公看管。扈三娘的哥哥扈成见妹妹被捉，求见宋江，双方约定，扈家庄不再助祝家庄对抗梁山，如有祝家庄人投奔扈家庄，扈成就将他抓起来交给宋江，这样就可以把扈三娘放回去。\n后梁山攻破祝家庄，祝彪逃往扈家庄，被扈成派人抓住，献给宋江。行至半路遇到李逵，李逵一斧头砍了祝彪，又追着扈成要砍，扈成弃家逃命。李逵杀红了眼，冲到扈家庄里，杀了扈家庄一门老幼。梁山众将得胜回山。而在梁山上的扈三娘，此时已被宋太公收为义女。宋江此前在清风山曾许给王英一门亲事，于是就做主将扈三娘许配给王英。",
	["tid#Herolegend5_116"]="自此，扈三娘成为梁山上的一名女头领，在山上多数时候都与丈夫王英分派在一起行动。后来梁山的多次征战，扈三娘基本上都有参与。梁山大聚义、排座次，扈三娘的石碣排名为第五十九，星号地慧星，与丈夫王英共同担任专掌三军内探事马军头领。",
	["tid#herolegend6_116"]="梁山受招安后，扈三娘与王英作为将领参与了征辽、征田虎、征王庆、征方腊的战争。征辽时，扈三娘与辽国天寿公主答里孛交战，助王英活捉答里孛。征田虎时，扈三娘杀对方将领盛本，与对方女将琼英对战，但占不了上风，于是顾大嫂也来助阵，三女将斗到二十余合，琼英拨马便走，扈三娘在追赶时手腕中了琼英一颗飞石，撇下一把刀便回本阵。",
	["tid#herolegend7_116"]="征方腊阶段，扈三娘王英一同去攻打睦州。方腊派出“灵应天师”包道乙和他的徒弟“郑魔君”郑彪，以及猎户出身的将领夏侯成去救应。王英、扈三娘夫妻两人带着三千马军，正迎上了郑彪，郑彪先与王英交战，战到八九合，突然用法术变出一个金甲神人，吓得王英手忙脚乱，被刺下马。扈三娘见丈夫落马，急忙来救，与郑彪打了一合，郑彪回马便走，扈三娘追赶时，郑彪用一块镀金铜砖打中她面门，将她打落下马而死。征方腊结束后，扈三娘被宋朝朝廷加封为花阳郡夫人。",
	["tid#herounlockedsaying_195"]="就这功夫，还想收我做压寨夫人？哼！",
	["tid#herounlockedsaying_196"]="若有来生，我还会选择这一身戎装，但我或许不会再上梁山……",
	["tid#herounlockedsaying_197"]="我心知，我只有两个选择，但我…绝不选宋江！",
	["tid#poetry_116"]="双刀把雄兵乱砍\\n  纤手将敌人生拿\\n  天然美貌海棠花\\n  一丈青当先出马",
	["tid#Herolife_510"]="郓城县宋家村人士。因为面黑身矮，人都唤他黑宋江；在家大孝，为人仗义疏财，所以又称为孝义黑三郎。他刀笔精通，吏道纯熟；更兼爱习枪棒，学得多种武艺。平生爱好结识江湖上的英雄好汉，有人前来投奔无论任何人都细心款待，尽力资助；常替人排忧解难，救死扶伤，名震山东、河北，人们将他比作天上的及时雨。所谓“山东呼保义，豪杰宋公明”。梁山排第一。",
	["tid#Herolegend1_510"]="宋江原为山东郓城县押司。为人仗义疏财，爱接济好汉，人称“山东呼宝义，孝义黑三郎，及时雨宋江”。晁盖等七人劫掠生辰纲，引来官府抓捕。多亏宋江通风报信，晁盖一行才得以逃脱。晁盖遂让刘唐带一百两黄金，并修书一封答谢宋江。宋江只收下书信，只在刘唐的恳求下取了一条黄金。然而书信却被宋江外室阎婆惜发现，并以此威胁宋江。宋江无奈之下怒杀阎婆惜，在向父亲告别后开始亡命天涯。",
	["tid#Herolegend2_510"]="宋江来到柴进庄上，结识了武松。二人分别后宋江投奔孔家庄，再次救下被误抓的武松。之后宋江欲往清风寨投奔花荣，不料在途中被清风山好汉劫上山，结识了王英等，并救下了清风寨知寨刘高的妻子。待宋江来到清风寨，恩将仇报的刘高之妻指认宋江为匪盗，导致宋江被捕入狱。幸得王英、燕顺、郑天寿相救。",
	["tid#Herolegend3_510"]="黄信的师父秦明性急想给徒弟报仇，结果被擒，于是宋江用计让秦明、黄信都入伙上山。宋江提议弃了清风寨投奔梁山，众人决定聚义梁山。此时宋江却收到父亲病故的消息，宋江悲痛愧疚回乡奔丧，到家时却发现宋太公安然无恙，原来是宋父为了骗宋江回家谎称自己已病逝。官府得到消息，前来捉拿，宋江被擒。",
	["tid#Herolegend4_510"]="宋江在发配途中被梁山人马所救，但宋江不愿落草，吴用遂写信给江州的押牢节级戴宗托他照顾宋江。到达江州后，宋江广施人情，上下打点，又结交了戴宗、李逵、张顺等人，暂时安顿下来。一次宋江酒醉，郁发于外，在浔阳楼墙上提写了一首反诗，被黄文炳告发，宋江被打入大牢，等候问斩。为救宋江，吴用伪造信件，但却因不谨慎导致戴宗也被捕，在二人行刑将要被处决那天，梁山、揭阳两路人马齐聚，劫走了宋江。二十九人在白龙庙英雄小聚义。在宋江的带领下，众人杀回江州杀了黄文炳，随后一同前往梁山。",
	["tid#Herolegend5_510"]="宋江上山后，坐了第二把交椅。并带领梁山人马出征，先后攻打祝家庄，高唐州。又大破连环马，攻打青州，大闹华州，一系列胜利让宋江在梁山威望大增，梁山的实力也进一步增强。",
	["tid#herolegend6_510"]="晁盖在攻打曾头市时，被史文恭毒箭射死，宋江率领人马攻破曾头市为晁盖报仇，而后又与卢俊义分别攻打东平府和东昌府，最终成为梁山之主 。后来，梁山主事厅由聚义厅改为忠义堂，头目增长到了一百单八将，又相继两胜童贯、三胜高俅、大胜十位节度使，并活捉高俅，梁山事业也发展到了鼎盛 。",
	["tid#herolegend7_510"]="宋江带领梁山泊义军接受招安，正遇辽兵侵犯，宋江受诏破辽。于是大军北进，攻下檀州、蓟州、霸州、幽州，兵围燕京，辽主请罪投降。宋江班师回国，遵照徽宗旨意，将所夺州县仍退还给了辽邦 。破辽成功后，宋江等梁山军又奉旨平定了河北田虎、淮西王庆、江南方腊。",
	["tid#herounlockedsaying_198"]="我等相聚梁山，为的就是除暴安良，替天行道！",
	["tid#herounlockedsaying_199"]="我宋江满腹经纶，一腔忠心赤胆，你睁眼看看！",
	["tid#herounlockedsaying_200"]="想我梁山聚义时，一百单八人何等热闹，今日功成名就却做鸟兽散，难道我宋江错了？",
	["tid#poetry_510"]="心在山东身在吴\\n  飘蓬江海漫嗟吁\\n  他时若遂凌云志\\n  敢笑黄巢不丈夫",
	["tid#Herolife_704"]="东京八十万禁军教头。因为高俅之子高衙内垂涎林冲妻子，高俅伙同陆谦设计使林冲误入白虎堂，被发配沧州。途中在野猪林由鲁智深搭救，幸免遇难。但高俅又使人火烧草料场，林冲才大闹山神庙，格杀陆谦，雪夜上梁山。后来火并王伦，拥立晁盖为梁山之主。梁山座次排在第六。一杆枪，天下无敌，从无败绩。",
	["tid#Herolegend1_704"]="林冲落草梁山之前，本是东京人士。他出生武人之家，自幼习武，在军中担任八十万禁军枪棒教头。又娶了张教头女儿张氏为妻，生活幸福美满。",
	["tid#Herolegend2_704"]="一日林冲与妻子到岳庙还愿，在门口听闻棍棒之声，遂让妻子先去，自己在外等候。林冲顺着声响，遇见鲁智深，二人一见如故。林冲本想与鲁智深坐下吃酒，不料使女前来通报，说是林娘子被人纠缠。林冲急忙赶回，正准备教训那贼人，却发现此人是太尉高俅之子高衙内。因为不愿得罪高俅，林冲只得悻悻作罢。但高衙内却淫心不死，又串通林冲好友陆谦使计，所幸得林冲及时发现未能得逞。",
	["tid#Herolegend3_704"]="高衙内得不到张氏竟卧病不起，高俅为了自己爱子，决心设计陷害林冲。事先暗中命人将自己的宝刀卖与林冲，过了几日后再让下人以看刀为名将林冲带入太尉府，进入白虎堂。白虎堂是商议军机大事之处，林冲怎能轻易进入？等林冲惊觉时已晚，高俅突然出现，指控林冲手执利刃闯入白虎堂。林冲百口莫辩，被判刺配沧州。",
	["tid#Herolegend4_704"]="刺配沧州途中，林冲由公差二人押送。这两个公差早已被高俅收买，准备在路上杀死林冲。在路过一个酒店之时，二人故意使用开水给林冲洗脚，并给他换上一双草鞋，使得林冲脚底磨出大水泡。在野猪林时，二公差将林冲绑在树上，欲结果林冲。幸好随后鲁智深一路尾随，林冲才免于被贼人所害。",
	["tid#Herolegend5_704"]="其后林冲路过“小旋风”柴进府上，柴进见他是赫赫有名的八十万禁军教头林冲，心中大喜，厚礼款待。洪教头随后前来，此人极度傲慢，对林冲步步紧逼，引发了柴进的不快，再加上柴进想看下两人的本事，便安排了两人的比武，还设了彩头。林冲迫不得已和洪教头比武。开始林冲让着洪教头，不用兵器和之争斗，但是洪教头不领情，结果林冲轻松击败了他。洪教头羞愧地离开了。",
	["tid#herolegend6_704"]="林冲被发配沧州牢城后，凭借柴进的书信，又上下打点，被分配负责看守天王堂。陆谦，富安等人暗害之心不死，一番操作竟将林冲差去看守草料场，而陆谦、富安二人则设计放火烧毁草料场，意图趁机谋害林冲性命。万幸的是，林冲却因为住处被大雪压垮，无奈露宿山神庙躲过一劫。回到山神庙的林冲凑巧听见门外陆谦和富安、牢城管营的谈话，得知他们对自己的阴谋。愤怒之下林冲终于爆发，杀了三人，冒着风雪连夜投奔梁山泊。",
	["tid#herolegend7_704"]="林冲上了梁山之后，遭到梁山泊时任寨主的王伦排挤。王伦忌惮林冲的能力，担忧林冲威胁他的地位，因此一直想赶走林冲，因此林冲内心积怨已久。不久后，晁盖等七人前来梁山投奔，王伦仍是百般为难不愿接受。林冲终于不再忍耐，一刀结果了王伦，又尊晁盖为山寨之主。自此之后，梁山逐渐壮大，林冲也立下汗马功劳。",
	["tid#herounlockedsaying_201"]="我林冲自幼受先父教诲，专爱结识英雄好汉，一肚子侠义心肠。",
	["tid#herounlockedsaying_202"]="这世道……官逼民反啊，奸臣当道，不遇明主，逼上梁山！",
	["tid#herounlockedsaying_203"]="他年若得志，威镇泰山东。",
	["tid#poetry_704"]="嵌宝头盔稳戴\\n  磨银铠甲重披\\n  丈⼋蛇⽭紧挺\\n  霜花骏马频嘶",
	["tid#EquipAffixDes1109"]="核心：一丈青装备时，吸血等级提高10",
	["tid#EquipAffixDes2309"]="核心：豹子头装备时，攻击速度提高12，外伤加深提高5%",
	["tid#EquipAffixDes3309"]="核心：及时雨装备时，最终伤害提升12%",
