	["tid#HeroName_117"]="神剑门",
	["tid#HeroTypeDes_117"]="职业：战士  装备：铠甲",
	["tid#SkillDes_11711"]="神剑门重击前方敌人，对其造成300%攻击力的伤害和2秒的眩晕效果，释放该技能后，神剑门会进入“真·神剑”姿态6秒，期间攻击力增加40%",
	["tid#SkillDes_11712"]="等级2:持续时间提升至8秒",
	["tid#SkillDes_11713"]="等级3:伤害提升至320%攻击力",
	["tid#SkillDes_11714"]="等级4:攻击力提升效果提高至50%",
	["tid#SkillDes_11721"]="神剑门向前突刺，对目标造成240%攻击力的伤害并使其防御力降低20%，持续5秒，释放时若自身处于神剑状态，则该技能会获得强化，变为对目标造成多段，攻击350%攻击力的伤害并使其防御力降低30%，持续8秒",
	["tid#SkillDes_11722"]="等级2:突刺伤害提升至260%攻击力，防御力降低效果提升至30%",
	["tid#SkillDes_11723"]="等级3:多段攻击伤害提升至370%攻击力，防御力降低效果提升至40%",
	["tid#SkillDes_11724"]="等级4:当自身处于“神剑“或“真·神剑”状态时，被命中的敌人还会被眩晕2秒",
	["tid#SkillDes_11731"]="神剑门进入蓄力姿态3秒，蓄力期间，自身受到的伤害减少80%，蓄力结束后会向前挥击，对范围内的敌人造成200%攻击力的伤害和2秒眩晕效果，释放完该技能后，神剑门会短暂进入“神剑”状态2秒",
	["tid#SkillDes_11732"]="等级2:伤害提升至220%攻击力",
	["tid#SkillDes_11733"]="等级3:蓄力期间，神剑门受到攻击获得的内力值会提升50%",
	["tid#SkillDes_11734"]="等级4:释放该技能后，自身进入神剑状态的持续时间提升至3秒",
	["tid#SkillDes_11741"]="每次进入“神剑”或“真·神剑”状态时，会获得30%伤害减免和30点吸血效果，该效果不可叠加",
	["tid#SkillDes_11742"]="等级2:伤害减免效果提升至40%",
	["tid#SkillDes_11743"]="等级3:每次退出“神剑”或“真·神剑”状态时，会恢复10%最大生命值的血量",
	["tid#SkillDes_11744"]="等级4:伤害减免效果提升至50%",
