	["tid#SkillName_11751"]="神剑门普攻",
	["tid#itemName_5523"]="开心罐头",
	["tid#itemDes_5523"]="可以提升奇兽心情的神奇食物，一口一个，心情倍儿棒！",
	["tid#Herolife_117"]="原本被江湖戏称为“一步剑圣”的谢小风如今重现江湖，过往种种传奇似乎也被江湖人所淡忘，没人清楚原先的留言给他带来过多少屈辱与不甘，但是而今的谢小风是令中天君剑圣——宇文元亨也不敢小觑的角色。",
	["tid#Herolegend1_117"]="谢小风是神剑门门主谢天仪的独子，老来得子的谢天仪对谢小风可谓是宠爱有加，也使得谢小风从小便骄纵跋扈，不过谢小风也天资聪慧，体质异于常人，小小年纪便精通家传绝学。",
	["tid#Herolegend2_117"]="后来谢小风稍长，便想着在江湖闯荡一下，老门主自然是答应了下来，心想自己年事也高了，该让儿子在江湖上有了些名气，也好将门主之位传给自己这宝贝似的儿子手上。果不其然，谢小风剑技傲然，击败多少使剑的英豪，一时声名响彻江湖。",
	["tid#Herolegend3_117"]="然而，年纪轻轻便志得意满的谢小风跋扈的行事风格也很快遭到了江湖人的不满，有些人甚至嘲笑他为“一步剑圣”，意思是他差一步就能赶得上剑圣了，但是总是不如剑圣。也许常人看来这话或许是夸奖，但是在谢小风耳中，这是对他实力不折不扣的讽刺，他认为自己的剑已经无敌于天下了。",
	["tid#Herolegend4_117"]="谢小风愤愤之下参加名剑大会，希望能跟传闻中的剑圣一决高下，却不想剑圣虽然接下了名剑山庄的请帖却并未参加大会，谢小风决战之日见并未有剑圣身影因此也没有参加后面的对决，如今在他的眼里，只有中天君剑圣才有资格成为他的对手。",
	["tid#Herolegend5_117"]="然而谢小风无论如何公开叫嚣和挑衅，中天君都无动于衷，急于证名的他行事愈发乖张，与人一言不合便大打出手以泄心头愤恨，“一步剑圣”之名反而越传越广。终于一日，谢小风又与人动武，正当要泄愤下狠手之时，却被一路人信手阻止，后来方知那便是传闻中的剑圣——中天君，宇文元亨。如今他才如梦初醒，自己与剑圣何止是一步之遥。",
	["tid#herolegend6_117"]="接下来的日子里，江湖上那个“一步剑圣”突然消声觅迹了一般，心灰意冷的谢小风一度放弃了再次拿起剑的念头，他自觉自己恐怕一辈子也难以匹及中天君的高度。百无聊赖之际，他接到一封来自老门主的家书，告诉他可以前往一处剑庐。",
	["tid#herolegend7_117"]="鸣泉之上有一处洞窟，谢小风不知道他的父亲谢天仪与那宇文元亨正是忘年之交，当年面对气势勃勃的宇文元亨与他在鸣泉谛天窟之内到处遍是二人曾经相斗之时留下的剑痕。谢小风自困于谛天窟内整整三年，从无数杂乱的剑痕中不停推演父亲与剑圣二人如何相斗，招招剑路也在他脑中重现，终有一日领悟到剑中真谛。",
	["tid#herounlockedsaying_204"]="你能否接下我这一剑？",
	["tid#herounlockedsaying_205"]="无名无剑，剑非剑，我亦非我。",
	["tid#herounlockedsaying_206"]="百兵之君，仁义之剑。",
	["tid#poetry_117"]="一剑惊天地\\n  青霜贯长空\\n  古来未有人\\n  能使万刃同",
