	["tid#HeroName_511"]="龙胆枪",
	["tid#SkillDes_51111"]="赵云召唤枪影笼罩敌人，对其造成共计5次攻击，前四次攻击会造成140%攻击力的伤害，最后一击会额外附加敌人最大生命值8%的伤害,眩晕敌人3秒，且自身免疫控制3秒",
	["tid#SkillDes_51112"]="等级2：赵云每拥有10点闪避值，便会使该技能造成的伤害提升2%，最多提升20%",
	["tid#SkillDes_51113"]="等级3：前四次攻击伤害提升至160%攻击力",
	["tid#SkillDes_51114"]="等级4：赵云每拥有10点闪避值，便会使该技能造成的伤害提升2%，最多提升30%，最后一击会额外附加敌人最大生命值10%的伤害",
	["tid#SkillDes_51121"]="战斗开始时，赵云自身的闪避值会提升100点，但战斗时间每过去5秒，该加成效果会减少20%",
	["tid#SkillDes_51122"]="等级2：当赵云的闪避值大于200点时，每额外获得10点闪避值，便会使自身受到的伤害减少1%，最多减少30%",
	["tid#SkillDes_51123"]="等级3：当赵云的闪避值大于200点时，每额外获得10点闪避值，便会使自身受到的伤害减少1%，最多减少40%",
	["tid#SkillDes_51124"]="等级4：战斗开始时，赵云自身的闪避值会提升150点",
	["tid#SkillDes_51131"]="战斗开始时，赵云会立刻瞬移到后排敌人身后，对其造成300%攻击力的伤害，并使其眩晕3秒",
	["tid#SkillDes_51132"]="等级2：释放该技能后，赵云会获得40%的攻速提升，持续10秒",
	["tid#SkillDes_51133"]="等级3：伤害提升至320%攻击力",
	["tid#SkillDes_51134"]="等级4：当赵云击杀敌人时，立刻瞬移至存活敌人身后，对其造成320%攻击力的伤害，并使其眩晕3秒",
	["tid#SkillDes_51141"]="战斗中，赵云每成功闪避一次敌人的攻击，便对当前目标造成一次300%攻击力的伤害，该效果每秒仅可触发一次",
	["tid#SkillDes_51142"]="等级2：每次闪避成功时，赵云还会获得80点内力",
	["tid#SkillDes_51143"]="等级3：对当前目标造成伤害提升至350%攻击力",
	["tid#SkillDes_51144"]="等级4：闪避成功获得的内力提高至100点",
