	["tid#HeroTypeDes_708"]="职业：战士  装备：铠甲",
	["tid#SkillDes_70811"]="吕布立即恢复自身30%最大生命值的血量，并进入“天下无双”状态，状态持续期间，吕布会保留1点血量且不会死亡，并使自身增加50%攻击速度和攻击力，释放该技能不会消耗内力，但会在“天下无双”状态持续期间每秒消耗150点内力，当内力消耗完时，状态结束，“天下无双”状态期间，吕布无法恢复内力",
	["tid#SkillDes_70812"]="等级2:攻击力效果提升至80%",
	["tid#SkillDes_70813"]="等级3:每秒消耗内力减少至120点",
	["tid#SkillDes_70814"]="等级4:每秒消耗内力减少至100点，“天下无双”状态期间免疫控制",
	["tid#SkillDes_70821"]="吕布每累计受到超过自身最大生命值10%的伤害，便会为自身恢复50点内力，每场战斗仅限一次。当吕布受到致命伤害时，会使自身无敌2秒，并立即恢复300点内力，每场战斗仅限一次。",
	["tid#SkillDes_70822"]="等级2:受到濒死伤害恢复的内力提升至400点",
	["tid#SkillDes_70823"]="等级3:当吕布受到致命伤害时，会立即震慑所有敌人眩晕2秒，吕布所有攻击无视对方50%防御，持续8秒，每场战斗仅限一次",
	["tid#SkillDes_70824"]="等级4:受到濒死伤害恢复的内力提升至500点",
	["tid#SkillDes_70831"]="战斗开始时，吕布会立刻释放战神之威，威吓与自己位置相对的敌方侠客，立即对其造成300%攻击力的伤害，且在本场战斗中，只要吕布在场，该侠客造成的伤害就会减少20%，吕布自身伤害增加20%（效果不会被净化）",
	["tid#SkillDes_70832"]="等级2:伤害提升至320%攻击力",
	["tid#SkillDes_70833"]="等级3:敌方侠客伤害减少效果提升至30%，吕布自身伤害增加30%",
	["tid#SkillDes_70834"]="等级4:吕布离场后，伤害减少效果仍会存留8秒",
	["tid#SkillDes_70841"]="吕布挥动方天画戟，对身前范围内的敌人造成150%攻击力的伤害，该技能造成伤害的30%会转化为自身恢复效果",
	["tid#SkillDes_70842"]="等级2:伤害提升至180%攻击力",
	["tid#SkillDes_70843"]="等级3:该技能造成伤害的40%会转化为自身恢复效果",
	["tid#SkillDes_70844"]="等级4:当处于“天下无双”状态时，此“飞将翼展”技能会变为普攻",
	["tid#SkillDes_70851"]="飞将军普攻",
	["tid#EquipAffixDes1208"]="核心：飞将军装备时，忽视敌方12%的外伤减免",
