	["tid#SkillName_70851"]="飞将军普攻",
	["tid#Herolife_511"]="先后在袁绍，公孙瓒帐下为将。但因未遇明主，遂投奔刘备，备受重用。为报主恩，长坂坡在曹操百万营中杀得七进七出，救得幼主，枪刺剑砍，杀死曹营名将五十余员，使曹军闻风丧胆。一生对阵，未尝败绩，称“长胜将军”，为刘备军五虎上将之一。",
	["tid#Herolegend1_511"]="公孙瓒大败于袁绍，只身逃离。文丑紧追不舍，公孙瓒不慎坠于马下，性命将要不保。忽见草坡左侧转出一个少年将军，飞马挺枪，直取文丑。公孙瓒爬上坡去看，那少年生 得身长八尺，浓眉大眼，阔面重颐，威风凛凛；与文丑大战五六十合，胜负未分。公孙瓒部下前来援救，文丑拨回马去了。公孙瓒忙下山坡，问那少年姓名。 那少年答曰：“某乃常山真定人也，姓赵，名云，字子龙，本袁绍辖下之人。因见绍无忠君救民之心，故特弃彼而投麾下；不期于此处相见。”公孙瓒大喜，遂与赵云一同归营。",
	["tid#Herolegend2_511"]="赵云在公孙瓒帐下，此时公孙瓒正与袁绍相争。董卓为了笼络人心，遣人去和解，以此拉拢二人。公孙瓒接受董卓册封，与袁绍和解。这让赵云十分失望，此时刘备正在公孙瓒处，赵云与刘备交好。刘备离开时，二人执手垂泪，不忍相离。赵云叹曰：“某曩日误认公孙瓒为英 雄；今观所为，亦袁绍等辈耳！”玄德曰：“公且屈身事之，相见有日。”洒泪而别。",
	["tid#Herolegend3_511"]="赵云与刘备分别之后，继续跟随公孙瓒，然而公孙瓒不听建议，兵败自焚。袁绍数次招揽赵云，赵云都没有答应。赵云知道刘备忠义，准备去徐州投奔刘备，不料徐州失守，连关羽都留在曹操处。赵云见刘备已经去了袁绍处，担心自己投刘备会被袁绍猜忌，只能四处飘零。路过卧牛山，赵云遇到裴元绍下山抢马，便杀了裴元绍，借卧牛山安身。关羽过五关斩六将与张飞刘备会和，刚好路过附近，赵云终于再见刘备，对刘备说：“云奔走四方，择主而事，未有如使君者。今得相随，大称平生。虽肝脑涂地，无恨矣。”从此赵云便在刘备帐下，跟随刘备四处征战。",
	["tid#Herolegend4_511"]="曹操攻荆州，刘表次子刘琮先举州投降，驻守樊城的刘备无力抵抗曹操，率军而走。襄阳十余万百姓自发跟随刘备，刘备为照顾平民，只能缓缓行军，很快被曹操追上。赵云负责保护刘备家人，无奈与曹军厮杀之中走散。于是赵云领三四十骑回身救援，救出甘夫人与糜竺，又独自回去寻糜夫人与小主人去。于乱军之中一枪刺死夏侯恩，得曹操佩剑“青釭”。赵云插剑提枪，杀入重围，孤身一人在乱军中冲杀，终于寻到糜夫人。糜夫人把阿斗托付给赵云，投井而死。赵云将阿斗抱在怀中，单骑冲杀。",
	["tid#Herolegend5_511"]="赵云怀抱阿斗，被曹军围追堵截，赵云一枪刺死晏明，杀散众军，冲开一条路。又遇张合，赵云不敢恋战，夺路而走。马延、张顗、焦触、 张南四将围堵赵云力战四将，杀出重围。又连斩锺缙、锺绅两员大将，终于逃脱。赵玉把阿斗从怀中托给刘备，刘备将亲子扔到地上，说“为汝这孺子，几损我一员大将！”赵云忙抱起阿斗，感激涕零。",
	["tid#herolegend6_511"]="孙权想进攻荆州，就派周善去接回自己的妹妹孙夫人，并拐走阿斗，跟刘备换取荆州。周善带着孙夫人和阿斗，正欲启航，赵云及时赶到。周善叱令军士开船。赵云沿江追赶，追了十余里，看到一只渔船。赵云跳上渔船，向大船追赶。周善让军士放箭，被赵云挡下。赵云手持青釭剑，跳上大船。赵云入舱中，向孙夫人讨回阿斗，孙夫人不从。赵云只得夺过阿斗，与船上吴军对峙。幸得张飞赶来营救，赵云夺回少主！",
	["tid#herolegend7_511"]="诸葛亮北伐，派赵云进兵。西凉大将韩德领着四子来战。韩德长子韩瑛迎战赵云，被赵云一枪刺死于马下。次子韩瑶、三子韩琼、四子韩琪三人一同围住赵云。赵云在中央独战三将，将韩琪刺落落马。韩琼按取弓箭射赵云，皆被赵云用枪拨落。韩琼反被赵云一箭射中面门，落马而死。韩瑶纵马举宝刀便砍赵云，云弃枪于地，闪过宝刀，生擒韩瑶。赵云连斩四将，吓得敌军阵阵倒退。赵云匹马单枪，往来冲突， 如入无人之境。之后赵云再斩韩德，杀退夏侯楙。一连斩杀五位敌方大将，让人感叹“赵云虽年老，英雄尚在。”",
	["tid#herounlockedsaying_207"]="大丈夫只患功名不立，何患无妻？",
	["tid#herounlockedsaying_208"]="大将军，岂可有勇无谋。勇者之事甚于生死。",
	["tid#herounlockedsaying_209"]="龙游沙场，胆震群雄！一枪在手，贼军何足道哉！",
	["tid#poetry_511"]="血染征透甲红\\n  当日谁敢与争风\\n  古来冲阵扶危主\\n  只有常山赵子龙",
	["tid#Herolife_708"]="五原九原人，初从定州刺史丁原，后因贪图赤兔马杀丁原归董卓，为卓义子，官拜“温侯”，世人讥笑为“三姓家奴”。后中司徒王允、貂蝉连环计，合谋杀董卓。布善弓马，武艺高强，有“飞将”之称。是三国第一条好汉。所谓“人中吕布，马中赤兔”。曹操破徐州，在白门楼杀之。",
	["tid#Herolegend1_708"]="吕布本是丁原义子。时董卓欲行废立之事，遭丁原怒斥。董卓本想斩杀丁原，但慑于吕布英武，不能发作。后丁原率军攻打董卓，吕布武艺高强，杀的董卓军大败，董卓以吕布为大患。其麾下虎贲中郎将李肃与吕布是同乡，他建议董卓用宝马赤兔和金银财宝策反吕布，董卓应允。李肃带着宝马财宝到吕布处游说，吕布果然答应叛节。当夜二更时分，吕布冲入丁原帐内，杀丁原，归顺董卓，再拜董卓为义父。",
	["tid#Herolegend2_708"]="十八路诸侯讨伐董卓，吕布奉命驻守虎牢关。斩杀河北名将方悦，大败王匡。后吕布大战八路诸侯，上党太守张杨部将穆顺，出马挺枪迎战吕布，被一戟刺于马下。北海太守孔融部将武安国，使铁锤飞马而出。吕布挥戟拍马来迎。战到十余合，一戟砍断安国手腕。八路军兵齐出，救了武安国。众诸侯回寨商议。正议间，吕布又来挑衅邀战。公孙瓒挥槊亲战吕布。战不数合，败走。吕布纵赤兔马追赶。眼看就要追上，张飞来救，二人酣战，连斗五十余合，不分胜负。关羽见状，拍马上前，夹攻吕布。激战三十合仍不分胜负。刘备于是也来助战。三人围住吕布，转灯般厮杀。吕布见久战不利，荡开阵角，倒拖画戟，飞马便回。此战吕布骁勇之资，诸侯畏惧。",
	["tid#Herolegend3_708"]="司徒王允有一养女貂蝉。王允请吕布来家中赴宴，先将貂蝉许诺于吕布。席间命貂蝉出堂敬酒。吕布一见貂蝉，神魂颠倒。王允当下同意将貂蝉许配给吕布，并约定日期送吕府完婚。接着王允又宴请董卓，命貂蝉率众舞女献舞，并将貂蝉赠与董卓。待吕布上门，王允称董卓将貂蝉带走，以挑拨二人关系。吕布之后屡屡骚扰貂蝉，引得董卓不快，但又不舍得将貂蝉送给吕布，二人矛盾渐生。吕布对董卓渐生怨恨，在王允的煽动下，决定诛杀董卓。是日，董卓上朝，入北掖门，王允带甲士围攻董卓。董卓向吕布呼救，吕布厉声大喝：“有诏讨贼！”一戟刺杀董卓。",
	["tid#Herolegend4_708"]="诛杀董卓后，其心腹李催，郭汜出逃，并发书信请求赦免，王允拒绝。于是催，郭汜采用贾诩之谋，带领原董卓部曲将攻向长安。吕布前往迎击，被击败。李催，郭汜攻入长安，吕布劝王允逃走，王允不从，吕布遂逃出长安投奔袁术。正值天下大乱，吕布也攻州伐县，自立为一方诸侯。",
	["tid#Herolegend5_708"]="曹操率军攻击濮阳，与吕布交战，二军对阵。吕布率军大败曹军，击退曹军三四十里。黄昏时分，曹操领两万兵马偷袭吕布军军寨。吕布亲自领兵救援，又杀的曹操大败，幸得典韦死战，夏侯惇援救才侥幸逃脱。吕布听从陈宫建议，派人假装内应去曹操军中报信，曹操信以为真，晚上径直领兵入城内。吕布突然带兵杀出，曹操措手不及，落荒而逃。混战中曹操险些被吕布所擒。",
	["tid#herolegend6_708"]="后吕布夺取刘备的徐州，让刘备居于小沛。袁术欲攻打刘备，派大将纪灵攻小沛。刘备兵少，无奈向吕布请援。吕布遂宴请纪灵和刘备宴饮。希望二人能够看在吕布的面子上停战。吕布让左右取戟来，提画戟在手，说：“我劝你两家不要厮杀， 尽在天命。”令左右接过画戟，去辕门外远远插定。乃回顾纪灵、刘备，说：“辕门离中军一百五十步。吾若一箭射中戟小枝，你两家罢兵；如射不中，你各自回营， 安排厮杀。有不从吾言者，拚力拒之。”众人不信吕布能射中，一致答应。吕布张弓搭箭，正中画戟小枝，众人无不叹服。纪灵见吕布神武，只得罢兵。",
	["tid#herolegend7_708"]="后吕布屡败，困守下邳。坚守数月，最终因苛待军事，被属下擒住，向曹操请降。被缢死于白门楼。",
	["tid#herounlockedsaying_210"]="哈哈！方天画戟，横扫刹车，无双立万世！",
	["tid#herounlockedsaying_211"]="天予不取反受其咎，时至不行反受其殃！",
	["tid#herounlockedsaying_212"]="尽管英雄人前多少风光，也难过美人关……",
	["tid#poetry_708"]="倒拖画杆方天戟\\n  乱散销金五彩幡\\n  顿断线涤走赤兔\\n  翻身飞上虎牢关",
