	["tid#SkillName_71051"]="羽人非獍普攻",
	["tid#SkillDes_71011"]="羽人非獍釋放絕技飛到空中，隨後攻擊所有敵人6次，前5次每次造成120%攻擊力的傷害，最後一次會造成200%攻擊力的傷害，技能釋放期間自身無敵",
	["tid#SkillDes_71012"]="等級2：最後一擊還會使命中的敵人眩暈2秒",
	["tid#SkillDes_71013"]="等級3：前五次傷害提升至130%攻擊力，最後一擊傷害提升至220%攻擊力",
	["tid#SkillDes_71014"]="等級4：使用該技能成功擊殺敵人後，羽人非獍會額外恢復300點內力",
	["tid#SkillDes_71021"]="羽人非獍發出音刃攻擊血量百分比最低的敵人，對其造成240%攻擊力的傷害，該若該技能成功擊殺了敵人，則會額外釋放一次，且額外釋放時會攻擊所有敵人（霹雳效果：每上阵一个霹雳联动角色，該技能造成伤害提升10%）",
	["tid#SkillDes_71022"]="等級2：命中敵人的血量低于50%，造成伤害提升50% ",
	["tid#SkillDes_71023"]="等級3：傷害提升至260%攻擊力",
	["tid#SkillDes_71024"]="等級4：敵人血量低於50%時，該技能無法被閃避",
	["tid#SkillDes_71031"]="羽人非獍發出道音刃，攻擊扇形範圍內的所有敵人，對其造成220%攻擊力的傷害，若該技能暴擊，則本次造成傷害的30%會轉化為自身的恢復效果",
	["tid#SkillDes_71032"]="等級2：傷害提升至240%攻擊力",
	["tid#SkillDes_71033"]="等級3：該技能暴擊時，會使該技能的傷害提升50%",
	["tid#SkillDes_71034"]="等級4：傷害提升至260%攻擊力",
	["tid#SkillDes_71041"]="戰鬥開始時，羽人非獍會獲得2層“六翼”效果，每層六翼效果會使自身的暴擊率提升10%和暴擊效果提升10，之後戰鬥每過去10秒，便會增加一層“六翼”效果，“六翼”效果會一直持續到戰鬥結束，最多可疊加6層（霹雳效果：每多上阵一个霹雳联动角色，戰鬥開始會便會額外獲得一層“六翼”效果）",
	["tid#SkillDes_71042"]="等級2：“六翼”效果現在最多可疊加8層",
	["tid#SkillDes_71043"]="等級3：每層六翼效果還可使自身獲得5%攻速提升",
	["tid#SkillDes_71044"]="等級4：每層六翼效果還可使自身獲得10%攻速提升",
