	["tid#SkillName_21751"]="御竞堂普攻",
	["tid#SkillDes_21711"]="御竞堂向敌方区域踢出蹴鞠，蹴鞠落地后会爆炸，对大范围内的敌人造成300%攻击力的伤害和2秒眩晕效果",
	["tid#SkillDes_21712"]="等级2：命中敌人身上每有一层“破甲”状态，该技能造成的伤害就会提升10%",
	["tid#SkillDes_21713"]="等级3：伤害提升至350%攻击力",
	["tid#SkillDes_21714"]="等级4：被命中的敌人还会被施加一层“破甲”效果（破甲：防御力降低10%，持续8秒，最多可叠加5层）",
	["tid#SkillDes_21721"]="解锁该技能后，御竞堂的普攻会得到强化，每次攻击都会对敌方及其周围的敌人造成180%攻击力的范围伤害，但御竞堂释放普攻的频率会减半，战斗中，御竞堂每次获得攻击力提升时，便会将攻速提升数值的30%转换为攻击力提升",
	["tid#SkillDes_21722"]="等级2：攻击力提升至200%攻击力",
	["tid#SkillDes_21723"]="等级3：伤害提升至220%攻击力，被命中的敌人有50%概率被施加一层破甲状态（破甲：防御力降低10%，持续8秒，最多可叠加5层）",
	["tid#SkillDes_21724"]="等级4：攻速转换攻击的比例提升至40%",
	["tid#SkillDes_21731"]="战斗中，御竞堂每过15秒会获得一个护盾，当护盾存在时，若御竞堂受到了控制效果，则会免疫该控制并无敌1秒（技能正式上线前可能会有调整）",
	["tid#SkillDes_21732"]="等级2：护盾生成时间减少至12秒",
	["tid#SkillDes_21733"]="等级3：无敌时间提升至2秒",
	["tid#SkillDes_21734"]="等级4：现在受到任意伤害都会触发无敌效果",
	["tid#SkillDes_21741"]="御竞堂对敌方攻击力最高的侠客洒出小蹴鞠，小蹴鞠在落地后会爆炸并产生烟雾，对敌人造成200%攻击力的伤害和持续3秒的致盲效果，当敌人受到致盲效果时，减少50%命中",
	["tid#SkillDes_21742"]="等级2：被命中的敌人还会被施加2层“破甲”状态（破甲：防御力降低10%，持续8秒，最多可叠加5层）",
	["tid#SkillDes_21743"]="等级3：攻击力提升至220%攻击力，致盲时间提升至5秒",
	["tid#SkillDes_21744"]="等级4：敌人减命中效果提升到60%",
	["tid#SkillDes_21751"]="御竞堂普攻",
	["tid#HeroTypeDes_709"]="職業：術士  裝備：布甲",
	["tid#Heroclass_709"]="蟻天海殤君",
	["tid#HeroName_709"]="滅境",
	["tid#SkillDes_70911"]="海殤君釋放擎羊嘯天攻擊所有敵人，對5個敵方俠客分別造成300%攻擊力的傷害，若敵方俠客數量不足5人，則會隨機攻擊另外一個敵人",
	["tid#SkillDes_70912"]="等级2：傷害提升至320%攻擊力",
	["tid#SkillDes_70913"]="等级3：若連續命中了同一個敵人2次以上，則該敵人還會被眩暈2秒",
	["tid#SkillDes_70914"]="等级4：傷害提升至340%攻擊力",
	["tid#SkillDes_70921"]="海殤君召喚狂風攻擊敵人，對範圍內的敵人造成300%攻擊力的傷害，並使其攻速降低30%，持續5秒",
	["tid#SkillDes_70922"]="等级2：復活後5秒內，該技能的冷卻時間減少50%",
	["tid#SkillDes_70923"]="等级3：傷害提升至320%攻擊力",
	["tid#SkillDes_70924"]="等级4：當自身血量低於50%時，該技能造成傷害的30%會轉化為自身恢復效果",
	["tid#SkillDes_70931"]="戰鬥開始時，海殤君會召喚水流對自己位置相對的敵人造成260%攻擊力的傷害，並使其攻擊力降低20%，該效果會一直持續到戰鬥結束",
	["tid#SkillDes_70932"]="等级2：傷害提升至280%攻擊力",
	["tid#SkillDes_70933"]="等级3：敵人降低的攻擊力會轉化為自身攻擊力，但加成效果會在敵人死亡時消失（霹雳效果：队伍中的其他霹雳角色也会受到该技能效果的一半）",
	["tid#SkillDes_70934"]="等级4：敵人死亡後，加成效果仍然會繼續保持",
	["tid#SkillDes_70941"]="戰鬥中，當海殤君死亡時，會在10秒之後復活，並恢復60%最大生命值的血量，之後每次復活，恢復的血量都會減少減半，（最少恢復1%最大生命值的血量），死亡時或復活期間，我方隊友全部陣亡，則海殤君將無法復活（霹雳效果：每多上阵一个霹雳联动角色，复活时恢复的血量就提升10%）",
	["tid#SkillDes_70942"]="等级2：每次復活時，海殤君會免疫所有控制效果和傷害1秒",
	["tid#SkillDes_70943"]="等级3：首次復活時恢復的血量提升至70%",
	["tid#SkillDes_70944"]="等级4：每次復活時，海殤君會免疫所有控制效果和傷害2秒",
