	["tid#ActiveItemName_5560"]="巅峰一级城池宝箱",
	["tid#ActiveItemName_5561"]="巅峰二级城池宝箱",
	["tid#ActiveItemName_5562"]="巅峰三级城池宝箱",
	["tid#ActiveItemDes_5560"]="在巅峰帮会战占领一座一级城池获得此宝箱，开启后可随机获得任意一个奖励",
	["tid#ActiveItemDes_5561"]="在巅峰帮会战占领一座二级城池获得此宝箱，开启后可随机获得任意一个奖励",
	["tid#ActiveItemDes_5562"]="在巅峰帮会战占领一座三级城池获得此宝箱，开启后可随机获得任意一个奖励",
	["tid#EquipAffixDes2209"]="核心：御竞堂装备时，外伤加深增加8%",
	["tid#Herolife_217"]="长安的坊间皆知一个少年蹴鞠手的名头，那便是御竞堂的罗纳多，他分明是一个胡人，却走动在贵胄之间颇有些声望。不仅如此，罗纳多劲射“风流眼”的腿法，在江湖之间也极富声名，相传他的腿法变幻莫测，迅如疾风，世间罕见。",
	["tid#Herolegend1_217"]="在某一日的清晨，年幼的罗纳多趁着一阵叮叮当当的驼铃声，混入了一直向着东方前进的商队，这个孤苦但机敏的孩子想要离开这片酷热的沙漠到传说中的长安去。他说长安是河里流着蜜的地方，想必到了那个地方就不会饿着肚子了。",
	["tid#Herolegend2_217"]="刚进长安城的罗纳多原本跟其他那些没有父母的孩子一样，混在乞讨的队伍里，虽然只能吃一些残羹冷炙，但是相比以前在风沙中的折磨中相比，日子倒是好过了很多。不在饿着肚子的罗纳多也开始与坊间街头的孩子们一起玩闹，蹴鞠算是他最喜欢的游戏了。",
	["tid#Herolegend3_217"]="没过多少日子，坊间的孩子们便都不是罗纳多的对手了，也许是时来运转，罗纳多在街头玩闹蹴鞠时，得到一个路过官员的青睐，这官员想到家中幼子也如同这孩子一般年纪，也是近来沉迷蹴鞠的不得了，将这小乞丐带回去作为玩伴也倒无不可。",
	["tid#Herolegend4_217"]="时过境迁，当初的小乞丐变成了长安中的红人，多少王孙看客都想看看一个少年英才蹴鞠的本事到底有多强。长安城的这些个王孙贵族闲来无事，就喜欢蹴鞠马球之类的，还组建了不少的堂口前来对抗，而罗纳多正是受朝中的一位权臣相托，成了权臣手下御竞堂的堂主。",
	["tid#Herolegend5_217"]="御竞堂在罗纳多的带领下，可谓在长安出尽了风头，每当御竞堂与其他的堂口比试，都能落得王孙贵族们无数的彩头，每当罗纳多将蹴鞠穿过场地中央的风流眼，都意味着千金掷地，红绡无数。因此也不知道多少达官显贵都想过将罗纳多拉入自己的麾下，不过碍于罗纳多背后的金主的地位，无人敢跨越雷池。",
	["tid#herolegend6_217"]="罗纳多一直都清楚，自己对于脚下蹴鞠的掌控，早就超出了一般意义的踢球游戏，他不甘心永远呆在蹴鞠场的小天地间，不间断的听着各式各样的加油和呐喊，在他看来，自己不过也是取悦王孙贵族的工具罢了，他渴望获得更多的尊重和关注。",
	["tid#herolegend7_217"]="有一日罗纳多走在坊间之时，在人群的簇拥之中敏锐察觉到浑水摸鱼的贼人，罗纳多见状一个空翻越过人群，接过他人手中的蹴鞠之后，大力劲射到贼人身上，罗纳多如此势大力沉的脚法，一球便将贼人击倒在地，猛然间罗纳多似乎找到自己的新方向，他决定摆脱长安的舒适圈向更大的中原进发看看了。",
	["tid#herounlockedsaying_213"]="总与个王孙贵族一起玩，甚是无聊！",
	["tid#herounlockedsaying_214"]="你可别小看看了这小小的蹴鞠。",
	["tid#herounlockedsaying_215"]="看我这就先拔个头筹！~",
	["tid#poetry_217"]="长安好少年\\n  豪气冲云天\\n  志在风流眼\\n  定脚山河颠",
