	["tid#SkillName_71451"]="白玉堂普攻",
	["tid#SkillDes_71311"]="展昭进入“剑花”状态8秒，期间会免疫所有外功伤害，且会将受到伤害值的60%返还给攻击者",
	["tid#SkillDes_71312"]="等级2：持续期间，展昭每秒会恢复10%最大生命值的血量",
	["tid#SkillDes_71313"]="等级3：反击伤害提升至80%",
	["tid#SkillDes_71314"]="等级4：展昭现在还会免疫受到内功伤害的50%",
	["tid#SkillDes_71321"]="战斗开始时，展昭会“护卫”我方后排攻击力最高的侠客，使其在之后的10秒内，攻击力提升20%，且受到的所有伤害都由展昭承担，护卫期间，展昭受到的伤害会减少30%",
	["tid#SkillDes_71322"]="等级2：护卫期间，展昭每秒会恢复最大生命值的10%",
	["tid#SkillDes_71323"]="等级3：持续时间提升至12秒",
	["tid#SkillDes_71324"]="等级4：护卫期间，护卫目标会获得展昭防御属性的50%，展昭会获得护卫目标攻击属性的50%",
	["tid#SkillDes_71331"]="展昭挥舞巨阙剑重击身前的敌人，对范围内的敌人造成240%攻击力的伤害和持续2秒的眩晕效果",
	["tid#SkillDes_71332"]="等级2：该技能成功命中敌人后，会为自身施加一个持续8秒的护盾，抵挡300%攻击力的伤害",
	["tid#SkillDes_71333"]="等级3：眩晕时间提升至3秒",
	["tid#SkillDes_71334"]="等级4：附加的护盾值提升至400%攻击力",
	["tid#SkillDes_71341"]="战斗中，若战场上存在除展昭以外的友方侠客，则展昭会获得40%的伤害减免",
	["tid#SkillDes_71342"]="等级2：若“护卫”目标存活，则展昭还会额外获得10%的伤害减免",
	["tid#SkillDes_71343"]="等级3：战斗中，若战场上存在除展昭以外的友方侠客，则展昭获得的伤害减免效果提升至50%",
	["tid#SkillDes_71344"]="等级4：若己方场上只剩余展昭1人，则展昭会获得90%的伤害减免和100%的攻速和攻击力加成，持续5秒",
	["tid#SkillDes_71351"]="展昭普攻",
	["tid#SkillDes_71411"]="白玉堂对当前敌人造成350%攻击力的伤害，释放时若敌人当前血量低于50%，则本次伤害必定暴击",
	["tid#SkillDes_71412"]="等级2：使用该技能击杀敌人后，还会额外对所有敌人造成一次伤害，伤害值相当于技能伤害的50%，且一次技能中只会触发一次",
	["tid#SkillDes_71413"]="等级3：释放时若自身处于“迷踪”状态，则该技能会无视敌方50%防御力",
	["tid#SkillDes_71414"]="等级4：伤害提升至400%攻击力",
	["tid#SkillDes_71421"]="战斗开始时，白玉堂会将对位敌人禁锢，随后瞬移至其背后，对其造成300%攻击力的外功伤害，并使其眩晕2秒，之后会使其攻击力降低30%，自身攻击力增加20%,持续8秒",
	["tid#SkillDes_71422"]="等级2：白玉堂击杀敌人后，会立即释放一次该技能",
	["tid#SkillDes_71423"]="等级3：伤害提升至320%攻击力",
	["tid#SkillDes_71424"]="等级4：自身攻击力提升效果增加至30%",
	["tid#SkillDes_71431"]="战斗中，白玉堂会一直处于“迷踪”状态，期间无法被选为攻击和技能目标，造成的伤害增加20%，当白玉堂击杀任意一名敌人后，会退出“迷踪”状态6秒，之后会重新回到“迷踪”状态，等我方侠客只剩白玉堂一人时，白玉堂会退出“迷踪”状态。",
	["tid#SkillDes_71432"]="等级2：处于迷踪状态时，白玉堂的攻速会提升20%",
	["tid#SkillDes_71433"]="等级3：击杀敌人后现身的时间缩短至5秒",
	["tid#SkillDes_71434"]="等级4：造成的伤害提升30%，攻速提升至30%",
	["tid#SkillDes_71441"]="白玉堂迅速攻击当前敌人三次，前两次造成100%攻击力的外功伤害，最后一段会造成200%攻击力的外功伤害且必定暴击",
	["tid#SkillDes_71442"]="等级2：最后一击还会附加敌人最大生命值5%的伤害，附加伤害最多不超过白玉堂攻击力的500%",
	["tid#SkillDes_71443"]="等级3：最后一击伤害提升至240%攻击力",
	["tid#SkillDes_71444"]="等级4：前两击伤害提升至120%攻击力",
	["tid#SkillDes_71451"]="白玉堂普攻",
	["tid#herounlockedsaying_216"]="展某一向只识公理，不识时务。",
	["tid#herounlockedsaying_217"]="展某顶天立地，公私分明。",
	["tid#herounlockedsaying_218"]="我就这个脾气，越不让我管的事，我越要管。",
	["tid#herounlockedsaying_219"]="谁说老鼠怕猫，我这锦毛鼠就偏偏要逗逗那蠢猫！~",
	["tid#herounlockedsaying_220"]="若在江湖之上，你还得尊称我一声五爷才是。~",
	["tid#herounlockedsaying_221"]="我是男是女，嘻嘻，你说是男便是男，你说是女便是女。",
