	["tid#SkillName_61251"]="铁阎罗普攻",
	["tid#SkillDes_61211"]="锻瑛谷消耗所有内力，立即恢复最大生命值30%的血量并使自身进入“阎魔”状态6秒，阎魔状态持续期间，锻瑛谷每秒会对自身周围的敌人造成50%攻击力的伤害且攻击力会提升50%（技能调整中）",
	["tid#SkillDes_61212"]="等级2：持续时间提升至8秒",
	["tid#SkillDes_61213"]="等级3：伤害提升至60%攻击力",
	["tid#SkillDes_61214"]="等级4：若阎魔状态持续时间超过了4秒，则之后造成的伤害会无视敌人50%的防御",
	["tid#SkillDes_61221"]="锻瑛谷攻击一名随机敌方角色，对其造成120%攻击力的伤害并为其添加“灭魂”标记，灭魂标记会存在6秒，存在期间每秒会造成100%攻击力的伤害，且锻瑛谷会恢复灭魂标记造成伤害30%的生命值（技能调整中）",
	["tid#SkillDes_61222"]="等级2：当自身进入阎魔状态时，每秒还会对被施加了灭魂标记的敌人造成50%的伤害",
	["tid#SkillDes_61223"]="等级3：该技能现在会优先选择敌方后排角色",
	["tid#SkillDes_61224"]="等级4：标记持续时间提升至10秒",
	["tid#SkillDes_61231"]="战斗开始时，锻瑛谷会获得一个“熔金盾”，熔金盾存在时，锻瑛谷受到的伤害会减少50%，且每次受到伤害后都会恢复自身攻击力10%的血量，熔金盾会在受到10次伤害后消失（技能调整中）",
	["tid#SkillDes_61232"]="等级2：每次释放必杀技后，锻瑛谷都会额外获得一个熔金盾",
	["tid#SkillDes_61233"]="等级3：熔金盾现在可以抵挡15次伤害",
	["tid#SkillDes_61234"]="等级4：减少效果提升至60%",
	["tid#SkillDes_61241"]="锻瑛谷每受到一次恢复效果，便会获得一层“锻铁”效果，每层锻铁效果会使自身防御力提升2%，最多提升50%（技能调整中）",
	["tid#SkillDes_61242"]="等级2：提升的防御力上限增加至60%",
	["tid#SkillDes_61243"]="等级3：每层锻铁效果提供的防御力加成增加至3%",
	["tid#SkillDes_61244"]="等级4：当锻瑛谷受到致命伤害时，会消耗当前锻铁层数的一半，免疫本次伤害并无敌2秒，每消耗一层锻铁层数，便恢复最大生命值1%的血量，该技能有15秒技能冷却",
	["tid#SkillDes_61251"]="锻瑛谷普攻",
	["tid#Heroclass_713"]="展昭",
	["tid#Heroclass_714"]="白玉堂",
	["tid#HeroName_713"]="开封府",
	["tid#HeroName_714"]="陷空岛",
	["tid#HeroTypeDes_713"]="职业：护卫 装备：铠甲",
	["tid#HeroTypeDes_714"]="职业：刺客 装备：皮甲",
	["tid#Herolife_713"]="展昭，字熊飞，为人少年行侠，仗剑四方，好不平事，百里传名。时人因其久居江南，尊为“南侠”。后来为包龙图引荐面圣，入仕为官，得“御猫”之号。",
	["tid#Herolegend1_713"]="彼时当年，包拯不过是一个进京赶考的考生，因缘巧合借助金龙寺，却不想金龙寺早已被法明法本两个贼僧搞得乌烟瘴气。两贼僧见包拯主仆到来，见二人身上盘缠便起了贼心，意欲图谋不轨。正当主仆二人以为求生无门之时，突然有如神兵天降，此刻展昭赶到救下二人，之后展昭的传奇也随着与包拯的相遇而徐徐展开。",
	["tid#Herolegend2_713"]="再后来，包拯罢官回京，不巧路过土龙岗时，竟被山贼王朝马汉张龙赵虎四人掳掠上山，又是危难之际，却再遇展昭，没想到四人见到展昭立马毕恭毕敬，称呼展恩公。从四贼口中得知，几人皆是为庞太师所祸，流落至此，之前种种多有误会。",
	["tid#Herolegend3_713"]="展昭来到陈州，听闻安乐侯庞昱抢掠民女，强征壮丁为其修建花园。展昭听闻之后气破英雄胆，于是直奔旁昱花园。恰巧听闻歹人为谄媚庞昱，为庞昱配药酒以对女子不轨。因此展昭乘着歹人外出之时，调换屋外药酒放入屋内，此举不但为妇人金玉仙解一时之围，更是惩治了歹人，令其翻然悔悟，早早远离是非之地。",
	["tid#Herolegend4_713"]="再说庞昱因为将赈济中饱私囊，所以十分畏惧包拯前来查赈。南侠在花园软红堂外刚好听见，庞昱欲意派人行刺加害包公。展昭因此日夜兼程暗传字柬，将防刺客捉庞昱救妇人的消息告知包拯。到了三更，刺客见自己行踪暴露，正想翻越屋脊逃跑，怎料中了袖箭摔下砖牙。包拯方才知晓原来是南侠展义士暗中多次相助，心中不胜感羡之至。",
	["tid#Herolegend5_713"]="且说展昭在通真观后阁，闻悉小道士的师傅刑吉受雇于庞太师，正在设坛作法暗害包公，连忙收拾行头直奔庞太师府。但见太师府内，展昭暗暗抽剑步上高台，顷刻间就破解了邪术，老道栽下法台刚要逃跑，就被展昭手起刀落就地斩首。展昭提着老道的首级，将其甩入书房，吓得庞吉以为是开封府暗中派遣了能人高手，只得忿忿悔恨暗自收手。",
	["tid#herolegend6_713"]="包拯为了感谢展义士的救命之恩，将展昭引荐给了仁宗。展昭心中虽不愿意，但无奈包公已经遵旨，只好决定不辜负包公的好意。次日，展昭于耀武楼面见圣上，奉旨献艺三绝。一绝剑法精奥，天子大乐。二绝袖箭闪转腾挪间俱入靶心，天子甚觉罕然。三绝纵跃法飞檐走壁，只因圣上金口说出“分明是朕的御猫一般”，南侠因此获得赐号“御猫”，并受封御前四品带刀护卫。",
	["tid#herolegend7_713"]="展昭为了追回白玉堂盗走的府上三宝，不得不应下白玉堂的挑战，孤身前往陷空岛。怎料着了白玉堂的道，落入圈套被束于皮兜子中，被白员外庄丁押入了通天窟。展昭长叹误中奸谋时，遇到了同样被监禁的郭彰。展昭得知其女被抢掠献给白员外，便与白玉堂当堂对峙时将此事报出，不想阴差阳错会与白玉堂一齐，将强抢民女讨好白玉堂的小人捉住，让郭彰父女得以相聚，平安归乡。",
	["tid#Herolife_714"]="白玉堂金华人士，年纪轻轻习得一身高强绝世的武艺，勇敢聪慧，喜欢行侠仗义，平时为了行走江湖方便常常打扮成男子，但是又因华美不凡的长相显得气宇轩昂十分英气。凡她碰上的恃强凌弱的事儿，她一定是正邪分明一帮到底。",
	["tid#Herolegend1_714"]="锦毛鼠白玉堂，虽为女子之身，却时常一副武生打扮，英姿焕然。所到之处，必有行侠仗义之举。在开封府时，曾与展昭合力行侠仗义，有过一面之缘。开封有一武将作乱，在城中残害无辜妇孺，千钧一发之际，白玉堂与展昭不谋而合，同时出手，救下一位女子和她怀中的婴儿。虽无更多交流，但那时他们之间，是有些惺惺相惜的。",
	["tid#Herolegend2_714"]="白玉堂有四个兄弟，江湖诨号钻天鼠、彻地鼠、穿山鼠、翻江鼠，五人合称“五鼠”，快意恩仇，名震江湖。而同样声名显赫的展昭却被封为四品带刀侍卫，赐号“御猫”。因绰号相克的关系，江湖中众说纷纭，多是在说“五鼠”逊“御猫”一筹。白玉堂一怒之下，上京找展昭挑战，其他四个兄弟也各显神通，设法与展昭一较高下。一场“五鼠闹东京”的大戏，便就此拉开帷幕。",
	["tid#Herolegend3_714"]="虽因负气与展昭较量，但白玉堂并未停止行侠仗义，而是以更多义举来维护“五鼠”的名声。白玉堂身怀绝技，即使是暗中出入皇宫，也如探囊取物般容易。一日她在宫中无意中撞见，忠良的老太监陈琳险些被奸佞郭安暗害，一向随性的白玉堂不顾身处宫墙之内，怒斩郭安，而后扬长而去。为宫中除了一个祸害，也留下了一桩“疑案”。",
	["tid#Herolegend4_714"]="郭安之案悬于众人心中许久，直到有一日，圣上进入了忠烈祠。忠烈祠的墙上有一首题诗：“忠烈保君王，哀哉杖下亡。芳名垂不朽，博得一炉香。”圣上问及诗的来历却无人知晓，而题诗之人，正是白玉堂。此事连同郭安之案一起被交给开封府，经包拯审查，还原出真相。得知白玉堂是在惩奸除恶，圣上便不再追究她擅闯宫墙之过，还称赞其“是位侠士”。正是因为这句夸赞，白玉堂“除贼题诗”的事迹，也在世间传开了。",
	["tid#Herolegend5_714"]="虽然五鼠的名声越来越响，但白玉堂心中，始终期待能与展昭正面一战。为了引出展昭，她在开封府留书一封，声称要盗取包拯的三样宝物：阴阳镜、古今盆、游仙枕。当晚，白玉堂先是投石问路，点燃西耳房窗纸调离众人，而后以房上的皮人吸引注意力，金蝉脱壳，于众目之下取走宝物。如她所料，展昭果然从开封府离开，追查自己的踪迹，而他们之间的较量，也真正开始了。",
	["tid#herolegend6_714"]="为了与“御猫”一较高下，以白玉堂为首的五鼠各展所能，开始了斗智斗勇的大战。白玉堂曾因通晓八卦阵法而技胜一筹，将展昭困于通天窟中；却也曾兵刃被展昭之湛卢剑所伤，因而惜败一招。双方难分胜负，却在较量之中，不自觉显现了平时未示于人的武艺与计谋。包拯惜才，最终劝服五鼠归顺开封，一同造福百姓。“猫鼠”之间也因此息战，化干戈为玉帛。",
	["tid#herolegend7_714"]="不久后，襄阳王笼络大批江湖人士，意图谋反，而谋反的名单，就藏于机关重重的冲霄楼中。此时白玉堂已是带刀侍卫，为了取得罪证，她暗入冲霄楼，在那常人有去无回的险地，安然无恙往返了两次。但第三次查探时，她却莫名失去了踪迹。有人说她陷于冲霄楼的铜网之中，也有人说她功成身退，悄然归隐江湖。没有人知道真正的答案，但这并不影响，锦毛鼠的传说，始终流传于江湖之中。",
	["tid#itemName2713"]="开封府结缘碎片",
	["tid#itemName2714"]="陷空岛结缘碎片",
	["tid#itemDes2713"]="集齐60个可立即获得侠客开封府",
	["tid#itemDes2714"]="集齐60个可立即获得侠客陷空岛",
	["tid#HeroTypeDes_612"]="职业:术士   装备:布甲",
	["tid#Heroclass_612"]="李洋",
	["tid#HeroName_612"]="锻瑛谷",
	["tid#itemName2612"]="锻瑛谷结缘碎片",
	["tid#itemDes2612"]="集齐60个可立即获得侠客锻瑛谷",
	["tid#Herolife_612"]="江湖人称铁阎罗，是锻瑛谷的谷主，亦是一个狂热的铁匠，他精通天下矿石，铸造了无数的凶兵恶刃。之所以被称作铁阎罗，是因为在他治下的锻瑛谷就如同地狱刀山，凡是与他作对的人都将受到残忍的对待。",
	["tid#Herolegend1_612"]="锻瑛谷，原本是江湖岌岌无名的一个小门派，不过也踏踏实实世代以冶炼金铁维生，在江湖中一直有不错的口碑。而李洋作为家中长子，却因为弟弟过高的天赋备受冷落，青年时期的李洋为了重新获得父亲的认可，他比谁都渴望获得成功，他希望改变门派的现状，而不只是永远屈居人他人之下，做个江湖中的无名之辈。",
	["tid#Herolegend2_612"]="李洋从小便听闻干将铸剑，以生灵熔炼金铁的故事，于是开始研究此法，意图铸出名剑，以震动武林。然而，他秘密进行的试验却被父亲所得知，原本以为会被父亲训斥而感到害怕的李洋，却发现父亲在看到自己用生灵为引锻造的精铁后沉默不语，似乎是默许了自己的行为。也从那天开始，李洋开始重拾自己作为长子的地位，不断加深研究，铸造出数柄惊世骇俗的凶兵。",
	["tid#Herolegend3_612"]="由于常年吸入金铁之气而饱尝金毒，每每发作便如同万针钻心之苦。后来因缘巧合，他获得一种奇妙法门能够救他性命，他通过催动真气，将金铁之气全数逼入左手，原以为只要牺牲一只手便可以解除常年以来的金毒之苦，却没想到金铁之气淤积成为一只名副其实的铁手。如今这只形态可憎的铁手饱含剧毒，并且无坚不摧，亦可直接抓取熔炼的铁器，寻常人一见便可胆寒，也是他被称作“铁阎罗”的来由之一。",
	["tid#Herolegend4_612"]="天罗首席凌一的链刃”阿鼻报业“便是铁阎罗亲手打造而成，乃是铁阎罗最得意的作品，也是铸造过程最残忍的作品。彼时，因铸造凶兵而闻名于江湖的锻瑛谷，不断受到江湖正道的声讨，并且一次名剑山庄的名剑大会，便是以讨伐锻瑛谷为名而举办。李洋“铁阎罗”的声名虽然常为江湖人所忌惮，但终究是有些寡不敌众。于是乎，在李洋苦思一晚之后决定投靠凌峰楼。而那柄黑色链刃，便是李洋的投名状。",
	["tid#Herolegend5_612"]="在名列天罗众第四席位之后，他开始接触更多厉害的角色，直接进入他视线的便是第二席位的白夜叉，准确说是白夜叉手中的白龙双刃。铁阎罗熟悉所有金铁的味道，他能从白龙的刀刃之上嗅到不详的气息，习惯于生灵造物的他十分熟悉这样的味道，因此他十分渴求探索这柄“凶兵”的来历。他与白夜叉交涉，试图改造白夜叉的“白龙”却遭到拒绝，因此一直对白夜叉怀恨在心，并无时无刻觊觎着白夜叉的白龙。",
	["tid#herolegend6_612"]="当年锻瑛谷为名剑山庄围攻之事，一直在铁阎罗的心中挥之不去，他无法容忍对方竟然否定自己的铸剑之道，可是，名剑山庄毕竟是江湖中的大门派，他虽然位居天罗众第三席位，也不能轻易将这颗眼中钉从江湖上轻易抹除。后来，他看到一个机会，看到一个对名剑山庄怀有仇恨的人，于是他便将自己铸剑的法门传与他一二，而这个人正是名剑风来堂的堂主风云鹤。",
	["tid#herolegend7_612"]="在昆仑山上曾有“烛阴”凶剑问世，铁阎罗自然不能放过夺取“烛阴”的机会。然而为避免江湖为争夺此剑再起波澜，天山派的柳念奉九天之命前来封存，阻止了铁阎罗的计划，原本单独一战，铁阎罗未必会输在柳念之手，然而不知何来的蓬莱青年出手相助，与柳念一道将“烛阴”封与九尺寒冰之下，要想拿到此剑亦再无可能。铁阎罗心中满是不忿，也只好将此事暂时记恨在心中。",
	["tid#poetry_612"]="铁手断生灵\\n  诡计乱魂心\\n  生杀无情客\\n  血刃入寒侵",
	["tid#herounlockedsaying_222"]="钢铁雄心，亦是奔袭的洪流。",
	["tid#herounlockedsaying_223"]="金鸣铁器，冰冷肃杀会夺走所有生机。",
	["tid#herounlockedsaying_224"]="流光漫过刀剑吟，金铁修罗照寒心。",
	["tid#EquipAffixDes3310"]="核心：锻瑛谷装备时，内伤加深提高8%",
