	["tid#SkillName_51251"]="月寒宫普攻",
	["tid#SkillDes_51211"]="月寒宫会禁锢敌人，对其造成3段，每段160%攻击力的伤害，最后一击时月寒宫会冲至敌人身后，随后切换为近战攻击，当月寒宫处于近战状态时，暴击伤害提升40%，若月寒宫在近战状态下击杀了敌人，则会瞬移回战斗一开始所在的位置，回到远程状态",
	["tid#SkillDes_51212"]="等级2：释放时若自身有飞剑，则会消耗一把飞剑，使最后一次攻击的伤害提升50%并使敌人眩晕2秒",
	["tid#SkillDes_51213"]="等级3：每段伤害提升至200%攻击力",
	["tid#SkillDes_51214"]="等级4：暴击伤害提升效果提高至50%",
	["tid#SkillDes_51221"]="月寒宫召唤飞剑攻击水平方向上的敌人，对其造成120%攻击力的伤害，当月寒宫的伤害造成暴击时，会额外触发一次，但会有8秒钟的冷却时间",
	["tid#SkillDes_51222"]="等级2：释放时若自身有3柄以上的飞剑，则会使技能范围扩大",
	["tid#SkillDes_51223"]="等级3：伤害提升至150%攻击力",
	["tid#SkillDes_51224"]="等级4：冷却时间缩短至5秒",
	["tid#SkillDes_51231"]="月寒宫每次暴击后，都会生成一把飞剑，飞剑最多同时存在5把，每把飞剑会为月寒宫提供5%的攻速和攻击力加成",
	["tid#SkillDes_51232"]="等级2：每把飞剑提供的攻速加成提高至8%",
	["tid#SkillDes_51233"]="等级3：每把飞剑提供的攻击加成提高至8%",
	["tid#SkillDes_51234"]="等级4：战斗一开始时月寒宫便会携带2把飞剑",
	["tid#SkillDes_51241"]="当月寒宫受到致命伤害时，会消耗3把飞剑，使自身免疫本次的伤害并无敌1秒，并恢复20%最大血量，该技能有10秒冷却时间",
	["tid#SkillDes_51242"]="等级2：恢复的基础血量提升至30%最大生命值",
	["tid#SkillDes_51243"]="等级3：触发该技能后5秒内，月寒宫会的攻击力和攻速会提升30%",
	["tid#SkillDes_51244"]="等级4：触发该技能后5秒内，月寒宫会的攻击力和攻速会提升50%",
	["tid#SkillDes_51251"]="月寒宫普攻",
	["tid#EquipAffixDes2312"]="核心：月寒宫装备时，暴击率增加8%,外伤加深增加5%",
	["tid#HeroTypeDes_512"]="职业:刺客   装备:皮甲",
	["tid#Heroclass_512"]="姮娥",
	["tid#HeroName_512"]="月寒宫",
	["tid#herounlockedsaying_225"]="我若教人三更死，谁能留他到五更？",
	["tid#herounlockedsaying_226"]="这世间只有我才能打造出最锋利的兵器。",
	["tid#herounlockedsaying_227"]="没有沾染生灵的兵器都只是凡铁罢了。",
	["tid#herounlockedsaying_228"]="也许剑锋划破你的皮肤，流淌出的温热便能融化我的心。",
	["tid#herounlockedsaying_229"]="莫非孤独是我蒙受的诅咒？",
	["tid#herounlockedsaying_230"]="人间不值得……",
	["tid#itemName2512"]="月寒宫结缘碎片",
	["tid#itemDes2512"]="集齐60个可立即获得侠客月寒宫",
	["tid#Herolife_512"]="月寒宫中凝结的哀怨能够愁煞任何胆敢靠近的人，她将所有对世间的不公都汇集在自己的短剑之上，受她望舒寒剑所伤之人，总是会因为心脉凝结而惨绝于世，如此阴狠的剑法致使她能坐在天罗众的第九席位之上。",
	["tid#Herolegend1_512"]="也许真如天师门摘星阁的张天师为她定下的判诗所说，姮娥是一个无比孤独的人，她身上似乎蒙受了什么诅咒一般，亲近之人总是不得善终。自小跟随师父修炼寒蟾功的姮娥一直不受师姐们的待见，其所受的欺凌与打压，让姮娥有一段非常不愉快的回忆。然而师父却总是不管不问，任由那些师姐胡作非为。",
	["tid#Herolegend2_512"]="可是，寒蟾功是一种很奇怪的功法，姮娥越是孤独和绝望，功法进步反而越发神速，师姐们对她的孤立程度便越深。直到年迈的师父将她单独唤至门派密室，才让姮娥得知这门怪异武学的机密——师父早已修炼至寒蟾功的最高一层寒蟾脱壳，他竟然意图通过某种夺舍的法门来侵夺姮娥的身体。",
	["tid#Herolegend3_512"]="后来月寒宫有了新的掌门，只是这个掌门一如往常一样沉默寡言，往昔对她百般刁难的师姐们早已变作了毕恭毕敬，而她也似乎对曾经的经历既往不咎，将门派大大小小的事情都交予了她们，自己反而做了个甩手掌门。她很想逃离这个从小便囚禁自己的牢笼，于是她修书一封，擅自离开门派前往江湖去了。",
	["tid#Herolegend4_512"]="在外游历的姮娥，一旦离开了月寒宫，沾染到外界的人间气息，倒是很快变了一个人，此时的她仿佛一个不食人间烟火的仙子，可是她从小便跟随在师父身边浑然不明白尘世间的种种规则，一次拿人包子取了便走，被老板一把拦下。索性突然有人仗义相助，付了些银钱给老板，这才作罢。",
	["tid#Herolegend5_512"]="此人其实是这镇子附近打猎的猎户，这也是来镇子卖点野货顺便采买物资路过于此。姮娥这是第一次受人相助，原本漫无目的的她索性一直跟在猎户身边。起初，猎户也并不在意，只当是以为谁家的小姐不小心走丢，心智却也不好，所以照顾有加，礼节相待，得空便带到镇子上四处打听姑娘来处，但是总无消息。",
	["tid#herolegend6_512"]="原本的日子倒也平顺，猎户多番打听无望，见女子仍然跟随在自己身边，便想着长期照顾倒也无甚大碍，说不定女子对自己也有意……猎户每每想到此处，却也憨厚一笑，然后连忙摇头作罢，还是想着等来年多打些皮货，带姑娘到附近州府打听一下。",
	["tid#herolegend7_512"]="一天夜里，猎户警觉的从睡梦中惊醒，只听一阵铿锵之声，竟然发现女子正与不少衣袂飘飘的女子相斗，猎户立刻拿起弓箭准备帮忙，却被一道横飞的剑气所伤，瞬间觉得心脉冰寒，透彻骨髓。那仍未知晓姓名的女子见状，竟然发出一声悲鸣，立刻出手解决了其他女子……姮娥如何也想不到，自己明明辞了月寒宫宫主之位，那些师姐却仍对她耿耿于怀，非要追踪到此，于是她立刻返回月寒宫上上下下清洗了任何对她有过怠慢的人，成了月寒宫唯一的人，孤独的人。",
	["tid#money_guide_gain_170"]="在侠客身上使用之后，获得随机属性，同时在多个部位使用产生共鸣效果",
