	["seal_character_story_1"]="使用时必然获得一条随机属性，有几率获得两条\n两件获得共鸣增益：攻击+5%、防御+5%\n四件获得共鸣增益：当被攻击的目标血量高于70%时对其造成的伤害增加10%",
	["seal_character_story_2"]="使用时必然获得两条随机属性，有几率获得三条\n两件获得共鸣增益：攻击+8%、防御+8%\n四件获得共鸣增益：当被攻击的目标血量高于60%时对其造成的伤害增加15%",
