	["seal_character_story_10"]="使用时必然获得三条随机属性\n两件获得共鸣增益：攻击回内+5%\n四件获得共鸣增益：绝技技能伤害增加10%，如是绝技是范围技能则伤害增加15%",
	["seal_character_story_11"]="使用时必然获得三条随机属性\n两件获得共鸣增益：攻击+15%\n四件获得共鸣增益：每次攻击有50%几率给敌对目标增加减5%暴击的负面效果，持续3秒最多叠加6层",
	["seal_character_story_12"]="使用时必然获得三条随机属性\n两件获得共鸣增益：血量+10%、防御+10%\n四件获得共鸣增益：自身被攻击时有30%几率让攻击者停止回怒2秒",
