	["tid#HeroTypeDes_715"]="职业:神射   装备:皮甲",
	["tid#Heroclass_715"]="李白",
	["tid#HeroName_715"]="太学宫",
	["tid#itemName2715"]="太学宫结缘碎片",
	["tid#itemDes2715"]="集齐60个可立即获得侠客太学宫",
	["tid#Herolife_715"]="原本入朝为官，担任太白学宫的祭酒，却因为始终郁郁不得志，无法施展更大的抱负而悻悻离去，开始游侠于江湖。太白剑道出神入化，江湖人无不对其颇有敬仰之情，后来李白客居姑苏慕容，曾留下不少武学典籍。（纯属虚构）",
	["tid#Herolegend1_715"]="李白幼年时便发奋读书，不过也因家中特殊的缘故接触了不少游侠之人，因此当他十五岁诗赋颇有声名之时，也常与一些江湖剑客切磋剑术，蜀中不少江湖名门，彼时都会收到李白的谒诗，随后李白便会登门拜访，而这些名门也颇为大气，受诗之礼，也会教一招剑术给李白，因此李白本就精通百家剑术。（纯属虚构）",
	["tid#Herolegend2_715"]="二十郎当之际，李白“仗剑去国，辞亲远游”，虽是游侠，但李白希望普查世间，寻求大道以匡社稷。游历期间，李白结实不少益友，但是求仕却如蜀道之难，几番坎坷。不过随着阅历的增加，李白的剑术却更加精进，后世所传《太白要义》之秘籍，如今便有了雏形。（纯属虚构）",
	["tid#Herolegend3_715"]="尔后李白再次进京，为皇帝献赋，文章写尽中原之盛世，大道之愿景，终获赏识便入朝为官，供奉翰林并祭酒于太学宫。起初，李白结实不少长安名流，为人称为“太白星精”、“谪仙人”，一时间好不得意。只不过，事情并未像李白想的那样，自己不过是御用文人，空挂一个闲职，无处施展抱负，于是满心失落，日日纵饮，反而又被好友称为“饮中八仙”。（纯属虚构）",
	["tid#Herolegend4_715"]="人人皆知如今的姑苏慕容家有些落寞，却鲜有人知当年诗仙落于此地时的胜景，李太白所留剑谱在姑苏慕容重新现世之后，历历往事重提，又使人回想起当初李太白剑法的出神入化。李太白受皇帝赐金放还之后，只得再次游历天下，只不过此时他的声名早已传遍天下，他游历江南之时，客居慕容家，因喜此门第诗乐风采颇有魏晋之风，便成为姑苏慕容家的供奉长老。（纯属虚构）",
	["tid#Herolegend5_715"]="《太白要义》成书之后，姑苏慕容在江湖之上一度风头无两，经李太白所传，姑苏慕容以琴制剑，以乐动身的神奇武学的独树一帜，李太白也从一个独行的游侠变成了江湖上的一代宗师。只不过，江南之地虽是安乐之所，却也囿不住一个浪漫的灵魂，数年之后，李太白还是离开了这里继续游侠去了。（纯属虚构）",
	["tid#herolegend6_715"]="再后来，天下遭遇大乱，李太白成为一方势力的幕僚，重新燃起了他沉沉久矣的报国之心，只不过他的仕途永如蜀道一般，历尽艰险，终不得志，甚至最后受到牵累被判罪流放。好在李太白盛名，江湖上人人尽知，被困流放之地的李太白受江湖人士搭救，逃了出来，只不过这次，李太白彻地放下了心中的执念，不再过问庙堂之事。（纯属虚构）",
	["tid#herolegend7_715"]="只不过慕然回首，谪仙人也已近垂暮，白发苍苍矣，一次江上乘船饮酒，对月作诗，只消一时三刻，便将自己喝的酩酊大醉。江上水波不兴，静影沉月，满目星光，李太白只觉自己早已身处凌霄之上，泛舟星河之间，仿佛太白还空，谪仙归位，于是乎，李白只想将明月揽入怀中，便一把向江中的月影揽去……星光中泛开了一些涟漪，从此再无人见过这谪仙人。（纯属虚构）",
	["tid#poetry_715"]="十步杀一人\\n  千里不留行\\n 事了拂衣去\\n  深藏身与名",
	["tid#herounlockedsaying_231"]="我便有经天纬地之才，也不过是沉沦风雅而已。",
	["tid#herounlockedsaying_232"]="庙堂之高哪比得上江湖之广，我纵身江湖方能不虚此生！",
	["tid#herounlockedsaying_233"]="比起诗中仙不如称我饮中仙~！",
	["tid#EquipAffixDes2210"]="核心：太学宫装备时，暴击率提升10%，暴击效果提升25%",
