	["tid#SkillDes_71511"]="太学宫肆意挥洒胸中剑气，诗气，酒气，并将其化为漫天飞剑，对所有敌人造成9段伤害，每段50%攻击力",
	["tid#SkillDes_71512"]="等级2：当酒、诗、剑三气都叠加至5层时，该技能伤害造成的伤害提升40%",
	["tid#SkillDes_71513"]="等级3：对所有敌人造成9段伤害，每段伤害提升至80%攻击力",
	["tid#SkillDes_71514"]="等级4：当酒、诗、剑三气都叠加至5层时，该技能伤害造成的伤害提升60%",
	["tid#SkillDes_71521"]="太学宫挥笔书写诗文，使自身受到的伤害减少80%，持续2秒，并为自身施加1层“诗气”状态，每层诗气状态会使自身暴击率和暴击伤害提升5%，最多叠加10层",
	["tid#SkillDes_71522"]="等级2：当“诗气”叠加至5层时，减伤效果提升至99%持续2秒",
	["tid#SkillDes_71523"]="等级3：战斗开始时，太学宫会立即获得3层“诗气”",
	["tid#SkillDes_71524"]="等级4：当诗气叠加至10层时，每次释放该技能太学宫会无敌并免疫控制2秒",
	["tid#SkillDes_71531"]="太学宫喝下杯中美酒，为自身增加100点内力，并为自身施加1层“酒气”状态，每层“酒气”状态会使自身攻速增加10%，最多叠加10层",
	["tid#SkillDes_71532"]="等级2：当“酒气”叠加至5层时，回内效果提升至200点",
	["tid#SkillDes_71533"]="等级3：战斗开始时，太学宫会立即获得3层“酒气”",
	["tid#SkillDes_71534"]="等级4：当酒气叠加至10层时，恢复的内力提升至400点",
	["tid#SkillDes_71541"]="太学宫挥舞宝剑，向前方释放出一道剑气，对范围三个敌人造成200%攻击力的伤害，并为自身施加1层“剑气”状态，每层“剑气”状态会使自身攻击力增加10%，最多叠加10层",
	["tid#SkillDes_71542"]="等级2：当“剑气”叠加至5层时，剑气的攻击范围会大幅度提升",
	["tid#SkillDes_71543"]="等级3：战斗开始时，太学宫会立即获得3层“剑气”",
	["tid#SkillDes_71544"]="等级4：当剑气叠加至10层时，该技能会连续释放出两道剑气",
	["tid#SkillDes_71551"]="太学宫普攻",
	["tid#seal_character_tips"]="1.符篆一经使用无法卸下；\n2.使用符篆时，随机获得1-3条属性，根据品阶不同获得属性条数上限不同：\n·红色符篆必定有一条属性，有10%概率获得两条属性；\n·白色符篆必定有两条属性，有10%概率获得三条属性；\n·彩色符篆必然有三条属性；\n3.品阶越高的属性数值上限越高；\n4.不同符篆使用后获得套装效果不同，同一侠客在不同部位使用相同的符篆后获得的随机属性及属性上限不同；\n5.使用新的符篆会将原有符篆效果替换掉；\n6.低品阶符篆不能覆盖高品阶符篆；\n\n",
