	["tid#itemDes2716"]="集齐60个可立即获得侠客凤仪亭",
	["tid#Herolife_716"]="以声色为戈矛，甘愿牺牲自己来挽救朝堂的奇女子，只可惜其身也似浮萍，飘荡在乱世当中，最后随着吕布的身死，化作历史岁月当中的一段烟尘。不过也因此，其美貌声名也在人们的口舌相传众永存。",
	["tid#Herolegend1_716"]="传说之中，貂蝉并非是一开始便成为了王允的义女的。东汉末年，一个樵夫打柴之时，突然听到山崖上有婴儿的啼哭之声，并且声量洪亮，令林间飞鸟都惊起而逃。后来樵夫循声而去，在一个半山腰的山洞之间，竟然看到山洞内有一张石桌，石桌之上有一个斗篷裹着的女婴，女婴的脸蛋如同粉雕玉琢十分可爱，樵夫一阵又惊又喜，便上前将女婴小心翼翼地抱起，却没想到女婴立刻停止了哭泣，又望着樵夫笑了起来。",
	["tid#Herolegend2_716"]="樵夫将女婴背在身上就打算按原路下山时，在半路上遇到一位鹤发童颜的老者，相逢而笑，执意要为女婴起一个名字，樵夫见此人满身仙气，倒也不多做怀疑，并应允了下来，于是老者为女婴起名貂蝉，那樵夫虽是个粗人，但觉得此名甚好，就一边逗弄着身上的孩子边一遍一遍说着貂蝉这个名字，之时樵夫正要转头跟老者道谢时，却发现老者早就没了踪影。",
	["tid#Herolegend3_716"]="不过后来樵夫却因为身染重疾，不幸离世，貂蝉为了葬父不得不委身为奴，不过因为天生丽质又善于歌舞，几经辗转成为司徒王允的歌女。貂蝉在王允府上的经历，也渐渐看懂了不少所谓的天下大势，见东汉王朝被奸臣董卓所操纵，于月下焚香祷告上天，愿为主人分忧。王允看到之后，得知了貂蝉心意，便想出一桩连环之计来铲除董卓。",
	["tid#Herolegend4_716"]="王允知晓吕布人称飞将军，骁勇善战，天下无敌，而董卓老奸巨猾，平常人也根本难以靠近，且不说身侧的吕布也无人能对董卓不利。然而，两人皆是好色之徒，王允便暗地里将貂蝉许配给吕布，再将貂蝉献给董卓，使得貂蝉周旋二人之间，迷得他们神魂颠倒。",
	["tid#Herolegend5_716"]="却说王允的计谋果然大成，自从貂蝉被纳入董卓府内之后，吕布耿耿于怀十分不满。一日，吕布趁董卓不在府中，前往董卓府上与貂蝉在凤仪亭相会，貂蝉一见到吕布就哭诉自己被董卓霸占之苦，又向吕布倾诉自己对吕布的倾慕和相思，引得吕布大怒。这是董卓突然回府撞见二人私会，更是怒发冲冠，夺过画戟直刺吕布，二人也自此互相猜忌。",
	["tid#herolegend6_716"]="后来王允便趁虚而入，鼓动吕布铲除了董卓，吕布果真也不负王允所望，令董卓血洒皇宫之前，计成之后，貂蝉却也不得不跟随着吕布四处漂泊，毕竟吕布也终是个反复无常的小人，虽有一身本领最后还是命吊白门楼。白门楼之后貂蝉的身世倒也成了迷，有人说貂蝉被曹操许给关羽，意图调拨刘关张三人，却被刚直中心的关羽所杀，另有一说被曹操作为礼物送给了爱将。只不过所有的传言可能也都是掩人耳目罢了，真正的行踪也无人说的清楚。",
	["tid#herolegend7_716"]="所谓“闭月”，是貂蝉为世人称道为美人的代称。传闻貂蝉在后花园拜月时，突然一阵清风袭来，便将一块儿流云吹向皎洁的明月，夜色也随之一沉，烛火下的貂蝉的脸反而显得更加玲珑剔透，如同一件精雕细琢的瑰宝。此情此景也正由王允撞见，因此在向董卓进献貂蝉之前，逢人便说自己的女儿国色天香，能使当头明月羞于相见，不得不以流云遮挡自己的面目，因此后来貂蝉便被人称为“闭月”了。",
	["tid#poetry_716"]="红牙摧拍燕飞忙\\n  一片行云到画堂\\n 眉黛促成游子恨\\n  脸容初断故人肠",
	["tid#herounlockedsaying_234"]="美貌之于我，便如流云遮月，教你看不到我的本心。",
	["tid#herounlockedsaying_235"]="莫说什么红颜祸水，那不过是文人们的托词罢了。",
	["tid#herounlockedsaying_236"]="可是身处乱世，哪有什么安身之所呢？",
	["tid#EquipAffixDes3109"]="核心：凤仪亭装备时，治疗效果提升17%",
