	["tid#SkillDes_71611"]="貂蝉舞动腰肢，使所有敌方侠客攻速降低40%，并使其受到的伤害增加40%，持续6秒，并随机魅惑四名敌人3秒，被魅惑的敌人只能使用普攻攻击且回内效果减少50%，被魅惑的敌方侠客5秒内不会再被魅惑技能命中",
	["tid#SkillDes_71612"]="等级2：攻击降低和伤害增加效果的时间提升至8秒",
	["tid#SkillDes_71613"]="等级3：被魅惑的侠客可以使用除必杀技以外的技能",
	["tid#SkillDes_71614"]="等级4：攻速降低效果提升至50%，伤害增加效果提升至50%",
	["tid#SkillDes_71621"]="战斗中，只要貂蝉在场，我方所有侠客的攻击不会被闪避，且敌方侠客造成的内功伤害会降低20%，效果会在貂蝉离场后消失",
	["tid#SkillDes_71622"]="等级2：若貂蝉在场上存活超过15秒，则该技能效果在貂蝉死亡后也不会消失",
	["tid#SkillDes_71623"]="等级3：我方侠客还会获得貂蝉攻速属性和攻击属性的30%",
	["tid#SkillDes_71624"]="等级4：我方侠客还会获得貂蝉攻速属性和攻击属性的40%",
	["tid#SkillDes_71631"]="战斗中，当貂蝉受到致命伤害时，会免疫本次伤害并瞬移到我方随机一位角色身后，为自己和该角色恢复300%攻击力的血量，并使该角色和自己无敌2秒，该效果有12秒冷却时间，若我方场上存在男性战士职业角色，则会优先选择该角色，若场上无男性角色，女性角色同上",
	["tid#SkillDes_71632"]="等级2：恢复的血量提升至320%攻击力",
	["tid#SkillDes_71633"]="等级3：触发该技能后，貂蝉还会为自己和该角色增加200点内力",
	["tid#SkillDes_71634"]="等级4：冷却时间缩短至10秒",
	["tid#SkillDes_71641"]="貂蝉为场上血量百分比最低的己方侠客施加恢复效果，为其恢复300%攻击力的生命值，并使其防御力增加40%，持续5秒",
	["tid#SkillDes_71642"]="等级2：恢复的血量提升至330%攻击力",
	["tid#SkillDes_71643"]="等级3：被施加恢复效果的友军，通过受击回复的内力会增加50%，持续5秒",
	["tid#SkillDes_71644"]="等级4：该技能对血量百分比低于30%的友军造成的恢复效果会增加50%",
