	["tid#SkillDes_71661"]="貂蝉放逐攻击力最高的敌人，使其无法攻击也无法受到伤害，放逐期间貂蝉会获得所放逐敌人40%的攻击力和生命值，持续4秒。仅剩余1名敌人时，貂蝉仍然能获得属性的提升，但不再放逐敌人，而是降低敌人50%的攻击力，使其受到伤害提高50%",
	["tid#SkillDes_71662"]="等级2：放逐效果及吸取属性效果的时间提升至6秒",
	["tid#SkillDes_71663"]="等级3：放逐吸取属性的效果提高至60%",
	["tid#SkillDes_71664"]="等级4：仅剩1名敌人时，降低攻击力和受到伤害效果提升至70%",
	["tid#SkillDes_71671"]="场上每有一名侠客阵亡（无论敌我），貂蝉回复100点内力，并获得【连环】效果，每层提高10%攻击力和暴击率。",
	["tid#SkillDes_71672"]="等级2：在貂蝉获得【连环】效果时，其他队友也会获得该效果，在貂蝉死亡后移除该效果。",
	["tid#SkillDes_71673"]="等级3：貂蝉和己方侠客在每次获得【连环】效果时，恢复30%的最大生命值",
	["tid#SkillDes_71674"]="等级4：每次获得连环效果时，貂蝉会叠加2层",
