	["tid#itemDes_5617"]="蕴含神秘力量的印记，可以在联动侠客进阶时代替任意一张阴系联动侠客，尚在联动期间内的侠客不能使用",
	["tid#itemDes_5618"]="蕴含神秘力量的印记，可以在联动侠客进阶时代替任意一张阳系系联动侠客，尚在联动期间内的侠客不能使用",
