	["tid#itemDes_5624"]="天地灵气凝结成的纯粹结晶，可在登仙楼中用于侠客登仙，使用是可以增加35点进度值",
	["tid#itemDes_5625"]="天地灵气凝结成的大块结晶，可在登仙楼中用于侠客登仙，使用是可以增加12点进度值",
	["tid#itemDes_5626"]="天地灵气凝聚成的结晶，可在登仙楼中用于侠客登仙，使用是可以增加5点进度值",
	["tid#itemDes_5627"]="天地灵气残留的小碎块，可在登仙楼中用于侠客登仙，使用是可以增加2点进度值",
	["tid#itemDes_5628"]="天地灵气残留的碎片，可在登仙楼中用于侠客登仙，使用是可以增加1点进度值",
	["tid#AwakenDes_001"]="我正在进行侠客%s的渡劫，请少侠帮我助威，助我成功",
	["tid#itemName_5629"]="先天灵魄",
	["tid#itemName_5630"]="破镜丹",
	["tid#itemName_5631"]="入梦铃",
	["tid#itemDes_5629"]="蕴含一丝先天之气的神魄，可以再帮助侠客突破登仙瓶颈，打到更高的境界",
	["tid#itemDes_5630"]="蕴含雷劫之力的丹药，可以帮助侠客突破登仙境界",
	["tid#itemDes_5631"]="氤氲着玄妙气息的铃铛，据说其声音可以使人入梦，重温过去的记忆",
	["tid#itemName_5632"]="羽化丹",
	["tid#itemDes_5632"]="用玄鸟神羽炼制的丹药，可以开启侠客羽化，达到更高的武学境界",
	["tid#Herolife_718"]="公堂上执笔断案的“神探”，庙堂上直言进谏的丞相。出身官宦人家的狄仁杰自小立志成为一名“好官”，大理寺断案千百起，让他名声大振，仕途高升后仍然坚守着他心中的正道。聪慧过人的同时，也因长期伏案，身体大不如以前，没少被小跟班方誉拉着强身健体。",
	["tid#Herolegend1_718"]="幼年时代：年少时的狄仁杰随祖父住在晋阳，祖父为太原狄氏，官居高位，其清廉严苛的作风给狄仁杰留下了深刻的印象，也让他励志成为一名好官。同时，因为长期与祖父生活，也让狄仁杰喜好文墨，年少时便读书万卷，还自行为邻里审理“冤假错案”。",
	["tid#Herolegend2_718"]="踏入仕途：狄仁杰天性聪慧，参加科举后得到贵人赏识。随后迅速高升，身居汴州判佐时几次协助审理民间案情，从不徇私舞弊，很受百姓爱戴。仪凤年间升任大理寺丞，而这几乎改变了他的一生，不仅因为他神探的名声远扬，也因为他在前往大理寺的路上遇见了一位少年，也就是他日后的得力助手，方誉。（参考李元芳杜撰）",
	["tid#Herolegend3_718"]="大理寺丞：身居大理寺丞是狄仁杰传奇一生的开始，有突厥血统的方誉曾在汴州时候被狄仁杰所救，一直遭受冷眼的少年立刻决定追随狄仁杰。（杜撰）于是狄仁杰在大理寺得到了一位得力的保镖兼助手，他主张审理判决大量积压案件，甚至与方誉一起便衣出入市井乡野为百姓查案（此处杜撰）。处理案件涉及一万七千人，无一人冤诉，在当时引起了极大的轰动。狄仁杰因此名声大振。",
	["tid#Herolegend4_718"]="累职拜相：百姓爱戴狄仁杰，为他立碑勒石。狄仁杰的美名很快流传至朝廷，被封为东官侍郎。后也因朝堂争斗被贬为刺史，这让狄仁杰第一次清晰意识到庙堂之上的险恶。但无论狄仁杰处于何种境地，方誉都一直跟在狄仁杰身边保护他的安全。武则天称帝后，因爱惜人才，重新召回狄仁杰并为其加授宰相，狄仁杰由此正式走向政权中心。",
	["tid#Herolegend5_718"]="谪贬彭泽：朝堂上风波不断，因酷吏的诬告，狄仁杰险些死于酷刑。好在狄仁杰将暗号以石灰写在衣物中，及时将伸冤书信送到方誉手中。方誉策马从神都赶往长安，向武则天陈情，但当时酷吏掌权，大势已去，最后狄仁杰被贬到彭泽担任县令。",
	["tid#herolegend6_718"]="复居宰辅：契丹入侵，武则天再次启用狄仁杰。狄仁杰带着方誉前往其故乡，想要为其找回亲人，但方誉不愿离去，狄仁杰也意识到自己与年纪相差许多的方誉已是挚友。在契丹，狄仁杰凭借聪明才智胜仗而归，武则天为其写金字锦袍，以示其忠诚。后狄仁杰再次拜相，恩宠冠绝当朝。",
	["tid#herolegend7_718"]="晚年生活:狄仁杰拜相后仍不断关心百姓，为天下人称道，受百姓爱戴和武则天的信任。得武则天的批准，狄仁杰在长安修建新的“大理寺”，继续和方誉一起查案断案，在长安留下了更多的传奇。（杜撰）去世多年仍被唐中宗、唐睿宗追封称号，配享太庙。",
	["tid#poetry_718"]="一心清正千家福\\n  两字公平百姓安\\n 惟有昌平旧令尹\\n  留传案牍后人看",
	["tid#herounlockedsaying_237"]="明察秋毫，是非分明。",
	["tid#herounlockedsaying_238"]="时机还未到，但有些事，我早就有了头绪。",
	["tid#herounlockedsaying_239"]="天下不平之事，皆断于我眼。",
	["tid#EquipAffixDes3311"]="核心：大理寺装备时，攻击速度提升16，忽视敌方6%的内伤减免",
	["tid#SkillDes_71811"]="对所有敌方加一层断狱，根据敌人身上的断狱层数获得不同效果；笞刑(1层):造成200%的伤害，之后6秒内，“断狱”造成的伤害增加效果翻倍；杖刑(2层):造成200%的伤害，眩晕2秒，之后6秒内，“断狱”造成的伤害增加效果翻倍；斩立决(3层):造成200%的伤害，眩晕2秒，额外增加一层“斩立决”，持续6秒，该状态下，“断狱”造成的伤害增加效果翻倍，造成的伤害减少50%，攻速减少50%，若敌人在“斩立决”状态下生命值低于5%，会立即死亡，无视免死效果（无法对首领敌人生效）",
	["tid#SkillDes_71812"]="等级2：笞刑和杖刑中，断狱效果翻倍的时间提升至8秒",
	["tid#SkillDes_71813"]="等级3：杖刑和斩立决中，眩晕时间提升至3秒",
	["tid#SkillDes_71814"]="等级4：斩立决中，无视免死判定血量提高至10%",
	["tid#SkillDes_71821"]="战斗开始时，狄仁杰会选择敌方全体侠客揭露其罪行并为其施加一层“断狱”状态，断狱状态会一直持续到战斗结束或狄仁杰死亡，且最多叠加3层，每有一层断狱状态，该敌人受到的伤害变会增加10%，之后战斗时间每过去10秒，狄仁杰还会随机选择2个角色，并为其施加1层“断狱”状态，若武则天在场，则必须武则天也死亡才会消失",
	["tid#SkillDes_71822"]="等级2：被施加断狱状态的敌人还降低攻击力10%，持续5秒",
	["tid#SkillDes_71823"]="等级3：断狱状态的伤害增加效果提升至15%",
	["tid#SkillDes_71824"]="等级4：击杀我方单位的敌方侠客将立刻被施加一层断狱状态",
	["tid#SkillDes_71831"]="战斗开始时，狄仁杰会选择一名敌方攻击力最高的侠客，使其沉默5秒，当狄仁杰每次为敌人施加“断狱”状态时，还会随机为一名我方侠客施加一层“明断”状态，处于“明断”状态的友军会获得5%的攻击力和攻速提升，持续5秒，最多提升叠加3层，明断状态会优先选择武则天",
	["tid#SkillDes_71832"]="等级2：明断状态的持续时间提升至8秒",
	["tid#SkillDes_71833"]="等级3：被沉默的敌人在沉默结束后造成的伤害会降低30%，持续5秒",
	["tid#SkillDes_71834"]="等级4：明断状态的效果提升至7%攻击力和攻击速度",
	["tid#SkillDes_71841"]="战斗中，当狄仁杰首次死亡时，会以最大生命值30%的血量、恢复300点内力复活并使自身无敌2秒，复活时，狄仁杰还会对自身周围造成一次200%攻击力的伤害并使命中的侠客眩晕2秒",
	["tid#SkillDes_71842"]="等级2：恢复的内力提升为400点，血量提升至40%",
	["tid#SkillDes_71843"]="等级3：被命中的敌方侠客还会被施加一层“断狱”效果",
	["tid#SkillDes_71844"]="等级4：恢复的内力提升为500点，血量提升至50%",
	["tid#SkillDes_71851"]="大理寺普攻",
	["tid#SkillDes_71861"]="狄仁杰先为所有敌方侠客施加一层断狱状态，随后对其进行审判，敌人身上每有一层“断狱”状态，便会被施加一层“伏刑”状态，“伏刑”状态会持续3秒，且每秒会发作一次，每次发作时会造成100%攻击力的伤害和0.5秒的眩晕效果，该技能施加的眩晕效果可以叠加",
	["tid#SkillDes_71862"]="等级2：伏刑状态的攻击力提升至120%攻击力",
	["tid#SkillDes_71863"]="等级3：伏刑状态的持续时间提升至5秒",
	["tid#SkillDes_71864"]="等级4：被叠加三层伏刑状态的敌方侠客将会立即被眩晕2秒",
	["tid#SkillDes_71871"]="狄仁杰随机攻击两名敌方侠客，对其造成攻击力220%的伤害并使其禁锢3秒，并为其施加一层“断狱”状态，且每次有敌方侠客被施加“断狱”状态，狄仁杰都活获得7%伤害提升，持续5秒，最多叠加5层，若场上同时存在武则天，则武则天每次施加“慑服”状态还会使狄仁杰的攻速提升7%，持续5秒，最多叠加5层",
	["tid#SkillDes_71872"]="等级2：伤害提升至240%攻击力",
	["tid#SkillDes_71873"]="等级3：该技能现在会额外随机选择一名敌方侠客",
	["tid#SkillDes_71874"]="等级4：伤害提升效果的持续时间提升至8秒",
