	["tid#SkillName_10000541"]="封印之殇·葬",
	["tid#SkillName_10000551"]="普攻",
	["tid#Herolife_717"]="日月当空，位居人极，是天朝唯一的女皇帝。武则天一生传奇跌宕，风流一世，但功过是非正如她陵前的无字碑一般，但凭后世人评说。",
	["tid#Herolegend1_717"]="初入宫廷：武则天幼年丧父，随母亲搬回长安居住。她容貌美丽，性格酷似男儿，十四岁时候被唐太宗李世民选中，入宫做才人。入宫后，她并未得到李世民的荣宠，做了十二年才人，未得晋升，但在此期间，她与太子李治建立起了感情。",
	["tid#Herolegend2_717"]="再次入宫：李世民去世后，武则天和其他没有子嗣的旧朝嫔妃一起进入感业寺为尼。然而武则天并未囿于此地，一年后新王李治来到感业寺祭奠太宗，再次遇到令他朝思暮想的武则天。恰逢王皇后想要利用武则天制衡得宠的萧淑妃，因此李治顺利纳武则天入后宫，她得宠迅速，很快被拜为二品昭仪。",
	["tid#Herolegend3_717"]="废王立武：随着武则天越来越得宠，加之前朝大臣的牵制，让李治产生了废王立武的念头。此事不仅能让武则天成为皇后，更是为了借此重振皇权，打击元老大臣的势力。武则天此时便与李治成为了战友，显庆四年，经过武则天和李治的不断筹谋斗争，武则天被封为皇后，李治更是借此将权力牢牢把握。",
	["tid#Herolegend4_717"]="二圣临朝：李治风疾发作，开始让武则天代理政务，这也让武则天逐渐走进了权力中心。但二人也不免因此起了争执，李治开始忌惮武则天的能力，几次想废后，最终都被武则天化解。处理政务期间，武则天兴修佛像，编写农书，并召集北门学士分割宰相权力，政绩卓越。李治驾崩后，传位给了太子李显，武则天正式以太后身份参政。",
	["tid#Herolegend5_717"]="太后称制：武则天临朝称制期间，广开言路，发展宗教文化。有“圣母临人，永昌帝业”的美称。同时，武则天铲除了朝中逆党，大败越王李贞，稳固了朝政。垂拱四年，在武则天的授意下万象神宫建成，外臣纷纷来朝，为武则天的女皇之路打下了坚实的基础。",
	["tid#herolegend6_717"]="女皇岁月：“凤集上阳宫，赤雀见朝堂”，武则天成为一代女皇，改国号为周，定都神都。在位期间，武则天创立试官制度，安定安西四镇，平定叛乱。诸多政绩让一代女皇的名号响彻天下。圣历元年，武则天开始设立太子，在多方权衡下，最终放弃武姓子嗣，定李显为太子。",
	["tid#herolegend7_717"]="退位去世：神龙政变后，正逢武则天病笃，最终她还政于李显，李唐王室因此重回。武则天退位后迁入上阳宫，于仙居殿病逝，享年八十二岁。",
	["tid#poetry_717"]="赫赫离精御炎陆\\n  滔滔炽景开隆暑\\n 冀延神鉴俯兰樽\\n  式表虔襟陈桂俎",
	["tid#herounlockedsaying_240"]="朕就是要让天下人知道，女人也可以临朝天下！",
	["tid#herounlockedsaying_241"]="功过是非全由后世人评说，朕只做朕认为对的事情。",
	["tid#herounlockedsaying_242"]="九域之广，岂一人之强化，必伫才能，共成羽翼。",
	["tid#EquipAffixDes3209"]="核心：神都上阳宫装备时，最终伤害提升8%，暴击提升5%",
	["tid#SkillDes_71711"]="武则天释放火凤之力，召唤火凤席卷敌方战场，对所有敌人造成500%攻击力的伤害并为使其眩晕2秒",
	["tid#SkillDes_71712"]="等级2：被命中的敌人身上如果有慑服状态，则会清除所有慑服状态并使其伤害立刻生效",
	["tid#SkillDes_71713"]="等级3：造成的伤害提升至550%攻击力",
	["tid#SkillDes_71714"]="等级4：若被命中的敌人身上同时有“慑服”和“断狱”状态，则该技能造成的伤害会提升50%",
	["tid#SkillDes_71721"]="武则天在敌方阵营中召唤牡丹，牡丹会在短暂延迟后炸开，对范围内的敌人造成200%攻击力的伤害，并为其施加一层“慑服”状态，处于慑服状态中的敌人每秒会受到50%攻击力的伤害，持续8秒，最多叠加5层",
	["tid#SkillDes_71722"]="等级2：伤害提升至220%攻击力",
	["tid#SkillDes_71723"]="等级3：慑服状态每叠加一层，该状态造成的伤害便会提升20%",
	["tid#SkillDes_71724"]="等级4：战斗开始8秒后，该技能会替换为武则天的普攻",
	["tid#SkillDes_71731"]="战斗开始时，我方场上每有一个攻击力低于武则天的角色，武则天便会额外获得其5%攻击力的加成，该效果会持续到战斗结束，若场上同时存在狄仁杰，则通过该效果获得的加成会提升50%",
	["tid#SkillDes_71732"]="等级2：每有一个攻击力低于武则天的角色，获得的加成提升至7%",
	["tid#SkillDes_71733"]="等级3：每有一个攻击力低于武则天的角色，获得的加成提升至10%",
	["tid#SkillDes_71734"]="等级4：该技能还会额外选择三名随机敌方侠客，若其攻击力低于武则天，则武则天会吸取其10%的攻击力加给自己",
	["tid#SkillDes_71741"]="战斗开始前10秒，武则天会免疫所有负面效果，且每有一个敌方或己方侠客死亡，武则天便会恢复10%最大生命值的血量，并使自身无敌2秒",
	["tid#SkillDes_71742"]="等级2：免疫负面效果的时间提升至12秒",
	["tid#SkillDes_71743"]="等级3：当武则天受到致命伤害时，会免疫本次伤害并选择我方一名生命值最低的侠客，在之后的2秒内，将自身受到的伤害全部转移给该侠客，该效果有15秒冷却时间",
	["tid#SkillDes_71744"]="等级4：恢复血量提升至15%最大生命值",
	["tid#SkillDes_71751"]="神都上阳宫普攻",
	["tid#SkillDes_71761"]="武则天转换为冰煌神力，互换冰凰攻击敌方全场，对所有敌人造成200%攻击力的伤害，并使其冰冻2秒，被命中的敌人还会被额外施加一层“霜羽”状态",
	["tid#SkillDes_71762"]="等级2：冰冻时间提升至3秒",
	["tid#SkillDes_71763"]="等级3：伤害提升至240%攻击力",
	["tid#SkillDes_71764"]="等级4：命中的敌人每有一层霜羽状态，还会使其受到的伤害增加10%，持续5秒",
	["tid#SkillDes_71771"]="战斗中，武则天每次为敌人施加“慑服”状态时，还会额外施加一层“霜羽”状态，处于“霜羽”状态的敌人，攻击力和攻击速度会降低8%，持续5秒，最多叠加5层，当我方侠客死亡时，会立即为击杀者施加5层“霜羽”状态，若场上同时存在狄仁杰，则狄仁杰每次施加“断狱”效果时，都有30%的几率额外施加一层“霜羽”效果",
	["tid#SkillDes_71772"]="等级2：霜羽状态的持续时间提升至8秒",
	["tid#SkillDes_71773"]="等级3：“霜羽”状态的攻速和攻击力降低效果提升至10%",
	["tid#SkillDes_71774"]="等级4：当敌人身上的“霜羽”状态叠加至5层时，会立即被冰冻2秒，该效果有10秒的冷却时间",
