	["tid#ActiveItemName_5641"]="元系侠客自选箱",
	["tid#ActiveItemDes_5641"]="开启后可以在以下奖励中任选一个。",
	["tid#Fateskillname_71701"]="玄天威凤",
	["tid#Fateskillname_71702"]="玄天星降（天命）",
	["tid#Fateskillname_71703"]="敬请期待",
	["tid#Fateskillname_71704"]="敬请期待",
	["tid#Fateskillname_71801"]="神机妙算",
	["tid#Fateskillname_71802"]="无量慈悲（天命）",
	["tid#Fateskillname_71803"]="敬请期待",
	["tid#Fateskillname_71804"]="敬请期待",
	["tid#FateDes_717"]="玄天且听凤凰鸣，功过一掷天下评。",
	["tid#FateDes_718"]="案上书神机妙算，庙堂唤万家平安。",
	["tid#FateskillDes_71701"]="天下归心：武则天在开场时会对敌方攻击力最高的一个敌人沉默3秒",
	["tid#FateskillDes_71702"]="持有此技能的侠客上场时，提升友方全体侠客3%最终伤害",
	["tid#FateskillDes_71703"]="",
	["tid#FateskillDes_71704"]="",
	["tid#FateskillDes_71801"]="料事如神：战斗中，当狄仁杰首次死亡时，复活血量提升至80%",
	["tid#FateskillDes_71802"]="持有此技能的侠客上场时，提升友方全体侠客每秒10点内力回复",
	["tid#FateskillDes_71803"]="",
	["tid#FateskillDes_71804"]="",
	["tid#MysticName_9304"]="紫霞神功",
	["tid#MysticName_9305"]="天鉴神功",
	["tid#MysticDes_9304"]="华山派称霸江湖的上乘内功，初发时若有若无，绵如云霞，蓄劲极韧，铺天盖地，势不可当。发功之人脸上满布紫气，故有“华山九功第一紫霞”之称。",
	["tid#MysticDes_9305"]="传说中逍遥派最高秘法，刻在三百六十面铜镜上，学成之后独步天下无人能及",
	["tid#MysticBuffName_93004"]="紫霞神功-秘籍效果",
	["tid#MysticBuffName_93014"]="紫霞神功-职业效果",
	["tid#MysticBuffName_93005"]="天鉴神功-秘籍效果",
	["tid#MysticBuffName_93015"]="天鉴神功-职业效果",
	["tid#MysticBuffDes_93004"]="战斗开始时，自身暴击率提升20%，暴击效果8%，持续时间8秒",
	["tid#MysticBuffDes_93014"]="释放绝技时如命中的敌对目标被暴击，则该目标内力降低30，多段攻击仅计算第一次",
	["tid#MysticBuffDes_93005"]="战斗开始时，自身血量上限提高30%，持续时间10秒",
	["tid#MysticBuffDes_93015"]="释放绝技后2秒时间内如被敌方攻击则为自身回血，每被攻击一下恢复10%，最多恢复50%",
	["tid#MysticBuffDesclass_93004"]="射手装备激活：释放绝技时如命中的敌对目标被暴击，则该目标内力降低30，多段攻击仅计算第一次",
	["tid#MysticBuffDesclass_93014"]="射手装备激活：释放绝技时如命中的敌对目标被暴击，则该目标内力降低30，多段攻击仅计算第一次",
	["tid#MysticBuffDesclass_93005"]="护卫装备激活：释放绝技后2秒时间内如被敌方攻击则为自身回血，每被攻击一下恢复10%，最多恢复50%",
	["tid#MysticBuffDesclass_93015"]="护卫装备激活：释放绝技后2秒时间内如被敌方攻击则为自身回血，每被攻击一下恢复10%，最多恢复50%",
	["tid#Herolife_705"]="无名杀手，生平不详。初见她的人都不知这俊俏又寡言的少女双拳有乾坤，她那刚柔并济的功夫曾取走无数性命。无人能知晓她的秘密，但要是端一碗面，趁着蓬莱夜色重，能在后山找到正在数星星的廿四，认真听，兴许能从她的只言片语中，听出她那惊心动魄的前尘往事。",
	["tid#Herolegend1_705"]="无名无姓，不记来历，身如浮萍。廿四记事起就在某个刺客组成的无名帮派之中接受训练，训练艰苦但从未抗拒帮派的指令，最终被培养成了一位无言的杀手。",
	["tid#Herolegend2_705"]="廿四甚至不知道自己是从什么时候开始接受了帮派给的任务，又是什么时候开始进行刺杀。因其手段高超，行事冷静且行踪难寻，声名便在江湖上传开，只不过没人知道她名字的来历和背后的意义。",
	["tid#Herolegend3_705"]="江湖传言，有人曾在某月黑风高夜看见一娇俏少女自屋顶跃下。手中未佩武器，却双拳有力，以太极之势取一人性命，功夫刚柔并济，十分少见。因这传言太像话本小说的桥段，未被太多人信服。",
	["tid#Herolegend4_705"]="廿四面对的刺杀对象从门派弟子到世家皇族，她手段干脆且从未留下线索，许多人为了捉拿她不惜千金。但廿四总能凭借冷静和高超的武功逃脱追捕。",
	["tid#Herolegend5_705"]="直到有一次，她在房梁之上观察自己的目标。这次的目标是当地的一位大员，她看到这位大员与家人一起其乐融融的样子，不知为何突然不想继续完成任务了，于是廿四的人生从这一刻改变。",
	["tid#herolegend6_705"]="廿四遭到了无尽的追击，无名帮派将她视作叛徒。那些平日以师傅和长辈称呼的人，皆通过对她的了解迅速找到她的行踪。在追杀中，廿四偶然到达一世外仙境，那地方便是蓬莱。",
	["tid#herolegend7_705"]="蓬莱岛的人收留了廿四，她每日过得悠闲自在，再未有过杀戮。每夜蓬莱岛上空的银河，都让廿四产生了从未有过的安心。",
	["tid#poetry_705"]="心若素水清\\n  山崩亦无惊\\n 本来无一物\\n  何惧世无名",
	["tid#herounlockedsaying_243"]="一颗……两颗……啊？怎么了？旧时云裳已不再用，只剩这枝红梅，我不肯忘。",
	["tid#herounlockedsaying_244"]="你……可以叫我廿四……愿天下女郎，皆破业障，不求留名千古，但求不负命途。",
	["tid#herounlockedsaying_245"]="又有新的任务了吗？我上了沙场，就要打胜仗。",
	["tid#EquipAffixDes3110"]="核心：太极内家拳装备时，治疗效果提升17%，攻击速度增加4",
	["tid#SkillDes_70511"]="太极内家拳释放太极阵图笼罩全场，持续5秒，阵图每秒会爆发一次，每次都对范围内的敌方侠客造成220%攻击力的内功伤害，期间对敌方造成3秒眩晕效果，对范围内的己方侠客造成150%攻击力的恢复效果",
	["tid#SkillDes_70512"]="等级2：伤害提升至240%攻击力，恢复效果提升至180%攻击力",
	["tid#SkillDes_70513"]="等级3：伤害提升至260%攻击力，范围内的己方侠客还会获得20%攻击加成",
	["tid#SkillDes_70514"]="等级4：范围内的己方侠客还会获得30%攻击加成",
	["tid#SkillDes_70521"]="战斗开始时，太极内家拳会在战场上布下阵图，极阳和极阴两种状态，战斗时间每过10秒会转换一次，当处于极阳时，我方所有侠客都会获得一个极阳之力，使自身受到的伤害减少20%，最大血量提升20%；当处于极阴时，敌方所有侠客都会获得一个极阴之力，使其受到的伤害增加20%，当太极内家拳死亡时，阵图便会消失",
	["tid#SkillDes_70522"]="等级2：极阳之力提供的防御力和血量提升至25%；极阴之力施加的伤害增加提升至25%",
	["tid#SkillDes_70523"]="等级3：太极内家拳死亡时，当前阵图的效果还会停留8秒",
	["tid#SkillDes_70524"]="等级4：极阳之力提供的防御力和血量提升至30%；极阴之力施加的伤害增加提升至30%",
	["tid#SkillDes_70531"]="当阵图处于极阳状态时，太极内家拳会为所有施加了极阳之力的己方侠客施展恢复效果，为其恢复100%攻击的血量，和50点内力；当阵图处于极阴状态时，太极内家拳会对所有施加了极阴之力的敌方侠客造成1段150%攻击力的内功伤害",
	["tid#SkillDes_70532"]="等级2：伤害提升至170%攻击力，恢复血量提升至120%",
	["tid#SkillDes_70533"]="等级3：恢复血量提升至150%，内力恢复效果提升至80",
	["tid#SkillDes_70534"]="等级4：伤害提升至200%，且必定触发极阴印记的爆炸效果",
	["tid#SkillDes_70541"]="当阵图为极阳时，太极内家拳会为所有施加了极阳之力的己方侠客释放一个持续5秒的极阳盾，极阳盾会吸收角色所受伤害的20%并转化为极阳值，当护盾消失会产生爆炸，对周围敌人造成相当于极阳值20%的伤害；当阵图为极阴时，会为所有施加了极阴之力的敌方侠客施展一个持续5秒的极阴印记，当被施加了极阴印记的敌方侠客受到攻击时，极阴印记有15%的概率爆炸，额外造成一次敌方最大生命值5%的真实伤害，最高不超过内家拳攻击力的200%",
	["tid#SkillDes_70542"]="等级2：护盾吸收的伤害提升至25%，持续时间提升至6秒",
	["tid#SkillDes_70543"]="等级3：极阴印记的爆炸概率提升至20%",
	["tid#SkillDes_70544"]="等级4：极阳护盾的爆炸伤害提升至25%极阳值",
	["tid#SkillDes_70551"]="太极内家拳普攻",
	["tid#SkillDes_70561"]="太极内家拳位于4号位会布下太阴阵图，不会再切换，为所有敌方侠客施加太阴之力受到的伤害增加30%；太阴阵图被视为极阴阵图，太阴之力被视为极阴之力；若位于4号以外的位置，则布下太阳阵图，不会再切换，为我方侠客施加太阳之力，受到的伤害减少30%，最大血量提升30%；太阳阵图被视为极阳阵图，太阳之力被视为极阳之力，当太极内家拳死亡时，阵图便会消失",
	["tid#SkillDes_70562"]="等级2：太阴阵图的伤害增加提升至40%",
	["tid#SkillDes_70563"]="等级3：太阳阵图的伤害减少提升至40%，最大血量增加提升至40%",
	["tid#SkillDes_70564"]="等级4：太极内家拳死亡时，当前阵图的效果还会停留8秒",
	["tid#SkillDes_70571"]="为太阴阵图时，太极内家拳会释放太阴之力笼罩全场5秒，每秒对敌方侠客造成200%攻击力的伤害,期间对敌方造成3秒的眩晕效果，当场上阵图为太阳阵图时，太极内家拳会释放太阳之力笼罩全场8秒，对我方侠客施加一个400%攻击力的太阳护盾，持续8秒，太阳护盾消失时，剩余护盾值会转换为我方侠客的血量",
	["tid#SkillDes_70572"]="等级2：太阴阵图的伤害提升至300%攻击力，太阳阵图的护盾提升至600%",
	["tid#SkillDes_70573"]="等级3：太阴阵图每次造成伤害，都有30%的概率触发“极阴印记”的爆炸",
	["tid#SkillDes_70574"]="等级4：太阳阵图每次施加护盾时，还会为己方侠客增加100点内力，该效果每5秒仅能对同一侠客触发1次",
	["tid#SkillName_70561"]="极·玄龙丝引（等级1）",
	["tid#SkillName_70562"]="极·玄龙丝引（等级2）",
	["tid#SkillName_70563"]="极·玄龙丝引（等级3）",
	["tid#SkillName_70564"]="极·玄龙丝引（等级4）",
	["tid#SkillName_70571"]="极·气海沉渊（等级1）",
	["tid#SkillName_70572"]="极·气海沉渊（等级2）",
