	["tid#HeroTypeDes_705"]="职业:辅助   装备:布甲",
	["tid#HeroName_705"]="太极内家拳",
	["tid#itemName2705"]="太极内家拳结缘碎片",
	["tid#itemDes2705"]="集齐60个可立即获得侠客太极内家拳",
