	["tid#herocv_162"]="姜英俊",
	["tid#SkillDes_50161"]="武当选择随机3个敌方侠客，为其施加持续5秒的真武剑意，被施加了真武剑意的侠客，每秒会受到400%攻击力的伤害和0.5秒的眩晕效果，真武剑意会无视敌方护盾；当敌方人数不足3人时，真武剑意会重复施加到同一名侠客身上，最多叠加三层",
	["tid#SkillDes_50162"]="等级2：伤害提升至430%攻击",
	["tid#SkillDes_50163"]="等级3：真武剑意持续时间提升至6秒",
	["tid#SkillDes_50164"]="等级4：伤害提升至450%攻击力",
	["tid#SkillDes_50171"]="战斗开始时，武当会获得一个太极盾，当太极盾存在时，若武当受到了近战范围内的伤害，则太极盾会破碎，并使武当无敌2秒，太极盾破碎15秒后会重新出现",
	["tid#SkillDes_50172"]="等级2：太极盾重新出现的时间缩短至12秒",
	["tid#SkillDes_50173"]="等级3：无敌时间提升至3秒",
	["tid#SkillDes_50174"]="等级4：太极盾重新出现的时间缩短至10秒",
	["tid#SkillDes_60561"]="天下会挥舞锁链，选择敌方当前攻击力最高的敌人并为其施加“缚魂”状态5秒，“缚魂”状态无法被清除，被施加了缚魂状态的敌人，无法攻击和移动，且受到的伤害会增加20%",
	["tid#SkillDes_60562"]="等级2：缚魂状态持续时间提升至6秒",
	["tid#SkillDes_60563"]="等级3：战斗开始时，天下会可以立即释放一次该技能",
	["tid#SkillDes_60564"]="等级4：敌人受到的伤害增加效果提升至30%",
	["tid#SkillDes_60571"]="当天下会一次性受到超过自身最大生命值30%的血量时，会立即将本次伤害降低至自身最大生命值的30%，并使自身无敌2秒，该效果有15秒的冷却时间",
	["tid#SkillDes_60572"]="等级2：触发该效果时，天下会还会恢复10%最大生命值的血量",
	["tid#SkillDes_60573"]="等级3：技能冷却时间缩短至12秒",
	["tid#SkillDes_60574"]="等级4：技能冷却时间缩短至10秒",
