	["tid#Fateskillname_70503"]="敬请期待",
	["tid#Fateskillname_70504"]="敬请期待",
	["tid#FateDes_704"]="万夫不当勇，风雪举天雄。",
	["tid#FateDes_705"]="游龙枕嶙石，天罅生孤星。",
	["tid#FateskillDes_70401"]="风雪神威：三次攻击每次都附加一次3%敌方最大生命值的伤害",
	["tid#FateskillDes_70402"]="友方每存在1/2/3名刺客，自身开场将获得10%/20%/30%的暴击率和50%/100%/150%的暴击伤害，持续5秒）",
	["tid#FateskillDes_70403"]="",
	["tid#FateskillDes_70404"]="",
	["tid#FateskillDes_70501"]="两仪化清：极阴印记爆炸时附加一次3秒内无法使用技能，此效果所有敌方10秒内只能触发一次",
	["tid#FateskillDes_70502"]="持有此技能的侠客上场时，提升友方全体侠客每秒10点内力回复",
	["tid#FateskillDes_70503"]="",
