	["tid#FateskillDes_10501"]="战斗中少林“不坏金身”获得的所有护盾值提升至30%，自身存在护盾时，受到的伤害减少至35%",
	["tid#FateskillDes_41301"]="被“碧波牢”困住的敌人恢复内力降低50%",
