	["seal_character_name_15"]="威赫",
	["seal_character_name_16"]="逆转",
	["seal_character_suittips_15"]="血量+20%",
	["seal_character_suittips_16"]="血量+10%\n攻击+5%",
	["seal_character_suittips_1_15"]="自身血量低于50%时，每次攻击有30%几率强制对手攻击自己1秒",
	["seal_character_suittips_1_16"]="每次使用技能，如对方被强行控制（沉默、晕眩、束缚、冰冻）则有30%几率吸取对方30内力，多段攻击只生效1次（分身不算在内）",
	["seal_character_story_15"]="使用时必然获得三条随机属性\n两件获得共鸣增益：\n血量+20%\n四件获得共鸣增益：自身血量低于50%时，每次攻击有30%几率强制对手攻击自己1秒",
	["seal_character_story_16"]="使用时必然获得三条随机属性\n两件获得共鸣增益：\n血量+10%、攻击+5%\n四件获得共鸣增益：每次使用技能，如对方被强行控制（沉默、晕眩、束缚、冰冻）则有30%几率吸取对方30内力，多段攻击只生效1次（分身不算在内）",
	["tid#MysticName_9306"]="阴阳乾坤决",
	["tid#MysticDes_9306"]="天地乾坤定,万物阴阳有。开合刚柔间,天下任君走。",
	["tid#MysticBuffDes_93006"]="战斗开始时，自身血量提高15%、防御提高15%，持续时间8秒",
	["tid#MysticBuffDes_93016"]="辅助装备激活：战斗开始增加50内力\n为友方目标施加“护盾”增益时，使自身获得一个下次受到致死伤害时无敌2秒，此效果持续时间8秒，无敌效果一场战斗最多触发1次",
	["tid#Heroclass_720"]="关羽",
