	["tid#SkillName_72073"]="极·武圣之力（等级3）",
	["tid#SkillName_72074"]="极·武圣之力（等级4）",
	["tid#SkillDes_72011"]="关羽释放武圣之力，恢复自身30%最大生命值的血量并进入“武圣”状态，关羽会获得50%的伤害减免和50%的伤害提升，免疫所有控制效果且每秒会对自身周围的敌人造成100%攻击力的伤害，技能结束时，关羽会对距离自己最近的一名敌人额外释放一次“青龙偃月”，释放不会消耗内力，但在技能持续期间每秒消耗200点内力，且无法通过普攻和技能恢复内力,技能释放期间，关羽会在敌人之间持续移动",
	["tid#SkillDes_72012"]="等级2：武圣状态期间，关羽会获得20点吸血，期间每有一个队友死亡，还会额外获得5点吸血",
	["tid#SkillDes_72013"]="等级3：武圣状态持续期间获得的伤害减免和伤害提升效果增加至60%",
	["tid#SkillDes_72014"]="等级4：每秒消耗内力减少至150点",
	["tid#SkillDes_72021"]="关羽攻击当前目标，对其造成200%攻击力并附加自身最大生命值5%的外功伤害，并使其进入“震慑”状态2秒，震慑状态期间，敌人无法行动，震慑状态无法被免疫，该技能无视敌方免死效果",
	["tid#SkillDes_72022"]="等级2：伤害提升至220%攻击力，附加伤害提升至7%最大生命值",
	["tid#SkillDes_72023"]="等级3：“震慑”状态持续时间提升至3秒",
	["tid#SkillDes_72024"]="等级4：每次击中敌人，该技能的伤害便会提升10%，冷却时间减少10%，最多叠加5次",
	["tid#SkillDes_72031"]="战斗开始，关羽会获得10层“武圣”效果，每层“武圣”效果，会使自身攻击力增加5%，攻击速度增加5%，当关羽受到致命伤害时，会消耗自身所有“武圣”效果，每层武圣效果会为自身提供1秒无敌效果，一场战斗仅能触发一次",
	["tid#SkillDes_72032"]="等级2：武圣效果提供的攻击力和攻速增加效果提升至增6%",
	["tid#SkillDes_72033"]="等级3：敌人侠客死亡时，关羽会获得2层“武圣”效果，若击杀者为关羽，则获得的层数翻倍",
	["tid#SkillDes_72034"]="等级4：关羽每消耗1层“武圣”便会使的攻击力和攻速增加6%，最多增加60%，该效果会持续到战斗结束",
	["tid#SkillDes_72041"]="当关羽被施加负面状态时，免疫该负面状态并使自身免疫负面状态1秒，每次触发该效果时，关羽还会恢复10%最大生命值，该效果有5秒冷却时间",
	["tid#SkillDes_72042"]="等级2：触发该技能5秒内，关羽受到的伤害减少40%",
	["tid#SkillDes_72043"]="等级3：免疫负面状态的持续时间增加至2秒",
	["tid#SkillDes_72044"]="等级4：恢复的生命值提升至15%",
	["tid#SkillDes_72051"]="汉寿亭侯普攻",
	["tid#SkillDes_72061"]="关羽在原地留下一个残影并暂时脱离战场，随后带领骑兵冲锋席卷战场，对命中的所有敌人造成200%攻击力的伤害和2秒震慑，震慑结束后，还会为敌人施加持续5秒的“xx”状态，使敌人造成的伤害减少30%，冲锋期间关羽处于无敌状态，冲锋结束后关羽会回到原地；",
	["tid#SkillDes_72062"]="等级2：“xx”状态造成的伤害减少效果提升至40%",
	["tid#SkillDes_72063"]="等级3：伤害提升至220%攻击力",
	["tid#SkillDes_72064"]="等级4：释放该技能后，关羽获得2层“忠义”",
	["tid#SkillDes_72071"]="战斗开始时，关羽会获得10层“忠义”效果，每层“忠义”效果会使自身受到的的伤害减少5%，当任意友方侠客受到致命伤害时，关羽便会消耗自身所有“忠义”层数，每消耗一层忠义层数，便会使该队友恢复5%最大生命值的血量和0.5秒的无敌效果，该效果有10秒的冷却时间，只要关羽身上存在“忠义”buff，就不会被魅惑",
	["tid#SkillDes_72072"]="等级2：忠义效果提供的伤害减免增加至6%",
	["tid#SkillDes_72073"]="等级3：我方侠客死亡时，关羽会获得2层“忠义”",
	["tid#SkillDes_72074"]="等级4：关羽每消耗1层“忠义”便会使自身伤害减免增加6%，最多增加60%，该效果会持续到战斗结束",
	["tid#Herolife_720"]="关羽为蜀汉将领，曾被曹操俘获，他舍弃赏赐，千里走单骑继续追随刘备。关羽以武圣之名威震华夏，其忠义气节也成为千古美谈。关羽的一生，正是“仗节气盖世，横槊勇冠军”。手持青龙偃月刀，身披绿袍金铠，令敌人闻风丧胆，是一名前后绝伦的猛将。",
	["tid#Herolegend1_720"]="东汉末年，天下大乱，黄巾四起，刘焉出榜招募义兵，关羽，刘备，张飞，三个只取相投的英雄一见如故，相约结为异性兄弟。三人焚香再拜而说誓曰：“念刘备、关羽、张飞，虽然异姓，既结为兄弟，则同心协力，救困扶危；上报国家，下安黎庶。不求同年同月同日生，只愿同年同月同日死。皇天后土，实鉴此心，背义忘恩，天人共戮！”誓毕，拜玄德为兄，关羽次之，张飞为弟",
	["tid#Herolegend2_720"]="曹操派刘岱、王忠攻打刘备，却被刘备击败，曹操于是亲提大军出征，刘备败逃投奔袁绍，关羽战败被生擒，被带到许都，曹操待以厚礼，任命为偏将军，后来，袁绍派大将颜良攻东郡太守刘延于白马。曹操亲自率军救援。颜良仓促应战。曹操命张辽与关羽为前锋击之。策马冲锋，刺死颜良于万军之中，斩得颜良的首级，然后返还。袁军将领无人能挡，白马之围被解，曹操上表请求汉献帝封关羽为汉寿亭侯。",
	["tid#Herolegend3_720"]="关羽被曹操俘获后，曹操非常欣赏关羽的为人，想要留下关羽。叫张辽以私人感情来试探关羽。关羽对张辽叹息道：“我知道曹公对我的厚爱，但我受刘备将军的厚恩，发誓共死，不可背弃。我终不会留下，在为曹公立下功劳后我便会离去。”关羽为曹军斩杀了颜良之后，关羽将曹操的赏赐全部封存，留书告辞，回到刘备身边",
	["tid#Herolegend4_720"]="孙权知道刘备已夺得益州，希望取回荆州。刘备却说：“当得到凉州时，便会把荆州交还。”孙权对此十分怨恨，便派鲁肃索要荆州关羽为了荆州之事只身过江，与鲁肃会面。鲁肃，周仓步步紧逼想要蜀汉交还荆州。关羽于是变色而起，从周仓手中夺过大刀，右手提刀，左手挽住鲁肃手，勃然怒斥，”鲁肃被他一提，挣脱不得，早已吓得魂不附体，暗藏的刀斧手也只好望洋兴叹",
	["tid#Herolegend5_720"]="关羽奉命进攻樊城，听说曹兵移到城北驻扎，关羽不知何意，骑马登高观望，看到北山谷内人马很多，又见襄江水势汹猛，水淹七军之计，油然而生。遂急命部下准备船筏，收拾雨具，又派人堵住各处水口。这天夜里，风雨大作，曹军在帐中，只听万马奔腾，喊声震天。出帐一看，大水从四面急剧涌来。七军兵士随波逐浪，死伤无数。幸存士兵登上小土山躲避，关羽带大军冲杀而来，将其团团围住，战不多时，曹军士兵全都投降",
	["tid#herolegend6_720"]="关羽领兵出征在外时，孙权暗中派人去诱降关羽部下糜芳、傅士仁，又命吕蒙为主帅，偷袭荆州。孙权亲自率军为后援，麋芳和傅士仁果然不战而降，南郡陷落。关羽带着仅剩的三百人马来到了麦城。关羽向刘备求救。但是，刘备远在西川，救兵无法及时到达，而刘封、孟达见死不救。关羽无奈突围，结果遭到了东吴将领潘璋、朱然等人的埋伏。关羽被东吴擒获",
	["tid#herolegend7_720"]="孙权将关羽首级送给曹操，曹操以诸侯之礼将其安葬于洛阳，孙权则将关羽身躯以诸侯礼安葬于当阳，蜀汉在成都为关羽建衣冠冢以招魂祭祀，蜀汉后主刘禅在追谥追谥关羽为“壮缪侯”。",
	["tid#poetry_720"]="心若素水清\\n  山崩亦无惊\\n 本来无一物\\n  何惧世无名",
	["tid#herounlockedsaying_249"]="一颗……两颗……啊？怎么了？",
	["tid#herounlockedsaying_250"]="你……可以叫我廿四……",
	["tid#herounlockedsaying_251"]="又有新的任务了吗？",
	["tid#EquipAffixDes1311"]="核心：汉寿亭侯装备时，受治疗效果提升15%，防御提升10%核心：绛衣军装备时，攻击速度提升12，外伤加深提升5%",
