	["tid#SkillName_71574"]="极·笔落风雨（等级4）",
	["tid#SkillDes_71561"]="李白解放剑仙之力，召唤10把飞剑，攻击随机敌人，每把飞剑都会对敌人造成100%攻击力的伤害，飞剑可以攻击同一个敌人，当一个敌人被飞剑连续命中3次时，会额外受到一次150%攻击力的真实伤害并被眩晕2秒",
	["tid#SkillDes_71562"]="等级2：敌人每受到一次飞剑伤害，则下次受到的飞剑伤害就会增加10%，最多增加60%",
	["tid#SkillDes_71563"]="等级3：诗仙状态叠加至5层以上时，额外增加5把飞剑",
	["tid#SkillDes_71564"]="等级4：诗仙，酒气和剑气叠加至7层以上时，额外增加5把飞剑",
	["tid#SkillDes_71571"]="李白每次对敌人造成伤害时，都会为自身施加一层“诗仙”状态，诗仙状态也会被视为“诗气”状态，每层诗仙状态会使自身的外功伤害提升5%，最多叠加10层，当自身受到致命伤害时，若自身存在诗仙状态，则会消耗所有诗仙状态免疫本次伤害，使自身无敌2秒，且每有一层“诗仙”状态，都会为自身恢复5%最大生命值的血量，该效果有10秒冷却时间",
	["tid#SkillDes_71572"]="等级2：当诗仙状态叠加至5层时，李白造成的所有伤害都会无视敌方闪避值",
	["tid#SkillDes_71573"]="等级3：诗仙状态叠加至10层时，李白会在之后的5秒内无视敌方50%防御和伤害减免，该效果无法叠加",
	["tid#SkillDes_71574"]="等级4：战斗开始时，李白会获得3层“诗仙”状态",
