	["tid#SkillName_71964"]="极·槊锋飞火（等级4）",
	["tid#SkillDes_71911"]="花木兰挥舞马槊在自身周围布下飞火战阵，战阵会跟随花木兰移动，花木兰受到来自战阵以外的内功伤害会减免100%，受到的来自战阵以内的所有伤害会减少50%；释放该技能时不会消耗内力，而是会在战阵持续期间，每秒消耗200点内力，当内力消耗完时，技能效果结束；战阵持续期间，花木兰无法通过自身以外的手段恢复内力",
	["tid#SkillDes_71912"]="等级2：当花木兰处于战阵中时，会获得30%攻速和攻击力提升",
	["tid#SkillDes_71913"]="等级3：来自战阵以外的外功伤害也会减少50%",
	["tid#SkillDes_71914"]="等级4：每秒消耗的内力缩减至150点",
	["tid#SkillDes_71921"]="花木兰快速攻击当前目标三次，每次造成120%攻击力的伤害，最后一击还会额外附加5%敌方最大生命值的伤害并使其攻击力降低20%，持续5秒",
	["tid#SkillDes_71922"]="等级2：伤害提升至140%攻击力",
	["tid#SkillDes_71923"]="等级3：若是在飞火战阵中释放该技能，则该技能的最后一击伤害会翻倍且会使敌人眩晕2秒",
	["tid#SkillDes_71924"]="等级4：攻击力降低效果提高至30%",
	["tid#SkillDes_71931"]="战斗中，若花木兰攻击范围内没有敌人，则会强制选取在场攻击力最高的一名敌方侠客，将其拉到自己攻击范围内，并立即对其造成200%攻击力的伤害和2秒沉默效果",
	["tid#SkillDes_71932"]="等级2：该技能还会为敌人施加持续5秒的“挑衅”状态，处于该状态的敌人的攻击目标会强制转换为花木兰，且该状态无法被免疫",
	["tid#SkillDes_71933"]="等级3：伤害提升至240%攻击力",
	["tid#SkillDes_71934"]="等级4：处于“挑衅”状态的敌人造成的伤害会降低30%",
	["tid#SkillDes_71941"]="战斗中，花木兰每次对同一目标造成伤害时，便会为自身增加一层“红裳”效果，持续8秒，每层红裳效果会为自身增加10%攻击力和5%伤害减免，最多6层",
	["tid#SkillDes_71942"]="等级2：当花木兰受到致命伤害时，会立即消耗自身所有的“红裳”效果，获得6秒无敌效果，且每消耗一层“红裳”效果自身恢复10%最大生命值的血量，该效果每场战斗仅能触发一次",
	["tid#SkillDes_71943"]="等级3：战斗开始时，花木兰会立刻获得一层“红裳”效果",
	["tid#SkillDes_71944"]="等级4：每层红裳效果提升的攻击力提升至12%，6%伤害减免",
	["tid#SkillDes_71951"]="绛衣军普攻",
	["tid#SkillDes_71971"]="战斗开始时，花木兰会立即冲至与自己位置相对的敌人身后，随后对其造成200%攻击力的伤害和持续2秒的沉默效果",
	["tid#SkillDes_71972"]="等级2：被命中的敌人受到的伤害会增加20%，持续5秒",
	["tid#SkillDes_71973"]="等级3：伤害提升至240%攻击力",
	["tid#SkillDes_71974"]="等级4：敌人伤害增加的效果提升至30%",
	["tid#SkillDes_71961"]="花木兰立即冲至当前血量最低的敌人身后，对其造成300%攻击的伤害，为其施加“破虏”标记，持续5秒，之后使自身进入“巾帼”状态，持续5秒，巾帼状态持续期间花木兰会获得30%的攻击力和攻速提升，且除被施加了破虏标记的敌人以外，其他所有敌人都无法对花木兰造成伤害，破虏状态持续期间若敌人死亡，则破虏标记会转移至另外一个随机敌人，持续时间保留",
	["tid#SkillDes_71962"]="等级2：伤害提升至320%攻击力",
	["tid#SkillDes_71963"]="等级3：破虏标记和巾帼效果的持续时间提升至8秒",
	["tid#SkillDes_71964"]="等级4：花木兰活动的攻击力和攻速提升提高至40%",
	["tid#Herolife_719"]="替父从军的巾帼英雄，从一心复仇的无名小卒一路成长为忠义仁德的女将军。阵前擂鼓，领兵杀敌；红梅簪发，血做胭脂。长久的征战令她难以摆脱其带来的梦魇，但守护天下安康的信念支撑着她踏上沙场，一往无前。",
	["tid#Herolegend1_719"]="柔然入侵，木兰丧亲。木兰年幼时随父亲花弧，母亲袁氏于虞城居住。长姐花木莲不美好的婚姻让小木兰不愿意出嫁，整日跟随作为后备役军官的父亲习武，彼时木兰羡慕将军的威风，向往成为一名意气风发的真将军。花弧只认为是女儿的戏言，没有关注到天赋极高的小木兰，而寄希望于幼弟花雄。然而一次骑射的失误让花雄的双腿再也不能站起，花雄的性格开始变得内向，整日在房中读书，只愿意同木兰说话。柔然入侵时木兰出城狩猎，躲过一劫。赶回城中早已哀鸿遍野，房屋尽数被烧毁，木兰也因此没能救出双腿残疾的弟弟。自此，复仇的种子在木兰心中埋下。",
	["tid#Herolegend2_719"]="贺氏征兵，利箭识胆。 木兰在城外安葬父母和弟弟时，听闻朝廷派贺廷玉将军出征。木兰女扮男装混入队伍，借用弟名“花雄”成功入选。贺廷玉为人正直，骁勇善战，因战役损失了一名主将，正欲寻找英勇非凡的战士担任战前擂鼓的重任。原本木兰清瘦非常，不在预选名单，但她“红裳玉面少年郎”的外表给贺廷玉留下了深刻的印象，木兰的男装让他想起来早年前在战争中去世的独子贺骁。选拔时众将原本不看好瘦弱的木兰，但木兰凭借出众的骑射脱颖而出。最后贺廷玉弯弓搭箭，士兵们面对锋利的剑刃均眼神躲闪，唯有木兰不惧，目光灼灼犹如虎豹，一向看重将领胆识的贺廷玉当即选中了木兰。",
	["tid#Herolegend3_719"]="再遇少年，首战失利。 木兰得了军中主将的位置，她碍于女儿身一直独来独往，拨给她差遣的士兵并不认可这名小将军，其他主将也以为她骄纵，对她百般刁难。木兰在军中遇到了年少时倾慕她的同乡刘忠，彼时对方已是贺廷玉的副将。二人的重逢并没有让木兰开心，因为刘忠一心想要保护花木兰的安危，想要将她送出军营，二人为此争执，不欢而散。行军三月，木兰参加了第一次战争，贺廷玉溺爱的小女儿贺敏被柔然人捉住。两军借此开战，木兰一袭红裳在两军阵前擂鼓，身形瘦弱，战鼓却在她手下有震天之势。木兰被派去营救贺敏，潜入营帐后木兰顺利带出贺敏，却不料被偷袭，木兰才意识到自己无法做到杀人，幸好刘忠及时策马赶到，避免了惨重的伤亡。",
	["tid#Herolegend4_719"]="结识千金，拜师贺氏。 木兰回到军中遭受贺廷玉的重罚，对方完全把她当成了贺骁那样严格对待。但贺敏却爱上了这位孤身救她的将士“花雄”，撒娇求情地为木兰免去了不少惩罚。木兰因这场战争的失利，不仅在军中更加遭受排挤，就连她自己也开始怀疑自己是否真的能完成“复仇”。贺廷玉主动找到木兰，愿意将武艺传授于她，不止是因为贺敏的求情，更是因为贺廷玉心中不愿意见到她也像贺骁那样命丧沙场。在亲传武艺时，贺廷玉愈发意识到木兰的“软弱”，她能不顾自己的性命，却无法动手抹杀别人。贺廷玉为此设计，在木兰熟睡时放走了先前抓获的柔然间谍，果不其然，那间谍摸进木兰帐中行刺，而彼时木兰已经日日遭受梦魇折磨，精神濒临崩溃。就这样，次日清晨贺敏来探望，才看到在溅满血泊的床前独坐了一夜的木兰，和早已经没有气息的柔然间谍。",
	["tid#Herolegend5_719"]="赈灾救济，心向百姓。 间谍之事后，木兰疏远了贺廷玉，不再同他习武。贺廷玉见木兰软弱，并非心中的可塑之才，无法成为第二个贺骁，便撤了木兰的将领之位，派她去十里外的难民营协助赈灾。在与难民相处中，木兰才意识到了战争的本质，她不再是意气风发的小将军，只是一名普通的士卒。在这里她见到了无家可归的孩提，瘦如枯骨的老妪，这里没有粮食便分食同伴，没有水喝便饮用泥汤。木兰终于明白了花雄曾和她说“战争之事，并非你杀我打，它是无奈之举，是穷百姓，是损天下。”，于是木兰不再只关注能从战争中得到复仇的机会，她发觉真正的仇是战争、是她抵死相拼的命运。彼时刘忠也带着贺敏来到了难民营，贺敏自从知道木兰受梦魇困扰，便为她找来了故乡的红梅做安神香粉，贺廷玉又因贺敏的一句“你不过是放不下对哥哥的愧疚”而重新思考起自己对木兰的态度，命刘忠带着贺敏前来接走木兰。木兰终于决定堂堂正正走向战场，从一个士卒做起。临行前满营百姓争相拉住她的手，挥泪相送。刘忠也意识到木兰并非是为复仇或是为功名，她会成为一个爱戴百姓的好将军，这无关于她是不是女子。",
	["tid#herolegend6_719"]="识破真身，孤身救帅。 回营途中一切顺畅，木兰也凭着贺敏带回的红梅香粉安然入睡，却因整日劳累在临营地半日路程时候熟睡过去，任谁都喊不醒。贺敏原本打算叫醒木兰，却意外发现这位”花雄将军“是一位女子。贺敏顿时羞愤，折断了赠予木兰的红梅先行离去。刘忠无奈带队前去追赶，然而却碰上了柔然部队偷袭军营。两方交战，贺廷玉的军队损失惨重。木兰在梦中见到了父母和弟弟，许是命运的眷顾，弟弟指引她从牢笼般的梦境中解脱。木兰披上铠甲，不再掩饰女子身份，头簪红梅，持马槊杀入敌阵，孤身救出贺廷玉。随后带领剩余部下，亲自指挥作战，扭转局势，一战成名。",
	["tid#herolegend7_719"]="不向庙堂，只向天下。 贺廷玉领兵大胜，班师回朝后贺廷玉亲自举荐了木兰。皇帝要给木兰封赏，加官进爵。但木兰婉拒，并亲自登门向贺廷玉和贺敏请罪，坦白了自己的身份。贺廷玉先是震惊，却并不恼怒，原来是贺敏早已和他说明了木兰的身份，并替她求情，且愿意与木兰结为姐妹。“我知道，你更需要一个家。”贺敏派人从后院递来一枝红梅，她赞叹木兰身为女子却敢破囹圄的胆识，决定此后云游四海，为流民疗伤治病。刘忠也不再自私地执着于同木兰年少时的情感，他领命前往边关驻守，与木兰阔别。而花木兰也终于以女将军的身份踏上沙场，她会继续坚守自己心中的正道，为家国天下，黎民百姓寻求安宁。",
	["tid#Heroclass_722"]="孙尚香",
	["tid#HeroName_722"]="枭姬祠",
	["tid#poetry_722"]="吴蜀成婚此水浔\\n 明珠步障屋黄金\\n 谁知一女轻天下\\n 欲易刘郎鼎峙心",
	["tid#SkillDes_72211"]="孙尚香进入狂暴状态，狂暴状态下，角色降无法移动，免疫控制效果，且只能使用普通攻击；状态持续期间，十二连环坞的攻击力提升50%，攻击速度提升50%，每次普攻会附带目标2%的最大生命值伤害，且每秒会消耗120点内力，当内力消耗完时，狂暴状态结束",
	["tid#SkillDes_72212"]="攻速和攻击力提升至60%",
	["tid#SkillDes_72213"]="每次普攻附带3%最大生命值伤害",
	["tid#SkillDes_72214"]="每秒消耗内力减少至100点",
	["tid#SkillDes_72221"]="孙尚香每释放三次普攻，便会释放一记强力普攻，强力普攻便会攻击所有敌方单位，并额外附加命中单位8%最大生命值的伤害",
	["tid#SkillDes_72222"]="每次释放完强力普攻后，十二连环坞的攻速便会增加30%，持续5秒",
	["tid#SkillDes_72223"]="强力普攻的伤害提升30%",
	["tid#SkillDes_72224"]="强力普攻将必定暴击",
	["tid#SkillDes_72231"]="战斗中，每过去15秒，孙尚香会获得一个护盾，当受到攻击时，抵挡本次伤害，护盾随后爆炸，对自身周围的敌人造成200%攻击力的伤害并使其眩晕2秒",
	["tid#SkillDes_72232"]="护盾爆炸后3秒内孙尚香不会死亡",
	["tid#SkillDes_72233"]="生成护盾的cd缩短至12秒",
	["tid#SkillDes_72234"]="每次释放绝技时，都会刷新护盾的cd",
	["tid#SkillDes_72241"]="孙尚香向前发射一枚炮弹，对范围内的敌人造成200%攻击力的伤害并施加“复仇”标记，持续15秒，并使其受到的伤害增加20%",
	["tid#SkillDes_72242"]="伤害提升至220%攻击力",
	["tid#SkillDes_72243"]="十二连环坞的普攻将对被标记敌人额外造成一次伤害",
	["tid#SkillDes_72244"]="伤害提升至240%攻击力",
	["tid#SkillDes_72251"]="孙尚香普攻",
	["tid#SkillDes_72261"]="孙尚香射出三波巨大的箭矢，对所有敌人造成三次伤害，受到伤害的敌人会进入【定魂】状态，无法使用技能，持续3秒",
	["tid#SkillDes_72262"]="伤害提升至250%",
	["tid#SkillDes_72263"]="敌人每次受到时会被孙尚香吸收20点内力",
	["tid#SkillDes_72264"]="【定魂】效果延长至4秒",
	["tid#SkillDes_72271"]="对攻击力最高的敌人释放连续强烈的攻击，此次攻击会驱散目标身上的护盾效果",
	["tid#SkillDes_72272"]="伤害提升至240%",
	["tid#SkillDes_72273"]="可以驱散目标身上的无敌效果",
	["tid#SkillDes_72274"]="冷却时间缩短至8秒",
	["tid#itemName2721"]="天香阁结缘碎片",
	["tid#itemDes2721"]="集齐60个可立即获得侠客天香阁",
	["tid#poetry_721"]="美目盼兮夺花颜\\n  长歌万里迎春暖\\n  娇云无形有真意\\n  天香掩容展才情。",
