	["tid#SkillName_72164"]="极·百花绽放（等级4）",
	["tid#SkillDes_72111"]="小乔施展花神之力，使所有友方侠客获得持续2秒的“赐福”效果，处于赐福效果的侠客受到的伤害会强制降为0点，“赐福”效果结束时，所有侠客还会获得1个持续6秒的“回春”效果，处于回春效果的侠客受到的伤害减少40%，且每秒会恢复100%小乔攻击力的血量，处于“回春”效果的侠客无法再被施加“赐福”效果",
	["tid#SkillDes_72112"]="等级2：赐福效果的持续时间提升至3秒",
	["tid#SkillDes_72113"]="等级3：恢复的血量提升至120%攻击力",
	["tid#SkillDes_72114"]="等级4：伤害减免效果提升至50%",
	["tid#SkillDes_72121"]="小乔施展恢复之力，为所有己方侠客恢复200%攻击力的血量，血量百分比低于50%的侠客收到的恢复效果会翻倍，若治疗效果溢出，则溢出部分的20%会转化为友军的最大生命值加成，持续到战斗结束",
	["tid#SkillDes_72122"]="等级2：受到恢复效果的友军还会获得30%的攻击力提升，持续5秒",
	["tid#SkillDes_72123"]="等级3：溢出治疗效果的转化比例提升至25%",
	["tid#SkillDes_72124"]="等级4：溢出治疗效果的转化比例提升至30%",
	["tid#SkillDes_72131"]="战斗开始时，小乔会在我方阵营中布下“天香领域”，处于天香领域中的友方侠客，最大血量提升30%，防御力提升50%，处于天香领域中的侠客在受到攻击时，受到的伤害会被“吸收”20%，天香领域会在小乔死亡时消失（吸收：计算伤害时，会先计算吸收值，再计算伤害减免），若周瑜存在与天香领域中，则周瑜获得的增益效果不会消失",
	["tid#SkillDes_72132"]="等级2：最大血量提升至40%，防御力提升至60%",
	["tid#SkillDes_72133"]="等级3：天香领域的吸收效果增加至30%",
	["tid#SkillDes_72134"]="等级4：小乔死亡时，天香领域依然会存在6秒",
	["tid#SkillDes_72141"]="处于天香领域中的每个友方侠客都会为小乔提供10%的伤害减免，当小乔受到致命伤害时，若天香领域中存在其他友军，则小乔会免疫本次伤害且每存在1个友军，小乔便会获得1秒无敌效果；若天香领域中存在周瑜，则小乔还会立即将生命值恢复至满血，改技能1场战斗中仅能触发1次",
	["tid#SkillDes_72142"]="等级2：每个友军为小乔提供的伤害减免提升至15%",
	["tid#SkillDes_72143"]="等级3：触发该技能时，天香领域中友军会立即将攻击目标转移至攻击者，且攻速增加30%，持续5秒",
	["tid#SkillDes_72144"]="等级4：触发该技能时，天香领域中友军会立即将攻击目标转移至攻击者，且攻速增加40%，持续5秒",
	["tid#SkillDes_72151"]="小乔普攻",
	["tid#SkillDes_72171"]="小乔施展虚弱，为随机2名敌方侠客施加“虚弱”效果，被虚弱的敌人攻击速度会降低30%，攻击力会降低30%，持续5秒",
	["tid#SkillDes_72172"]="等级2：被施加虚弱的敌人还会降低30%的内力恢复效果",
	["tid#SkillDes_72173"]="等级3：持续时间提升至6秒",
	["tid#SkillDes_72174"]="等级4：攻速和攻击降低效果增加至40%",
	["tid#SkillDes_72161"]="小乔施展枯萎之力，为敌方当前攻击力最高的敌人施加枯萎，使其造成的所有伤害强制降为0点（对首领单位无效），持续4秒，被施加了枯萎的敌人在枯萎结束后8秒内，无法被再次选择为枯萎目标，且造成的伤害会降低20%",
	["tid#SkillDes_72162"]="等级2：枯萎效果的持续时间提升至5秒",
	["tid#SkillDes_72163"]="等级3：被枯萎的敌人受到的伤害还会增加20%",
	["tid#SkillDes_72164"]="等级4：被枯萎的敌人受到的伤害还会增加30%",
	["tid#Herolife_721"]="世人说乔氏有二女，天仙之貌，小乔正是其中之一，她与姐姐大乔分别嫁给周瑜，孙策二人，希望战乱可以休止，天下重回一统。",
	["tid#Herolegend1_721"]="烂漫闺阁：小乔与姐姐大乔的童年是格外幸福的，父亲桥蕤是赫赫有名的将军，又与母亲琴瑟和鸣，姐妹俩备受宠爱。小乔喜欢赏花，父亲便命人在自家院子中开辟出一角，专门为她栽种各色花朵。与娴静腼腆的姐姐不同，小乔机灵热情，总拉着姐姐一同去街上看热闹。",
	["tid#Herolegend2_721"]="战火初燃：汉氏王朝一朝倾颓，天下大乱。桥蕤选择了袁术，于是他带着全家人一起追随了袁术，四处征战。小乔一路所见，皆是百姓流离失所，骨肉分离之苦，她由衷感受到过去的美好，从而希望父亲能在袁术的带领下让天下重新恢复太平。",
	["tid#Herolegend3_721"]="乍见之欢：桥蕤一家本来都将天下复兴希望寄托于袁术身上，可袁术却逐渐显露出他浅薄短视的一面，袁术不但自大傲慢，甚至还对他的部将们和家人出言不逊，二乔也不堪其扰。一日，小乔偶然看见一位风度翩翩的公子拜见袁术，那人与她遥遥一望便离开了。正在小乔好奇之时，父亲告诉她那是周瑜，特来向袁术请辞。她看着父亲对周瑜欣赏的眼神，心下明白父亲恐怕早有离开袁术投奔孙策之意了。",
	["tid#Herolegend4_721"]="鼓角连天：桥蕤还未找到时机带着家人离开袁术，就因为袁术的指挥失利战死在沙场上。小乔与姐姐一同照顾着生病的母亲，可惜天不遂人愿，母亲经受不住父亲战死的消息，最终撒手人寰。她默默将这种痛苦记在心中，发誓有朝一日必要向袁术报仇。",
	["tid#Herolegend5_721"]="重逢之喜：袁术接连战败，他带着家眷和部将们一并逃到皖城，小乔与大乔也在其中。几个月后，皖城也被攻破，袁术与其心腹败走，留下了一众家眷在城中惶惶不可终日。大军进城了，有几位将士找到了她们的藏身之处，小乔仔细一看才发现——正是之前与她遥遥对望的玉面郎君周瑜和一位年轻爽朗的将军孙策。孙策惊叹于大乔娴静如水的姿容，当即便纳其为内室，又笑着劝周瑜一并纳了小乔。见周瑜的表情并未有太大波澜，小乔内心的喜悦又多了几分酸楚。",
	["tid#herolegend6_721"]="情投意合：成婚之后，小乔与周瑜一直相敬如宾，二人未曾提起之前的相遇，也并未体会到夫妻之间的爱情。直到某次见到他人献上的名贵花卉勾起小乔的忧思，在周瑜再三追问下，她吐露真情，更诉说了自己对于天下统一的心愿与畅想。周瑜从此对小乔另眼相看，真正为其倾心，二人琴瑟和鸣。",
	["tid#herolegend7_721"]="痛失所爱：小乔与周瑜相伴仅仅十年，周瑜便因病去世，小乔便留在庐江当地，抚养二人的孩子。在孩子的牙牙学语中，她将夫妻二人的理想与希望，对于天下复兴的热忱都一并传授给了年幼的孩子。",
	["tid#herounlockedsaying_252"]="繁华盛景，才是天下太平之像呀。",
	["tid#herounlockedsaying_253"]="我曾与家人们在战乱中奔波，因此更能懂得和平的珍贵。",
	["tid#herounlockedsaying_254"]="百花盛开之日，想必天下已合为一统了吧。",
