	["tid#SkillName_72374"]="极·火烧赤壁（等级4）",
	["tid#SkillDes_72311"]="周瑜施展烈火焚烧所有敌人，每秒造成140%攻击力的伤害，持续4秒，若命中的敌人身上有“引燃”或“焚烬”状态，则每次造成伤害时，还会造成爆炸，对范围内的敌人额外造成1次伤害",
	["tid#SkillDes_72312"]="等级2：焚烧伤害和爆炸伤害提升至150%攻击力",
	["tid#SkillDes_72313"]="等级3：命中的敌人身上若有“引燃”或“焚烬”状态，则每次造成伤害还会使其眩晕1秒",
	["tid#SkillDes_72314"]="等级2：焚烧伤害和爆炸伤害提升至160%攻击力",
	["tid#SkillDes_72321"]="被【铁锁连环】命中的敌人，将被施加1层持续8秒的“引燃”状态，引燃状态下的敌人，每秒会受到50%攻击力的伤害，且内伤减免会降低10%，引燃状态最多可以叠加3层。当引燃状态叠加至3层时，若再次被施加引燃效果时，则会立即清除敌人身上所有引燃状态并升级为“焚烬”状态，每秒会造成200%攻击力的伤害，内伤减免降低50%，且无法恢复内力，持续5秒，焚烬状态持续期间，敌人无法再被施加引燃状态。",
	["tid#SkillDes_72322"]="等级2：引燃状态伤害提升至70%攻击力",
	["tid#SkillDes_72323"]="等级3：焚烬状态伤害提升至280%攻击力，焚烬状态下，敌人每秒还会减少20点内力",
	["tid#SkillDes_72324"]="等级4：普攻也有30%的概率对目标施加“引燃”效果",
	["tid#SkillDes_72331"]="周瑜召唤火鸟攻击敌人，火鸟会在敌人之间随机弹射1次，对命中的敌人造成160%攻击力的伤害，若命中的敌人身上已有“引燃”或者“焚烬”状态，则火鸟在命中敌人时还会造成1次爆炸，对范围内的敌人额外造成1次伤害",
	["tid#SkillDes_72332"]="等级2：弹射次数增加至2次",
	["tid#SkillDes_72333"]="等级3：冷却时间降低2秒",
	["tid#SkillDes_72334"]="等级4：弹射次数增加至3次",
	["tid#SkillDes_72341"]="战斗开始时，若周瑜位置相对的敌人为敌方攻击力最高的侠客，则会为敌方攻击力最高的侠客施加“策反”状态5秒，被策反的侠客会转而攻击自己的友军，但无法使用必杀技，策反成功后，周瑜会获得30%的攻击力和攻速提升，直到战斗结束；若周瑜位置相对的敌人不是敌方攻击力最高的侠客，则周瑜会对位置相对的敌人造成200%攻击力的伤害，并使其眩晕3秒；若场上存在小乔，小乔会对相对位置的敌人也释放该技能。",
	["tid#SkillDes_72342"]="等级2：策反成功后获得的攻速和攻击力提升增加至40%",
	["tid#SkillDes_72343"]="等级3：策反失败也会增加20%的攻击力和攻速",
	["tid#SkillDes_72344"]="等级4：策反失败造成的伤害提升至240%",
	["tid#SkillDes_72351"]="周瑜普攻",
	["tid#SkillDes_72361"]="每次有敌人被施加“引燃”状态，周瑜便会获得【英姿】效果，每层3%的内力恢复速度和攻击速度提升效果，最多叠加8层，英姿效果会持续到战斗结束，当受到致命伤害时，周瑜会免疫本次伤害，并依照当前【英姿】的层数，每层无敌0.3秒，触发无敌后，【英姿】效果将被清除，无敌效果每场战斗只能触发一次。",
	["tid#SkillDes_72362"]="等级2：【英姿】效果叠加层数最高为12层",
	["tid#SkillDes_72363"]="等级3：每层英姿无敌的效果提高至0.5秒",
	["tid#SkillDes_72364"]="等级4：若队伍内存在小乔，则周瑜在战斗开始时，将获得4层英姿效果，小乔死亡时，周瑜将立即获得最高英姿层数，并回复所有生命值。",
	["tid#SkillDes_72371"]="周瑜对随机2名敌人造成280%攻击力的伤害，使其眩晕2秒并立即进入“极·焚烬”状态，每秒会造成350%攻击力的伤害，内伤减免降低50%，且无法恢复内力，持续4秒。该状态结束时，会额外造成一次爆炸，对周围的敌人造成200%攻击力的伤害。",
	["tid#SkillDes_72372"]="等级2：技能伤害提升至300%攻击力",
	["tid#SkillDes_72373"]="等级3：被“极·焚烬”爆炸命中的敌人，还会眩晕2秒",
	["tid#SkillDes_72374"]="等级4：若队伍内存在小乔，极·焚烬 状态下还会每秒额外造成3%最大生命值的伤害。",
	["tid#Herolife_723"]="他出生于一个书香门第，自幼聪颖过人，善于文武，精通音律，擅长诗词。年轻时，他曾经拜在名将孙策门下，随孙策征战四方，立下了赫赫战功，成为名副其实的一代名将。",
	["tid#Herolegend1_723"]="伯牙子期：周瑜与孙策是挚友，孙坚兵讨董卓时，家小移居舒县，孙策和周瑜同岁，交往甚密，周瑜让出路南的大宅院供孙家居住，且登堂拜见孙策的母亲，两家互通有无。",
	["tid#Herolegend2_723"]="良禽择木：袁术赏识周瑜的才干，想任命他担任手下的将领。周瑜对袁术的目光短浅、骄横无知，十分鄙视， 所以只请求做居巢县长，欲借机回江东，袁术同意了周瑜的请求。",
	["tid#Herolegend3_723"]="郎才女貌：建安四年孙策要攻打荆州，拜周瑜为中护军，兼任江夏太守，随军征讨。十二月，孙策带领周瑜等人攻破皖城，虏获袁术手下刘勋家人及他们部下的男女亲族，其中桥公二女皆国色天姿，孙策自纳大乔，周瑜纳小乔。",
	["tid#Herolegend4_723"]="安邦重臣：建安五年四月，孙策遇刺身亡，临终时把军国大事托付给孙权。孙权统业时，年龄尚小，只有寥寥数郡，其偏远险要之处也尚未全附。天下英雄豪杰散在各个州郡，并未和孙氏建立起君臣之间相互依赖的关系。周瑜从外地带兵前来奔丧，留在吴郡孙权身边任中护军，同长史张昭共同掌管军政大事。",
	["tid#Herolegend5_723"]="力排众议：建安十三年，曹操率军南侵，占领荆州，向东吴进逼。大军压境之际，孙权的大臣们大多建议投降曹操。周瑜从多个角度驳斥主和派，让孙权下定决心与曹操决一死战，任命周瑜为主帅，率兵与刘备合力迎战曹操。",
	["tid#herolegend6_723"]="赤壁之战：孙刘联军与曹军在赤壁相遇，曹操为了北方士卒习惯坐船，将舰船首尾连接起来，人马于船上如履平地。周瑜采用部将黄盖的火攻之计，命其率小战船十艘，上装柴草，灌以膏油，假称投降，向北岸而进，至离曹营二里之处时，各船一齐点火，然后借助风势，直向曹军冲去，曹军大败。",
	["tid#herolegend7_723"]="天妒英才：建安十五年，孙权批准了周瑜提出征伐益州的战略方案，周瑜返回驻地江陵，行至巴丘路染疾病，不幸病卒，年仅三十六岁 。周瑜临终时上表孙权说：“人生有死，修短命矣，诚不足惜，但恨微志未展，不能再为东吴效命了”，孙权听闻周瑜病逝悲伤不已，亲自穿上丧服为周瑜举哀。",
	["tid#herounlockedsaying_255"]="灰飞烟灭...哼，不过弹指一挥间罢了。",
	["tid#herounlockedsaying_256"]="琴声能抚平人心，亦能摧毁神智。",
	["tid#herounlockedsaying_257"]="英雄乐于效力，应当心系天下，清除曹贼！",
	["tid#EquipAffixDes3112"]="核心：平虏伯装备时，攻击速度提升16，内伤加深提高6%",
