	["tid#itemDes2801"]="集齐60个可立即获得侠客神·九黎",
	["tid#poetry_801"]="余处幽篁不见天\\n  倏来如月去如烟\\n却是能知春信息\\n  惟伴狸奴附日眠",
	["tid#Heroclass_801"]="筱九",
	["tid#HeroTypeDes_801"]="职业:术士   装备:布甲",
