	["tid#SkillName_80151"]="九黎普攻",
	["tid#SkillName_80161"]="灵之迅捷（等级1）",
	["tid#SkillName_80171"]="灵之复苏（等级1）",
	["tid#SkillDes_80111"]="驱散所有敌人的无敌效果，对所有敌人造成300%的伤害和2秒眩晕。并为自己附加“祈灵”状态，持续10秒，祈灵状态下，神·九黎 技能获得增强。“祈灵”状态下再次释放此技能会使技能伤害提高100%",
	["tid#SkillDes_80112"]="等级2：伤害提高至400%",
	["tid#SkillDes_80113"]="等级3：眩晕时间提升至3秒",
	["tid#SkillDes_80114"]="等级4：祈灵状态提高至15秒",
	["tid#SkillDes_80121"]="对一名敌人造成250%伤害和2秒眩晕， 在祈灵状态下，若造成伤害后，目标生命值低于20%，直接将其斩杀",
	["tid#SkillDes_80122"]="等级2：伤害提高至300%",
	["tid#SkillDes_80123"]="等级3：眩晕时间提升至4秒",
	["tid#SkillDes_80124"]="等级4：祈灵状态下，斩杀目标生命值提升至30%",
	["tid#SkillDes_80131"]="召唤幽灵飞雪到场上，飞雪会继承自身70%的属性，并一直存在到战斗结束，飞雪会对附近的敌人发起攻击，并且会分担九黎受到的50%伤害。在祈灵状态下，飞雪和九黎受到的伤害会降低40%，暴击率提高20%",
	["tid#SkillDes_80132"]="等级2：飞雪继承100%的属性，飞雪死亡时，九黎会获得3秒的无敌效果。 ",
	["tid#SkillDes_80133"]="等级3：当九黎受到致命伤害时，飞雪会代替九黎承受此次伤害，每10秒只能触发一次。",
	["tid#SkillDes_80134"]="等级4：飞雪死亡后，九黎会获得50%的攻击力加成，持续到战斗结束，该效果可叠加3次。",
	["tid#SkillDes_80141"]="战斗开始时，九黎会在敌方战场中心位置释放音波，对所有敌人造成200%伤害，并使其内力恢复速度降低50%，持续5秒",
	["tid#SkillDes_80142"]="等级2：伤害提高至240%",
	["tid#SkillDes_80143"]="等级3：内力恢复速度降低的效果持续8秒",
	["tid#SkillDes_80144"]="等级4：受到伤害后的8秒内，还会使敌人受到的伤害提高30%",
	["tid#SkillDes_80151"]="神·九黎普攻",
	["tid#SkillDes_80161"]="飞雪继承150%的属性，攻击速度提高30%",
	["tid#SkillDes_80171"]="飞雪死亡8秒后会以100%的生命，重新进入战场",
	["tid#Herolife_801"]="筱九生在一个很古老的家族，这个家族一直相信万物有灵，敬畏且热爱着世间的一切生命。几百年前，家族为了躲避江湖中的一场祸事，举族搬迁到了云梦山的深处，从此与世隔绝。筱九的父亲是家族的族长，按照惯例，筱九一出生便注定了圣女的身份。",
	["tid#Herolegend1_801"]="从筱九记事起，她便跟着前代圣女学习如何与万灵沟通。所谓万灵，即是万千生灵的集合体，它代表着树木、花草、飞禽、走兽等一切生灵。万灵似乎很喜欢这个小女孩，很轻易地就回应了她的呼唤。在万灵的教导下，她学会了如何与自然中的生灵沟通，如何与她们做朋友。逐渐地，筱九纯净的心灵得到了森林中所有生灵的认可，其中与她最为亲昵的，是一只异色瞳的白猫，筱九给她取名“飞雪”，一直带在身边，但奇怪的是，养了许久，飞雪却始终不见长大。",
	["tid#Herolegend2_801"]="筱九十四五岁的时候，在森林中遇到了史春莲，从史春莲口中，她得知了森林之外还有着很广阔的世界，于是便萌生了离开这个森林的想法。她把这个想法告诉了母亲，但母亲告诉筱九，每一任圣女在长大之后都要被送往族中的圣地——万灵树，从此常伴在万灵身边。筱九想反驳，母亲却第一次斥责了她，并禁止她再外出。被禁足之后，筱九仍会偷偷和史春莲相会，她想把自己的痛苦告诉史春莲，但天性善良的她却不想让史春莲为难。直到十六岁生日的那天，她前去举行圣女的传承仪式，在获取了圣女代代传承的力量之后，她就要前往神树，从此常伴万灵。绝望之际，史春莲突然出现了，大闹了传承仪式，不由分说就拉着她逃离了族中。自此，筱九终于可以看看外面的世界了。",
	["tid#Herolegend3_801"]="其实筱九早就注意到史春莲了，最开始她只是听森林中的动物说，有一位与众不同的女猎手。那个女猎手只捕猎年迈的动物，从不屠宰幼崽。且对待猎物也保持着敬畏和怜悯。筱九虽然不喜欢猎人，但对史春莲这样的还是很好奇的。于是便开始偷偷的观察她，观察了许久之后，她觉得史春莲确实和其他猎人不一样，也慢慢的对她产生了好感。",
	["tid#Herolegend4_801"]="其实史春莲对外面的世界也不是很清楚，毕竟她也只去过周边的一些村镇，但她一贯喜欢摆出无所不知的姐姐做派，面对小妹妹的提问总是不好意思说不知道，于是就瞎编了许多。等到两人真的到了外面的时候，也闹了不少笑话；",
	["tid#Herolegend5_801"]="筱九遇见飞雪的时候是在万灵树，那时她刚从上一任圣女那里学习回来，一出门就看到它蹲在面前。筱九刚准备伸手逗一逗它，它就直接跳到了自己的怀里，并且怎么都不愿意离开筱九，筱九只好带它回家。从此之后，这只小猫就一直跟着筱九。",
	["tid#herolegend6_801"]="游历江湖时也曾听过东海少侠的盛名，但无法想到的是，初次相见竟是被当作“贼人”刀剑相向。彼时史春莲之父身染重病，只有神鹿鹿茸方可根治病症。幸而筱九与万灵心意相通，得神鹿相助解此困局；却不想落在东海少侠眼里，成了谋害神鹿的歹人。筱九也并不知东海少侠的来头，只当他是见利忘义的狩猎者，硬是阴错阳差地打了一架。",
	["tid#herolegend7_801"]="虽然闹了不小的误会，但好在东海少侠知错就改，倾力相助救回了神鹿，筱九便决定，不再与他计较了。况且在他身上，筱九感应到一颗如圣灵般澄澈的内心，这是在离开圣地之后，在人类身上从未见到过的。虽然短暂的相逢转瞬即逝，告别后筱九便随史春莲前往万兽庄救急，但日后江湖总还会相遇的吧，筱九时常这样想着。",
	["tid#EquipAffixDes3113"]="核心：神·九黎装备时，攻击速度提升16，内伤加深提高6%",
	["tid#array_tips_37"]="攻击、防御、生命+30%，减伤+20%",
